// ===== js/config.js =====
// =====================================================================
// CONFIGURAÇÃO: a tela do jogo, os tamanhos e a escala
// =====================================================================

// O canvas é a "tela" onde o jogo é desenhado; ctx é a ferramenta de desenho
// (let, e não const: o visual pixel troca as duas por um instante, ao desenhar o mundo)
let canvas = document.getElementById('jogo');
let ctx = canvas.getContext('2d');

// Faz o canvas ocupar a janela inteira (e se ajustar se ela mudar)
function ajustarTamanho() {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
}
window.addEventListener('resize', ajustarTamanho);
ajustarTamanho();

// Tamanho de um tile (losango) na tela, em pixels
const TILE_LARGURA = 64;
const TILE_ALTURA = 32;

// ESCALA: tudo no jogo é medido em metros reais e convertido para pixels.
// Cada tile representa 2 x 2 metros de chão.
// Na projeção isométrica 2:1, 1 metro na horizontal da tela vale ~22,6 px
// e 1 metro de altura vale ~19,6 px (a altura aparece um pouco achatada).
const METROS_POR_TILE = 2;
const PX_POR_METRO = (TILE_LARGURA / 2) / (METROS_POR_TILE * Math.SQRT1_2); // ~22,6
const PX_ALTURA_POR_METRO = PX_POR_METRO * Math.cos(Math.PI / 6);          // ~19,6

// Atalhos para converter metros em pixels
const altPx = (metros) => metros * PX_ALTURA_POR_METRO;  // altura
const meiaLargPx = (metros) => metros / 2 * PX_POR_METRO; // metade da largura

// Todos os mapas do jogo. Cada arquivo em js/mapas/ adiciona o seu aqui.
const MAPAS = {};

;
// ===== js/idioma.js =====
// =====================================================================
// IDIOMA: o jogo em português ou em inglês
// =====================================================================
// Por dentro, o jogo é todo em português (nomes de itens, missões, flags,
// o jogo salvo). A tradução acontece só no que aparece na tela:
//   - T(texto): devolve o texto no idioma escolhido (js/i18n_en.js tem o
//     dicionário português -> inglês e os "padrões" para textos com números)
//   - tudo o que o canvas escreve (fillText, strokeText, measureText) passa por T
//   - as falas (DIALOGOS) são trocadas uma vez, ao carregar
//   - o HTML (tela inicial, atlas, painéis) é traduzido ao aparecer
// O idioma vem do navegador na primeira vez e fica guardado depois; os botões
// "Português / English" da tela inicial trocam e recarregam a página.
// Assim o jogo salvo vale nos dois idiomas.

const IDIOMAS = ['pt', 'en'];
let IDIOMA = (() => {
  try { const g = localStorage.getItem('montgisard-idioma'); if (IDIOMAS.includes(g)) return g; } catch (e) {}
  return /^pt\b/i.test(navigator.language || 'pt') ? 'pt' : 'en';
})();
document.documentElement.lang = IDIOMA === 'pt' ? 'pt-BR' : 'en';

function trocarIdioma(novo) {
  try { localStorage.setItem('montgisard-idioma', novo); } catch (e) {}
  location.reload();
}

// --- T: o texto no idioma do jogo ---
const _memoT = new Map();
function T(s) {
  if (IDIOMA === 'pt' || typeof s !== 'string' || !s) return s;
  const m = _memoT.get(s);
  if (m !== undefined) return m;
  const r = traduzir(s);
  if (_memoT.size > 20000) _memoT.clear();
  _memoT.set(s, r);
  return r;
}
function traduzir(s) {
  const D = typeof TRADUCAO_EN !== 'undefined' ? TRADUCAO_EN : {};
  if (D[s] !== undefined) return D[s];
  if (!/[A-Za-zÀ-ú]/.test(s)) return s;
  // espaços nas pontas: traduz o miolo
  const t = s.trim();
  if (t !== s) { const tt = t ? traduzir(t) : t; return tt === t ? s : s.replace(t, tt); }
  // partes separadas por " · ": se todas têm tradução, traduz parte por parte
  let porPartes = null;
  if (s.includes(' · ')) {
    const ps = s.split(' · '), ts = ps.map(T);
    porPartes = ts.join(' · ');
    if (ps.every((p, i) => ts[i] !== p || !/[A-Za-zÀ-ú]{2}/.test(p) || /^[A-Z][a-z]+$/.test(p))) return porPartes;
  }
  // nomes de itens montados (base + prefixo + sufixo, raros, gemas)
  if (typeof nomeDeItemEN === 'function') { const n = nomeDeItemEN(s); if (n) return n; }
  // textos com partes que variam (números, nomes): padrões com grupos
  for (const [re, en] of (typeof PADROES_EN !== 'undefined' ? PADROES_EN : [])) {
    const m = s.match(re);
    if (m) return typeof en === 'function' ? en(...m.slice(1).map(T)) : en.replace(/\$(\d)/g, (_, k) => T(m[+k] || ''));
  }
  // partes separadas por " · ": traduz cada uma
  if (porPartes && porPartes !== s) return porPartes;
  return s;
}

// --- o canvas escreve no idioma escolhido ---
if (IDIOMA !== 'pt') {
  const P = CanvasRenderingContext2D.prototype;
  for (const nome of ['fillText', 'strokeText', 'measureText']) {
    const orig = P[nome];
    P[nome] = function (texto, ...resto) { return orig.call(this, T(String(texto)), ...resto); };
  }
}

// --- textos do HTML ---
const _origDoNo = new WeakMap();
function traduzirNo(no) {
  if (IDIOMA === 'pt') return;
  if (no.nodeType === 3) {
    const v = no.nodeValue;
    if (!v || !/[A-Za-zÀ-ú]/.test(v)) return;
    const t = T(v);
    if (t !== v) { _origDoNo.set(no, v); no.nodeValue = t; }
    return;
  }
  if (no.nodeType !== 1 || /^(SCRIPT|STYLE|CANVAS)$/.test(no.nodeName)) return;
  for (const at of ['aria-label', 'title', 'placeholder', 'alt']) {
    const v = no.getAttribute && no.getAttribute(at);
    if (v) { const t = T(v); if (t !== v) no.setAttribute(at, t); }
  }
  for (const f of no.childNodes) traduzirNo(f);
}

// --- dados das falas: troca uma vez (as falas não são usadas como nomes internos) ---
function traduzirFalas() {
  if (typeof DIALOGOS === 'undefined') return;
  for (const conversa of Object.values(DIALOGOS)) {
    for (const fala of Object.values(conversa)) {
      if (!fala || typeof fala !== 'object') continue;
      for (const k of ['texto', 'quem', 'fonte']) if (typeof fala[k] === 'string') fala[k] = T(fala[k]);
      for (const e of fala.escolhas || []) if (typeof e.texto === 'string') e.texto = T(e.texto);
    }
  }
}

// --- seletor na tela inicial ---
function montarSeletorDeIdioma() {
  const rodape = document.querySelector('#inicio .rodape');
  if (!rodape || document.getElementById('idiomas')) return;
  const span = document.createElement('span');
  span.id = 'idiomas'; span.className = 'visuais';
  for (const [id, nome] of [['pt', 'Português'], ['en', 'English']]) {
    const b = document.createElement('button');
    b.className = 'vis' + (IDIOMA === id ? ' ativo' : ''); b.textContent = nome; b.lang = id;
    b.addEventListener('click', () => { if (IDIOMA !== id) trocarIdioma(id); });
    span.appendChild(b);
  }
  rodape.insertBefore(span, rodape.firstChild);
}

document.addEventListener('DOMContentLoaded', () => {
  montarSeletorDeIdioma();
  if (IDIOMA === 'pt') return;
  traduzirFalas();
  document.title = T(document.title);
  traduzirNo(document.body);
  // o que aparecer depois (atlas, cartas do caminho, abertura, avisos em HTML)
  new MutationObserver((mudas) => {
    for (const m of mudas) {
      if (m.type === 'characterData') traduzirNo(m.target);
      else for (const n of m.addedNodes) traduzirNo(n);
    }
  }).observe(document.body, { childList: true, subtree: true, characterData: true });
});

;
