// ===== js/isometria.js =====
// =====================================================================
// ISOMETRIA: conversão entre posições do mundo e da tela
// =====================================================================
// O jogo "pensa" num mundo plano, como uma folha quadriculada vista de cima
// (x para a direita, y para baixo, em tiles). Só na hora de desenhar
// giramos esse mundo 45° e achatamos pela metade.

// Posição do mundo (em tiles) → posição na tela (em pixels)
function mundoParaTela(x, y) {
  return {
    x: (x - y) * (TILE_LARGURA / 2),
    y: (x + y) * (TILE_ALTURA / 2)
  };
}

// Posição na tela (em pixels) → posição do mundo (em tiles). Usada pelo mouse.
function telaParaMundo(telaX, telaY) {
  return {
    x: (telaX / (TILE_LARGURA / 2) + telaY / (TILE_ALTURA / 2)) / 2,
    y: (telaY / (TILE_ALTURA / 2) - telaX / (TILE_LARGURA / 2)) / 2
  };
}

;
// ===== js/mundo.js =====
// =====================================================================
// MUNDO: o mapa atual, colisão e passagens
// =====================================================================

// O mapa onde o jogador está agora. O jogo começa em Ascalão.
let mapaAtual = MAPAS.ascalao;

// Devolve a letra do tile numa posição do mundo. Fora do mapa = muralha.
function tileEm(x, y) {
  const linha = mapaAtual.linhas[Math.round(y)];
  if (!linha) return '#';
  return linha[Math.round(x)] ?? '#';
}

function ehPortal(tile) {
  const p = mapaAtual.portais[tile];
  // passagem que só aparece em certa parte da história (js/masmorras.js)
  return p !== undefined && (!p.aparece || !!flags[p.aparece]);
}

function ehSolido(tile) {
  if (ehPortal(tile)) return false;
  if (mapaAtual.portais[tile]) return false;          // passagem escondida: chão comum
  if (tile === 'g' && typeof gradeDoMapaAberta === 'function' && gradeDoMapaAberta()) return false;
  const info = TILES[tile];
  return !info || info.solido === true; // letra desconhecida bloqueia
}

// Algo com um "raio" (em tiles) colide se qualquer um dos 4 cantos
// do quadradinho em volta dele estiver num tile sólido.
function colide(x, y, raio) {
  return ehSolido(tileEm(x - raio, y - raio)) ||
         ehSolido(tileEm(x + raio, y - raio)) ||
         ehSolido(tileEm(x - raio, y + raio)) ||
         ehSolido(tileEm(x + raio, y + raio));
}

;
// ===== js/caminhos.js =====
// =====================================================================
// CAMINHOS: contornar paredes, rochas e colunas
// =====================================================================
// Antes, jogador e inimigos andavam em linha reta até o alvo e travavam atrás
// de qualquer coluna (nas Cisternas, a hiena velha ficava presa do outro lado
// de um pilar e a missão nunca terminava). Agora, quando a linha reta está
// fechada, procuramos um caminho pelos tiles (A*, 8 direções, sem cortar
// quina) e seguimos os pontos dele, pulando os que já dá para ver direto.

// O tile (x, y) dá passagem? (portal só se for o destino)
function tileDaPassagem(x, y, aceitarPortal, orat, npcs) {
  const linha = mapaAtual.linhas[y];
  if (!linha || x < 0 || x >= linha.length) return false;
  const t = linha[x];
  if (ehPortal(t)) return !!aceitarPortal;
  if (ehSolido(t)) return false;
  orat = orat || (typeof oratoriosDoMapa === 'function' ? oratoriosDoMapa() : []);
  if (orat.some((o) => Math.abs(o.x - x) < 0.6 && Math.abs(o.y - y) < 0.6)) return false;
  // gente parada no caminho (NPCs): contorna em vez de empacar nela
  npcs = npcs || (typeof npcsDoMapa === 'function' ? npcsDoMapa() : []);
  if (npcs.some((n) => Math.abs(n.x - x) < 0.6 && Math.abs(n.y - y) < 0.6)) return false;
  return true;
}

// Linha reta livre para algo de raio "raio" (só paredes e oratórios)
function linhaLivre(x0, y0, x1, y1, raio) {
  const d = Math.hypot(x1 - x0, y1 - y0);
  const passos = Math.max(1, Math.ceil(d / 0.2));
  for (let i = 1; i <= passos; i++) {
    const x = x0 + (x1 - x0) * i / passos, y = y0 + (y1 - y0) * i / passos;
    if (colide(x, y, raio)) return false;
    if (typeof colideComOratorio === 'function' && colideComOratorio(x, y, raio)) return false;
    if (typeof colideComNpc === 'function' && colideComNpc(x, y, raio)) return false;
    // passar por cima de uma passagem que não é o destino troca de mapa sem querer
    if (ehPortal(tileEm(x, y)) && (Math.round(x) !== Math.round(x1) || Math.round(y) !== Math.round(y1))) return false;
  }
  return true;
}

// A* de (x0, y0) até (x1, y1). Devolve a lista de centros de tile (sem o
// ponto de partida) ou null se não houver caminho.
function acharCaminho(x0, y0, x1, y1, aceitarPortal) {
  const linhas = mapaAtual.linhas;
  const H = linhas.length, W = linhas[0].length;
  let sx = Math.round(x0), sy = Math.round(y0);
  const orat = typeof oratoriosDoMapa === 'function' ? oratoriosDoMapa() : [];
  const npcs = typeof npcsDoMapa === 'function' ? npcsDoMapa() : [];
  // começou num tile fechado (encostado num oratório, na quina de uma parede):
  // sai primeiro pelo tile livre vizinho mais perto
  let saida = null;
  if (!tileDaPassagem(sx, sy, false, orat, npcs)) {
    let md = 1e9;
    for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) {
      if (!tileDaPassagem(sx + dx, sy + dy, false, orat, npcs)) continue;
      const dd = Math.hypot(sx + dx - x0, sy + dy - y0);
      if (dd < md) { md = dd; saida = { x: sx + dx, y: sy + dy }; }
    }
    if (saida) { sx = saida.x; sy = saida.y; }
  }
  let gx = Math.round(x1), gy = Math.round(y1);
  if (!tileDaPassagem(gx, gy, true, orat, npcs)) {
    // alvo dentro de algo sólido: o tile livre mais perto dele
    let melhor = null, md = 1e9;
    for (let dy = -2; dy <= 2; dy++) for (let dx = -2; dx <= 2; dx++) {
      if (!tileDaPassagem(gx + dx, gy + dy, aceitarPortal, orat, npcs)) continue;
      const dd = Math.hypot(gx + dx - x1, gy + dy - y1);
      if (dd < md) { md = dd; melhor = [gx + dx, gy + dy]; }
    }
    if (!melhor) return null;
    [gx, gy] = melhor;
  }
  const idx = (x, y) => y * W + x;
  const fim = idx(gx, gy), ini = idx(sx, sy);
  if (fim === ini) return saida ? [saida, { x: x1, y: y1 }] : [{ x: x1, y: y1 }];
  const g = new Float32Array(W * H).fill(Infinity);
  const veio = new Int32Array(W * H).fill(-1);
  const fechado = new Uint8Array(W * H);
  // fila de prioridade simples (heap binário)
  const heap = [];
  const push = (n, f) => {
    heap.push([f, n]);
    let i = heap.length - 1;
    while (i > 0) { const p = (i - 1) >> 1; if (heap[p][0] <= heap[i][0]) break; [heap[p], heap[i]] = [heap[i], heap[p]]; i = p; }
  };
  const pop = () => {
    const topo = heap[0], ult = heap.pop();
    if (heap.length) {
      heap[0] = ult;
      let i = 0;
      for (;;) {
        const a = 2 * i + 1, b = a + 1;
        let m = i;
        if (a < heap.length && heap[a][0] < heap[m][0]) m = a;
        if (b < heap.length && heap[b][0] < heap[m][0]) m = b;
        if (m === i) break;
        [heap[m], heap[i]] = [heap[i], heap[m]]; i = m;
      }
    }
    return topo[1];
  };
  const h = (x, y) => { const dx = Math.abs(x - gx), dy = Math.abs(y - gy); return Math.max(dx, dy) + 0.414 * Math.min(dx, dy); };
  g[ini] = 0; push(ini, h(sx, sy));
  // passagens só como o ponto final: o caminho não atravessa outras bocas de mapa
  const passa = (x, y) => (x === gx && y === gy) || tileDaPassagem(x, y, false, orat, npcs);
  let abertos = 0;
  while (heap.length && abertos < 6000) {
    const n = pop();
    if (fechado[n]) continue;
    fechado[n] = 1; abertos++;
    if (n === fim) break;
    const x = n % W, y = (n / W) | 0;
    for (let dy = -1; dy <= 1; dy++) for (let dx = -1; dx <= 1; dx++) {
      if (!dx && !dy) continue;
      const nx = x + dx, ny = y + dy;
      if (nx < 0 || ny < 0 || nx >= W || ny >= H || !passa(nx, ny)) continue;
      if (dx && dy && (!passa(x + dx, y) || !passa(x, y + dy))) continue;   // não corta quina
      const m = idx(nx, ny);
      const ng = g[n] + (dx && dy ? 1.414 : 1);
      if (ng < g[m]) { g[m] = ng; veio[m] = n; push(m, ng + h(nx, ny)); }
    }
  }
  if (veio[fim] < 0) return null;
  const pontos = [];
  for (let n = fim; n !== ini && n >= 0; n = veio[n]) pontos.push({ x: n % W, y: (n / W) | 0 });
  pontos.reverse();
  if (saida) pontos.unshift(saida);
  pontos[pontos.length - 1] = { x: x1, y: y1 };   // termina no ponto exato
  return pontos;
}

// Para onde "ent" deve andar agora para chegar a (ax, ay).
// Guarda a rota em ent.rota. Devolve null se não há caminho nenhum.
function passoNoCaminho(ent, ax, ay, raio, aceitarPortal) {
  if (linhaLivre(ent.x, ent.y, ax, ay, raio)) { ent.rota = null; return { x: ax, y: ay }; }
  const agora = performance.now() / 1000;
  const chave = Math.round(ax) + ',' + Math.round(ay);
  let r = ent.rota;
  if (!r || r.chave !== chave || agora - r.quando > 0.8 + (r.folga || 0)) {
    r = ent.rota = { chave, quando: agora, folga: Math.random() * 0.3,
                     pontos: acharCaminho(ent.x, ent.y, ax, ay, aceitarPortal) };
  }
  const pts = r.pontos;
  if (!pts || !pts.length) return pts ? { x: ax, y: ay } : null;
  // tira os pontos já alcançados e pula para o mais longe que dá para ver direto
  while (pts.length > 1 && Math.hypot(pts[0].x - ent.x, pts[0].y - ent.y) < 0.2) pts.shift();
  for (let i = Math.min(pts.length - 1, 5); i > 0; i--) {
    if (linhaLivre(ent.x, ent.y, pts[i].x, pts[i].y, raio)) { pts.splice(0, i); break; }
  }
  return pts[0];
}

