// ===== js/entrada.js =====
// =====================================================================
// ENTRADA: teclado, mouse e zoom
// =====================================================================

// --- Teclado: guardamos quais teclas estão pressionadas agora ---
const teclas = {};
window.addEventListener('keydown', (e) => { teclas[e.key.toLowerCase()] = true; });
window.addEventListener('keyup',   (e) => { teclas[e.key.toLowerCase()] = false; });

// --- Mouse ---
let destino = null; // ponto do mundo para onde o jogador está indo (clique)
const mouse = { x: 0, y: 0, pressionado: false, direito: false };
const camera = { x: 0, y: 0 }; // calculada no desenho, usada pelo mouse

// --- Zoom: aumenta ou diminui tudo junto, sem mudar a proporção ---
// 1 = tamanho normal; 2 = o dobro. Roda do mouse ou teclas + e -.
const ZOOM_MIN = 0.6;
const ZOOM_MAX = 3;
let zoom = 2.0;

function mudarZoom(fator) {
  zoom = Math.min(ZOOM_MAX, Math.max(ZOOM_MIN, zoom * fator));
}

canvas.addEventListener('wheel', (e) => {
  e.preventDefault(); // impede a página de rolar
  if (typeof rolarEm === 'function' && rolarEm(e.clientX, e.clientY, e.deltaY)) return;   // texto comprido (js/rolagem.js)
  mudarZoom(e.deltaY < 0 ? 1.1 : 1 / 1.1);
}, { passive: false });

window.addEventListener('keydown', (e) => {
  if (e.key === '+' || e.key === '=') mudarZoom(1.1);
  if (e.key === '-') mudarZoom(1 / 1.1);
  // Espaço ataca na direção do cursor (fora das conversas)
  if (e.key === ' ' && !dialogo && !transicao && !diarioAberto) {
    e.preventDefault();
    const p = pontoDoMouseNoMundo();
    atacar(anguloAte(p.x, p.y));
  }
});

// Ponto do mundo sob o cursor. Com zoom, primeiro dividimos a posição
// do mouse pelo zoom, depois tiramos a câmera e convertemos para o mundo.
function pontoDoMouseNoMundo() {
  return telaParaMundo(mouse.x / zoom - camera.x, mouse.y / zoom - camera.y);
}

function definirDestinoPeloMouse() {
  const p = pontoDoMouseNoMundo();
  destino = { x: p.x, y: p.y };
}

function limparAlvos() {
  npcAlvo = null; alvoInimigo = null; alvoItem = null; oratorioAlvo = null; achadoAlvo = null;
}

canvas.addEventListener('mousemove', (e) => {
  mouse.x = e.clientX;
  mouse.y = e.clientY;
});

// Um clique pode ser: no painel de equipamento, num item no chão,
// num NPC, num inimigo, ou no chão (andar). Testamos nessa ordem.
canvas.addEventListener('mousedown', (e) => {
  mouse.x = e.clientX;
  mouse.y = e.clientY;
  if (dialogo || transicao || menuOratorio) return; // conversa e menu cuidam dos próprios cliques
  if (e.button === 0 && cliqueNoHud()) return;       // painel de baixo (js/hud.js)
  if (e.button === 2 && !MODO.toque && mouse.y > canvas.height - alturaHud()) return;
  if (cliqueNoPainelTomas()) return;                 // atributos, habilidades e virtudes
  if (e.button === 0 && cliqueNasMissoes()) return;  // botão e diário de missões
  if (e.button === 0 && cliqueNaCronica()) return;   // botão e páginas da Crônica
  if (diarioAberto || cronicaAberta) return;
  if (lojaAberta) { cliqueNaLoja(e.button); return; }
  if (cliqueNoPainel(e.button)) return;

  if (e.button === 2) {                      // botão direito: atacar
    mouse.direito = true;
    return;
  }
  if (e.button !== 0) return;

  limparAlvos();
  const item = itemNoChaoSobOMouse();
  if (!item && typeof cliqueNasMasmorras === 'function' && cliqueNasMasmorras()) return;   // roldana, fios (js/masmorras.js)
  const achado = item ? null : achadoSobOMouse();          // jarros, baús e corpos (js/achados.js)
  if (achado) { achadoAlvo = achado; destino = { x: achado.x, y: achado.y }; return; }
  const npc = item ? null : npcSobOMouse();
  const inimigo = item || npc ? null : inimigoSobOMouse();
  const oratorio = item || npc || inimigo ? null : oratorioSobOMouse();
  if (oratorio) {
    oratorioAlvo = oratorio;
    destino = { x: oratorio.chegada.x, y: oratorio.chegada.y };
  } else if (item) {
    alvoItem = item;
    destino = { x: item.x, y: item.y };
  } else if (npc) {
    npcAlvo = npc;
    destino = { x: npc.x, y: npc.y };
  } else if (inimigo) {
    alvoInimigo = inimigo;
  } else {
    mouse.pressionado = true;                // segurar faz seguir o cursor
    definirDestinoPeloMouse();
  }
});

// No window (e não no canvas) para soltar mesmo se o mouse sair da tela
window.addEventListener('mouseup', (e) => {
  if (e.button === 0) mouse.pressionado = false;
  if (e.button === 2) mouse.direito = false;
});
// Impede o menu do botão direito: ele é usado para atacar
canvas.addEventListener('contextmenu', (e) => e.preventDefault());

