// ===== js/rolagem.js =====
// =====================================================================
// ROLAGEM: textos compridos que não cabem na janela
// =====================================================================
// No celular deitado, a tela é baixa e as falas longas, as missões e as
// páginas da Crônica passavam da borda. Cada região que pode rolar se
// registra aqui a cada quadro; a roda do mouse (js/entrada.js) e o arrasto
// do dedo (js/toque.js) mexem nela.
//
// Uso, ao desenhar:
//   const off = regiaoRolavel('cronica', x, y, w, h, alturaDoConteudo);
//   ctx.save(); recortar(x, y, w, h);  ...desenha em (y - off)...  ctx.restore();
//   barraDeRolagem('cronica');

const ROLAGEM = {};

// Registra a região e devolve quanto o conteúdo está rolado (em pixels)
function regiaoRolavel(chave, x, y, w, h, alturaConteudo) {
  const r = ROLAGEM[chave] ||= { y: 0, max: 0 };
  r.area = { x, y, w, h };
  r.max = Math.max(0, Math.ceil(alturaConteudo - h));
  r.y = Math.min(Math.max(0, r.y), r.max);
  r.quando = performance.now();
  return r.y;
}

function recortar(x, y, w, h) {
  ctx.beginPath();
  ctx.rect(x, y, w, h);
  ctx.clip();
}

function zerarRolagem(chave) {
  if (ROLAGEM[chave]) ROLAGEM[chave].y = 0;
}

// Leva a rolagem até mostrar o ponto "fundo" do conteúdo (para o texto que vai aparecendo)
function mostrarAte(chave, fundo) {
  const r = ROLAGEM[chave];
  if (!r || !r.area) return;
  if (fundo - r.y > r.area.h) r.y = Math.min(r.max, fundo - r.area.h);
}

// Barra fina à direita e um aviso de que há mais texto embaixo
function barraDeRolagem(chave) {
  const r = ROLAGEM[chave];
  if (!r || !r.area || r.max <= 0) return;
  const { x, y, w, h } = r.area;
  const total = h + r.max;
  const alt = Math.max(24, h * h / total);
  const pos = y + (h - alt) * (r.y / r.max);
  ctx.fillStyle = 'rgba(255, 255, 255, 0.06)';
  ctx.fillRect(x + w - 4, y, 3, h);
  ctx.fillStyle = 'rgba(232, 185, 49, 0.7)';
  ctx.fillRect(x + w - 4, pos, 3, alt);
  // mais texto embaixo: um degradê e uma setinha
  if (r.y < r.max - 2) {
    const g = ctx.createLinearGradient(0, y + h - 26, 0, y + h);
    g.addColorStop(0, 'rgba(20, 17, 14, 0)');
    g.addColorStop(1, 'rgba(20, 17, 14, 0.9)');
    ctx.fillStyle = g;
    ctx.fillRect(x, y + h - 26, w - 6, 26);
    ctx.font = '12px Alegreya, Georgia, serif';
    ctx.fillStyle = '#c9a25a';
    ctx.textAlign = 'center';
    ctx.fillText(MODO.toque ? '▾ arraste para ler mais' : '▾ role para ler mais', x + w / 2, y + h - 6);
    ctx.textAlign = 'left';
  }
}

// Região rolável (desenhada agora há pouco e com texto sobrando) num ponto da tela
function areaRolavelEm(px, py) {
  const agora = performance.now();
  for (const r of Object.values(ROLAGEM)) {
    if (!r.area || r.max <= 0 || agora - r.quando > 250) continue;
    const a = r.area;
    if (px >= a.x && px <= a.x + a.w && py >= a.y && py <= a.y + a.h) return r;
  }
  return null;
}

// Roda do mouse: rola se estiver sobre uma região; devolve true se rolou
function rolarEm(px, py, dy) {
  const r = areaRolavelEm(px, py);
  if (!r) return false;
  r.y = Math.min(r.max, Math.max(0, r.y + dy));
  return true;
}

