// ===== js/transicao.js =====
// =====================================================================
// TRANSIÇÃO: a tela escurece, o mapa troca e a tela clareia
// =====================================================================
// Enquanto acontece, "transicao" guarda o estado; senão é null.
let transicao = null;

function iniciarTransicao(portal) {
  destino = null;
  mouse.pressionado = false;
  mouse.direito = false;
  transicao = { portal: portal, fase: 'escurecendo', opacidade: 0 };
}

// Pergunta antes de entrar numa passagem (teclado e joystick)
let passagemRecusada = null;   // { x, y } do tile da passagem recusada
function perguntarPassagem(portal, tx, ty) {
  const nome = (MAPAS[portal.destino] && MAPAS[portal.destino].nome) || portal.rotulo || portal.destino;
  passagemRecusada = null;
  menuOratorio = {
    oratorio: { nome: `Ir para ${nome}?` }, sob: -1, pergunta: true,
    opcoes: [
      { texto: 'Entrar', acao: () => iniciarTransicao(portal) },
      { texto: 'Ficar aqui', acao: () => { passagemRecusada = { x: tx, y: ty }; } }
    ]
  };
}

function atualizarTransicao(dt) {
  const VELOCIDADE_FADE = 3; // quanto maior, mais rápida a transição
  if (transicao.fase === 'escurecendo') {
    transicao.opacidade += dt * VELOCIDADE_FADE;
    if (transicao.opacidade >= 1) {
      // Tela totalmente preta: hora de trocar de mapa
      transicao.opacidade = 1;
      mapaAtual = MAPAS[transicao.portal.destino];
      jogador.x = transicao.portal.chegada.x;
      jogador.y = transicao.portal.chegada.y;
      // Depois de cair em combate, o jogador volta descansado
      if (transicao.portal.renascer) {
        jogador.vida = jogador.vidaMax;
      }
      aoEntrarNoMapa();
      transicao.fase = 'clareando';
    }
  } else {
    transicao.opacidade -= dt * VELOCIDADE_FADE;
    if (transicao.opacidade <= 0) transicao = null;
  }
}

function desenharTransicao() {
  if (!transicao) return;
  ctx.fillStyle = `rgba(0, 0, 0, ${transicao.opacidade})`;
  ctx.fillRect(0, 0, canvas.width, canvas.height);
}

