// (Os conjuntos e as peças de armadura e joias ficam em js/equipamento.js)

// Forma do afixo que combina com o gênero do item (Afiado, Afiada, Reforçadas...)
const formaDoAfixo = (a, genero) => a[genero] || a.m;

// --- Geração de itens ---

const sortear = (min, max) => min + Math.floor(Math.random() * (max - min + 1));
const escolherUm = (lista) => lista[Math.floor(Math.random() * lista.length)];
let proximoIdItem = 1;

function sortearRaridade(minima) {
  const ordem = ['comum', 'refinado', 'raro', 'conjunto', 'lendario'];
  let r = Math.random() * 100;
  let raridade = 'comum';
  for (const nome of ordem) {
    if (r < CHANCE_RARIDADE[nome]) { raridade = nome; break; }
    r -= CHANCE_RARIDADE[nome];
  }
  // Alguns inimigos garantem uma raridade mínima
  if (minima && ordem.indexOf(raridade) < ordem.indexOf(minima)) raridade = minima;
  return raridade;
}

function criarItem(base, raridade) {
  const b = baseDe({ base });
  const item = { id: proximoIdItem++, base, raridade, nome: b.nome, afixos: [], efeitos: {} };
  // Escudos raros têm 2 ou 3 bônus (há menos tipos de bônus para escudos)
  const maxRaro = BASES_ESCUDOS[base] ? 3 : 4;

  if (raridade === 'conjunto') {
    // Uma peça de conjunto com esta base (ou qualquer peça, se não houver)
    const todas = Object.entries(CONJUNTOS).flatMap(([id, c]) => c.pecas.map((p) => ({ id, p })));
    const achada = todas.find((x) => x.p.base === base) || escolherUm(todas);
    item.base = achada.p.base;
    item.nome = achada.p.nome;
    item.efeitos = { ...achada.p.efeitos };
    item.conjunto = achada.id;
    return garantirDurabilidade(item);
  }

  if (raridade === 'refinado' || raridade === 'raro') {
    const possiveis = AFIXOS.filter((a) => !a.so || a.so.includes(base));
    const quantos = raridade === 'refinado' ? sortear(1, 2) : sortear(maxRaro - 1, maxRaro);
    const usados = new Set();
    let prefixo = null, sufixo = null;
    while (item.afixos.length < quantos && usados.size < possiveis.length) {
      const a = escolherUm(possiveis);
      if (usados.has(a)) continue;
      usados.add(a);
      if (a.chance && Math.random() > a.chance) continue;   // afixo raro (os +1 em habilidades)
      // Um item refinado tem no máximo um prefixo e um sufixo
      if (raridade === 'refinado' && ((a.tipo === 'prefixo' && prefixo) || (a.tipo === 'sufixo' && sufixo))) continue;
      const valor = sortear(a.min, a.max);
      item.afixos.push({ efeito: a.efeito, valor });
      item.efeitos[a.efeito] = (item.efeitos[a.efeito] || 0) + valor;
      if (a.tipo === 'prefixo' && !prefixo) prefixo = formaDoAfixo(a, b.genero);
      if (a.tipo === 'sufixo' && !sufixo) sufixo = formaDoAfixo(a, b.genero);
    }
    if (raridade === 'refinado') {
      item.nome = [b.nome, prefixo, sufixo].filter(Boolean).join(' ');
    } else {
      item.nome = escolherUm(NOMES_RAROS_1) + ' ' + escolherUm(NOMES_RAROS_2);
    }
  }

  if (raridade === 'lendario') {
    const lend = LENDARIOS.find((l) => l.base === base) || LENDARIOS[0];
    item.base = lend.base;
    item.nome = lend.nome;
    item.efeitos = { ...lend.efeitos };
    item.texto = lend.texto;
  }
  return adicionarEngastes(garantirDurabilidade(item));
}

// Item sorteado que um inimigo deixa cair.
//   basesPermitidas = o que aquele inimigo poderia carregar (veja "loot" em
//   js/inimigos.js). Sem a lista, vale qualquer item.
function gerarItemAleatorio(raridadeMinima, basesPermitidas) {
  let raridade = sortearRaridade(raridadeMinima);
  if (basesPermitidas && !basesPermitidas.length) basesPermitidas = null;   // lista vazia: vale qualquer item
  const pode = (base) => !basesPermitidas || basesPermitidas.includes(base);

  // Lendários e peças de conjunto só caem se a base deles for permitida;
  // senão o item vira raro
  const lendarios = LENDARIOS.filter((l) => pode(l.base) && !l.unico);   // únicos só vêm da história
  const pecas = Object.values(CONJUNTOS).filter((c) => !c.unico).flatMap((c) => c.pecas).filter((p) => pode(p.base));
  if (raridade === 'lendario' && !lendarios.length) raridade = 'raro';
  if (raridade === 'conjunto' && !pecas.length) raridade = 'raro';

  let base;
  if (raridade === 'lendario') base = escolherUm(lendarios).base;
  else if (raridade === 'conjunto') base = escolherUm(pecas).base;
  else if (basesPermitidas) base = escolherUm(basesPermitidas);
  else {
    // Proporção do que cai: 45% armas, 15% escudos, 40% armaduras e joias
    const r = Math.random();
    base = escolherUm(r < 0.45 ? ARMAS : r < 0.6 ? ESCUDOS : Object.keys(BASES_EQUIP).filter((k) => !BASES_EQUIP[k].soHistoria && !BASES_EQUIP[k].soDeInimigo));
  }
  return criarItem(base, raridade);
}

// Bloqueio final de um escudo (base + bônus)
function bloqueioDoEscudo(item) {
  if (quebrado(item)) return 0;
  return BASES_ESCUDOS[item.base].bloqueio + (item.efeitos.bloqueioPct || 0) / 100;
}

// --- Números finais de uma arma, somando bônus e atributos ---
// Cada ponto posto na árvore da arma na mão soma dano e velocidade
// (a proficiência, js/habilidades.js), e isso já vem em "bonus".
// Força soma dano às armas de corpo a corpo; Destreza soma dano às bestas e
// deixa todos os golpes mais rápidos (js/progresso.js). Os bônus de habilidades,
// virtudes e posturas entram em "bonus" (js/equipamento.js, recalcularAtributos).
// O tempo de golpe nunca cai abaixo de 45% do tempo da arma.
const COR_SAGRADO = '#ffe58a';
function statsDaArma(item) {
  const b = BASES_ARMAS[item.base];
  const e = quebrado(item) ? {} : item.efeitos;   // quebrada: perde os bônus
  const attr = typeof bonusDosAtributos === 'function' ? bonusDosAtributos() : { forcaPct: 0, destrezaPct: 0, tempoPct: 0, sagradoPct: 0 };
  // Bônus da arma + bônus do resto do equipamento, habilidades e virtudes
  const danoPct = (e.danoPct || 0) + (bonus.danoPct || 0) + (b.projetil ? attr.destrezaPct : attr.forcaPct);
  const tempoPct = (e.tempoPct || 0) + (e.folegoPct || 0) / 2 + (bonus.tempoPct || 0) + attr.tempoPct;
  const multDano = (1 + danoPct / 100) *
                   (jogador.bencao > 0 ? 1 + BONUS_BENCAO : 1); // Bênção de um oratório
  // Dano sagrado: da arma, do equipamento (colares, anéis) e da virtude da Fé
  const sagradoMax = Math.round(((e.sagrado || 0) + (bonus.sagrado || 0)) * (1 + attr.sagradoPct / 100));
  return {
    dano: quebrado(item) ? [1, 2]                  // quebrada: machuca como um soco
        : [Math.round(b.dano[0] * multDano + (e.danoMin || 0)),
           Math.round(b.dano[1] * multDano + (e.danoMin || 0))],
    sagrado: [Math.ceil(sagradoMax / 2), sagradoMax],
    tempo: b.tempo * Math.max(0.45, 1 + tempoPct / 100),
    alcance: b.alcance * (1 + ((e.alcancePct || 0) + (bonus.alcancePct || 0)) / 100), // em metros
    arco: b.arco,
    maos: b.maos,
    projetil: !!b.projetil,
    critico: bonus.critico || 0,                   // % de chance de golpe crítico (dano dobrado)
    estilo: b.estilo
  };
}

// Linhas de texto que descrevem um bônus, para a ficha do item
const TEXTO_EFEITO = {
  danoPct:     (v) => `Dano +${v}%`,
  danoMin:     (v) => `Dano +${v}`,
  tempoPct:    (v) => `Ataque ${-v}% mais rápido`,
  sagrado:     (v) => `Dano sagrado ${Math.ceil(v / 2)} a ${v}`,
  regenVida:   (v) => `Recupera ${v} de vida a cada segundo`,
  // efeitos antigos (jogos salvos antes de o fôlego sair): viram outra coisa ao carregar
  folegoPct:   (v) => `Ataque ${-v}% mais rápido`,
  alcancePct:  (v) => `Alcance +${v}%`,
  maestriaPct: (v) => `Experiência +${v}%`,   // (o nome ficou do tempo da maestria)
  bloqueioPct: (v) => `Bloqueio +${v}%`,
  defesa:      (v) => `Defesa +${v}`,
  vidaMax:     (v) => `Vida +${v}`,
  folegoMax:   (v) => `Vida +${v}`,
  devocaoMax:  (v) => `Devoção +${v}`,
  velocidadePct: (v) => `Corrida ${v}% mais rápida`,
  folegoRegenPct: (v) => `Vida +${v}`,
  ouroPct:     (v) => `Ouro encontrado +${v}%`
};

// Velocidade do golpe em palavras (para a ficha do item)
function velocidadeDoGolpe(tempo) {
  return tempo < 0.55 ? 'muito rápido' : tempo < 0.75 ? 'rápido' : tempo < 0.95 ? 'médio' : tempo < 1.6 ? 'lento' : 'muito lento';
}

;
