// --- Bônus somados de tudo que está equipado ---
let bonus = {};

// Itens equipados agora: o conjunto de armas em uso + o corpo
function itensEquipados() {
  return [jogador.armas[jogador.armaAtiva], escudoAtivo(), ...ESPACOS.map((e) => jogador.equipamento[e.id])].filter(Boolean);
}

function pecasDoConjuntoEquipadas(id) {
  return itensEquipados().filter((i) => i.conjunto === id && !quebrado(i)).length;
}

function recalcularAtributos() {
  bonus = {};
  const somar = (efeitos) => {
    for (const [k, v] of Object.entries(efeitos)) bonus[k] = (bonus[k] || 0) + v;
  };
  for (const e of ESPACOS) {
    const item = jogador.equipamento[e.id];
    if (!item || quebrado(item)) continue;     // quebrado: não protege nem dá bônus
    const b = BASES_EQUIP[item.base];
    somar({ defesa: b.defesa || 0 });
    if (b.bonusBase) somar(b.bonusBase);          // o que a própria peça dá (hábito, cazagante)
    somar(item.efeitos);
  }
  // Escudo: o bloqueio fica no próprio escudo; os outros bônus (de gemas) valem para o corpo
  const esc = escudoAtivo();
  if (esc && !quebrado(esc)) somar(Object.fromEntries(Object.entries(esc.efeitos).filter(([k]) => k !== 'bloqueioPct')));
  // Bônus de conjunto
  for (const [id, c] of Object.entries(CONJUNTOS)) {
    const n = pecasDoConjuntoEquipadas(id);
    for (const [minimo, efeitos] of Object.entries(c.bonus)) if (n >= Number(minimo)) somar(efeitos);
  }
  // Habilidades passivas e posturas (js/habilidades.js) e a virtude ativa (js/virtudes.js)
  if (typeof bonusDasHabilidades === 'function') somar(bonusDasHabilidades());
  if (typeof bonusDaVirtude === 'function') somar(bonusDaVirtude());
  if (typeof bonusDasMasmorras === 'function') somar(bonusDasMasmorras());   // bênção de São Jorge
  // Atributos (js/progresso.js): Vigor dá vida, Fé dá devoção, Destreza dá bloqueio
  const a = typeof bonusDosAtributos === 'function' ? bonusDosAtributos()
          : { vida: 0, devocao: 0, bloqueioPct: 0, regenDevocao: 0 };
  somar({ bloqueioPct: a.bloqueioPct, regenDevocao: a.regenDevocao });
  jogador.vidaMax = Math.round((VIDA_BASE + a.vida + (bonus.vidaMax || 0)) * (1 + (bonus.vidaPct || 0) / 100));
  jogador.devocaoMax = DEVOCAO_BASE + a.devocao + (bonus.devocaoMax || 0);
  jogador.velocidade = VELOCIDADE_BASE * (1 + (bonus.velocidadePct || 0) / 100);
  jogador.vida = Math.min(jogador.vida, jogador.vidaMax);
  jogador.devocao = Math.min(jogador.devocao, jogador.devocaoMax);
}

// Bloqueio do escudo em uso, com os bônus (no máximo 75%; a Muralha leva a 95%).
// Sem escudo, só bloqueia quem tem um bônus próprio (o pavês do besteiro).
function bloqueioTotal() {
  const e = escudoAtivo();
  const teto = bonus.bloqueioTotal ? 0.95 : 0.75;
  if (e) return Math.min(teto, bloqueioDoEscudo(e) + (bonus.bloqueioPct || 0) / 100);
  return Math.min(teto, (bonus.bloqueioSemEscudo || 0) / 100);
}

// Defesa total e quanto ela reduz do dano (nunca chega a 100%)
function defesaTotal() { return Math.round((bonus.defesa || 0) * (1 + (bonus.defesaPct || 0) / 100)); }
function reducaoPorDefesa() { const d = defesaTotal(); return d / (d + 40); }

// Em que espaço um item vai: 'arma', 'escudo' ou um dos ESPACOS
function categoriaDe(item) {
  if (BASES_ARMAS[item.base]) return 'arma';
  if (BASES_ESCUDOS[item.base]) return 'escudo';
  return BASES_EQUIP[item.base].cat;
}

// --- Equipar e tirar ---

// Põe um item do alforje no corpo; o que estava no lugar volta para o alforje
function equipar(indiceAlforje) {
  const item = jogador.alforje[indiceAlforje];
  const cat = categoriaDe(item);
  const i = jogador.armaAtiva;
  const devolver = (antigo) => { if (antigo) jogador.alforje.push(antigo); };
  const arma = jogador.armas[i];

  if (cat === 'escudo' && arma && BASES_ARMAS[arma.base].maos === 2) {
    avisar(`${arma.nome} usa as duas mãos. Não sobra mão para o escudo.`);
    return;
  }
  jogador.alforje.splice(indiceAlforje, 1);
  if (cat === 'arma') {
    devolver(jogador.armas[i]);
    jogador.armas[i] = item;
    // Arma de duas mãos: o escudo do conjunto volta para o alforje
    if (BASES_ARMAS[item.base].maos === 2 && jogador.escudos[i]) {
      devolver(jogador.escudos[i]);
      jogador.escudos[i] = null;
      avisar('Arma de duas mãos: o escudo foi para o alforje.');
    }
  } else if (cat === 'escudo') {
    devolver(jogador.escudos[i]);
    jogador.escudos[i] = item;
  } else if (cat === 'anel') {
    // Primeiro anel livre; se os dois estão ocupados, troca o primeiro
    const espaco = !jogador.equipamento.anel1 ? 'anel1' : !jogador.equipamento.anel2 ? 'anel2' : 'anel1';
    devolver(jogador.equipamento[espaco]);
    jogador.equipamento[espaco] = item;
  } else {
    devolver(jogador.equipamento[cat]);
    jogador.equipamento[cat] = item;
  }
  recalcularAtributos();
}

// Tira um item do corpo e põe no alforje
function desequipar(onde, id) {
  if (jogador.alforje.length >= TAMANHO_ALFORJE) { avisar('O alforje está cheio.'); return; }
  let item = null;
  if (onde === 'arma') { item = jogador.armas[jogador.armaAtiva]; jogador.armas[jogador.armaAtiva] = null; }
  else if (onde === 'escudo') { item = jogador.escudos[jogador.armaAtiva]; jogador.escudos[jogador.armaAtiva] = null; }
  else if (onde === 'corpo') { item = jogador.equipamento[id]; jogador.equipamento[id] = null; }
  if (item) jogador.alforje.push(item);
  recalcularAtributos();
}

