// ===== js/durabilidade.js =====
// =====================================================================
// DURABILIDADE: armas e armaduras se gastam com o uso, como no Diablo 2
// =====================================================================
// - A arma perde um ponto, às vezes, a cada golpe que acerta (ou tiro dado).
// - Quando Tomás é ferido, uma peça de armadura pode perder um ponto, e o
//   escudo também, se ele estava se defendendo (sem atacar).
// - Com 0 de durabilidade o item QUEBRA: deixa de dar defesa e bônus, e a
//   arma quebrada só machuca como um soco (1 a 2). Não some: o Bulos conserta.
// - Anéis e colares não se gastam.

// Durabilidade máxima de cada base (mais robusto = mais pontos)
const DUR_MAX = {
  faca: 20, espada: 32, acha: 30, maca: 36, lanca: 26, machado: 34, besta: 30, bestaMao: 24,
  amendoa: 40, broquel: 30,
  capuz: 12, capelo: 24, elmoNasal: 30, gambesao: 20, cota: 40,
  luvasCouro: 12, manoplas: 18, botasCouro: 12, botasCano: 18,
  sobreveste: 50, elmoGrande: 40, escudoCruz: 50,
  cintoCouro: 20, cinturao: 26, cintoCavaleiro: 34
};
const CHANCE_DESGASTE = { arma: 0.12, armadura: 0.25, escudo: 0.25 };  // uma espada aguenta ~270 golpes
const AVISO_DESGASTE = 0.2;   // abaixo de 20% o item aparece como "gasto"

const temDurabilidade = (item) => item && item.tipo === undefined && DUR_MAX[item.base] !== undefined;
const quebrado = (item) => temDurabilidade(item) && item.dur <= 0;
const gasto = (item) => temDurabilidade(item) && item.dur > 0 && item.dur <= item.durMax * AVISO_DESGASTE;

// Itens criados antes da durabilidade existir (jogos salvos) ganham a máxima
function garantirDurabilidade(item) {
  if (temDurabilidade(item) && item.durMax === undefined) { item.durMax = DUR_MAX[item.base]; item.dur = item.durMax; }
  return item;
}

function gastar(item, chance) {
  if (!temDurabilidade(item) || quebrado(item) || Math.random() >= chance) return;
  item.dur--;
  if (item.dur === 0) {
    avisar(`${item.nome} quebrou! Leve ao Bulos, o Ferreiro.`);
    recalcularAtributos();
  } else if (item.dur === Math.floor(item.durMax * AVISO_DESGASTE)) {
    avisar(`${item.nome} está se desgastando.`);
  }
}

// Chamados pelo combate (js/combate.js)
function desgasteAoAcertar() { gastar(armaAtiva(), CHANCE_DESGASTE.arma); }
function desgasteAoApanhar() {
  const pecas = ['elmo', 'armadura', 'luvas', 'botas'].map((e) => jogador.equipamento[e]).filter(temDurabilidade);
  if (pecas.length) gastar(escolherUm(pecas), CHANCE_DESGASTE.armadura);
  const escudo = escudoAtivo();
  if (escudo && !ataque) gastar(escudo, CHANCE_DESGASTE.escudo);
}

// --- Conserto (no Bulos, o ferreiro) -------------------------------------------------

// Itens que o jogador carrega (no corpo, na reserva e no alforje)
function todosOsItensDoJogador() {
  return [...jogador.armas, ...jogador.escudos, ...Object.values(jogador.equipamento), ...jogador.alforje].filter(Boolean);
}

// Custo para deixar um item novo: até 1/4 do valor, proporcional ao desgaste
function custoConserto(item) {
  if (!temDurabilidade(item) || item.dur >= item.durMax) return 0;
  const valorCheio = Math.round((PRECO_BASE[item.base] || 50) * MULT_RARIDADE[item.raridade]);
  return Math.max(1, Math.ceil(valorCheio * 0.25 * (1 - item.dur / item.durMax)));
}
const custoConsertoTotal = () => todosOsItensDoJogador().reduce((s, i) => s + custoConserto(i), 0);

function consertarTudo() {
  const custo = custoConsertoTotal();
  if (!custo) { avisarUmaVez('Nada precisa de conserto.'); return; }
  if (jogador.ouro < custo) { avisarUmaVez(`O conserto custa ${custo} de ouro.`); return; }
  jogador.ouro -= custo;
  for (const i of todosOsItensDoJogador()) if (temDurabilidade(i)) i.dur = i.durMax;
  recalcularAtributos();
  avisar(`Bulos consertou tudo por ${custo} de ouro.`);
}

// Avisos no canto da tela, como os ícones de armadura gasta do D2
function desenharAvisosDeDesgaste(x, y) {
  const itens = itensEquipados().filter((i) => quebrado(i) || gasto(i));
  ctx.font = '11px monospace';
  itens.forEach((i, k) => {
    ctx.fillStyle = quebrado(i) ? '#e0574a' : '#e8b931';
    ctx.fillText(`${quebrado(i) ? 'QUEBRADO' : 'gasto'}: ${i.nome}`, x, y - k * 14);
  });
}

;
// ===== js/gemas.js =====
// =====================================================================
// GEMAS E ENGASTES
// =====================================================================
// Como no Diablo 2: algumas armas, elmos, armaduras e escudos têm engastes
// (buracos para pedras). Uma gema encaixada dá um bônus que depende de onde
// ela está, e FICA PRESA no item (não sai mais).
//
// Para encaixar: abra o equipamento (I), clique na gema no alforje e depois
// no item com engaste livre (no corpo ou no alforje). Esc ou botão direito cancela.
//
// Cinco pedras conhecidas no século XII, em três qualidades.

const QUALIDADES_GEMA = ['lascado', 'lapidado', 'perfeito'];
const NOME_QUALIDADE = {
  m: ['lascado', 'lapidado', 'perfeito'],
  f: ['lascada', 'lapidada', 'perfeita']
};

// Bônus por qualidade [lascada, lapidada, perfeita], conforme onde a gema vai
const GEMAS = {
  rubi:      { nome: 'Rubi', genero: 'm', cor: '#d8484a',
               arma: ['danoPct', 6, 10, 15], armadura: ['vidaMax', 6, 10, 15], escudo: ['bloqueioPct', 3, 5, 8] },
  esmeralda: { nome: 'Esmeralda', genero: 'f', cor: '#4fbf6a',
               arma: ['tempoPct', -4, -7, -10], armadura: ['vidaMax', 6, 10, 15], escudo: ['defesa', 2, 3, 5] },
  safira:    { nome: 'Safira', genero: 'f', cor: '#5a86e0',
               arma: ['maestriaPct', 10, 15, 25], armadura: ['devocaoMax', 6, 10, 15], escudo: ['devocaoMax', 4, 6, 10] },
  topazio:   { nome: 'Topázio', genero: 'm', cor: '#e0b03a',
               arma: ['danoMin', 1, 2, 3], armadura: ['ouroPct', 10, 20, 30], escudo: ['defesa', 2, 3, 5] },
  ametista:  { nome: 'Ametista', genero: 'f', cor: '#a46ad8',
               arma: ['sagrado', 3, 5, 8], armadura: ['defesa', 2, 3, 5], escudo: ['vidaMax', 5, 8, 12] }
};
const VALOR_GEMA = [20, 60, 180];

// Quantos engastes cada tipo de item pode ter, no máximo
function maxEngastes(item) {
  const b = BASES_ARMAS[item.base];
  if (b) return b.maos === 2 ? 4 : 3;
  if (BASES_ESCUDOS[item.base]) return 3;
  const cat = BASES_EQUIP[item.base]?.cat;
  if (cat === 'armadura') return 3;
  if (cat === 'elmo') return 2;
  return 0;  // luvas, botas, colares e anéis não têm engaste
}

// Onde uma gema conta como "arma", "armadura" ou "escudo"
function lugarDaGema(item) {
  if (BASES_ARMAS[item.base]) return 'arma';
  if (BASES_ESCUDOS[item.base]) return 'escudo';
  return 'armadura';  // elmos e armaduras
}

// Chamado quando um item é criado: alguns itens comuns e refinados nascem com engastes
function adicionarEngastes(item) {
  const max = maxEngastes(item);
  if (!max || item.engastes !== undefined) return item;
  const chance = item.raridade === 'comum' ? 0.25 : item.raridade === 'refinado' ? 0.12 : 0;
  item.engastes = Math.random() < chance ? sortear(1, item.raridade === 'comum' ? max : Math.min(2, max)) : 0;
  item.gemas = [];
  return item;
}

const engastesLivres = (item) => (item.engastes || 0) - (item.gemas?.length || 0);

function criarGema(tipo, q) {
  const g = GEMAS[tipo];
  return { tipo: 'gema', gema: tipo, qualidade: q, id: proximoIdItem++,
           nome: `${g.nome} ${NOME_QUALIDADE[g.genero][q]}` };
}

// Gema que um inimigo deixa cair: lascadas são comuns, perfeitas são raras
const CHANCE_GEMA = 0.06;     // por inimigo humano (provisório: o equilíbrio final vem depois)
function largarGema(ini) {
  if (!ini.tipo.ouro || Math.random() >= CHANCE_GEMA * (ini.tipo.chanceItem >= 1 ? 3 : 1)) return;
  const r = Math.random();
  const q = r < 0.70 ? 0 : r < 0.95 ? 1 : 2;
  largarItem(criarGema(escolherUm(Object.keys(GEMAS)), q), ini.x, ini.y);
}

// Texto do bônus de uma gema num lugar
function bonusDaGema(gema, q, lugar) {
  const [efeito, ...valores] = GEMAS[gema][lugar];
  return { efeito, valor: valores[q] };
}

// Encaixa (para sempre) uma gema num item
function encaixarGema(gemaItem, alvo) {
  if (engastesLivres(alvo) <= 0) { avisarUmaVez('Esse item não tem engaste livre.'); return false; }
  const { efeito, valor } = bonusDaGema(gemaItem.gema, gemaItem.qualidade, lugarDaGema(alvo));
  alvo.gemas.push({ gema: gemaItem.gema, qualidade: gemaItem.qualidade });
  alvo.efeitos[efeito] = (alvo.efeitos[efeito] || 0) + valor;
  const k = jogador.alforje.indexOf(gemaItem);
  if (k >= 0) jogador.alforje.splice(k, 1);
  recalcularAtributos();
  avisar(`${gemaItem.nome} encaixado em ${alvo.nome}.`);
  return true;
}

// Seleção de gema no painel de equipamento
let gemaSelecionada = null;
window.addEventListener('keydown', (e) => { if (e.key === 'Escape') gemaSelecionada = null; });

// Linhas da ficha de uma gema (o que ela dá em cada lugar)
function linhasDaFichaGema(item) {
  const g = GEMAS[item.gema];
  const txt = (lugar) => { const { efeito, valor } = bonusDaGema(item.gema, item.qualidade, lugar); return TEXTO_EFEITO[efeito](valor); };
  return [
    { t: item.nome, cor: g.cor, fonte: 'bold 15px Alegreya, Georgia, serif' },
    { t: 'Gema · fica presa no item depois de encaixada', cor: '#a39a86' },
    { t: `Na arma: ${txt('arma')}`, cor: '#efe7d6' },
    { t: `No elmo ou armadura: ${txt('armadura')}`, cor: '#efe7d6' },
    { t: `No escudo: ${txt('escudo')}`, cor: '#efe7d6' },
    { t: 'Clique nela no alforje e depois no item com engaste livre', cor: '#8f846c' }
  ];
}

// Linha da ficha de um item com engastes
function linhaDosEngastes(item) {
  if (!item.engastes) return null;
  const nomes = item.gemas.map((g) => `${GEMAS[g.gema].nome} ${NOME_QUALIDADE[GEMAS[g.gema].genero][g.qualidade]}`);
  for (let k = item.gemas.length; k < item.engastes; k++) nomes.push('vazio');
  return { t: `Engastes (${item.engastes}): ${nomes.join(', ')}`, cor: '#c9b98a' };
}

