// ===== js/jogador.js =====
// =====================================================================
// JOGADOR: posição, atributos, movimento, ataque e desenho
// =====================================================================

const jogador = {
  x: 23, y: 77,     // posição no mundo, em tiles (no pátio do quartel, perto do Portão de Gaza)
  velocidade: 2.2,  // tiles por segundo: ~4,4 m/s, um passo rápido
  raio: 0.2,        // "tamanho" para colisão, em tiles (~0,4 m)
  altura: 1.75,     // altura em metros
  angulo: Math.PI / 2, // para onde está virado (no mundo)

  vida: 80, vidaMax: 80,
  devocao: 20, devocaoMax: 50, // a "mana": gasta nos golpes especiais (js/devocao.js)
  bencao: 0,                   // segundos restantes da Bênção de um oratório
  rezando: null,               // enquanto ajoelhado rezando

  // Estilo de combate: escolhido na Cena 2. Começa sem nenhum.
  estilo: null,
  // Nível, atributos e habilidades (js/progresso.js e js/habilidades.js)
  // Pontos de habilidade: 1 por nível, +1 por missão secundária e um de graça
  // na árvore da arma do caminho (js/habilidades.js)
  nivel: 1, xp: 0, pontosAtributo: 0, pontosHabilidade: 0,
  atributos: { forca: 10, destreza: 10, vigor: 10, fe: 10 },
  habilidades: {}, atalhos: [null, null, null], posturas: [], virtude: null, versaoHabilidades: 2,

  // Dois conjuntos, como no D2: o da mão e o de reserva (troca com Q).
  // Cada conjunto tem uma arma e, se ela for de uma mão, um escudo.
  armas: [criarItem('faca', 'comum'), null],
  escudos: [null, null],
  armaAtiva: 0,
  // O resto do corpo (js/equipamento.js)
  equipamento: { elmo: null, colar: null, armadura: null, luvas: null, botas: null, cinto: null, anel1: null, anel2: null },
  alforje: [],
  ouro: 0          // moedas de ouro (js/comercio.js)
};

const ESTILOS = {
  besta:    { nome: 'Besteiro',         arma: 'Besta' },
  lanca:    { nome: 'Lanceiro',         arma: 'Lança' },
  duasmaos: { nome: 'Duas mãos',        arma: 'Machado dinamarquês' },
  espada:   { nome: 'Espada e escudo',  arma: 'Espada e escudo' }
};

// Na Cena 2: o capitão entrega a arma do estilo escolhido (a faca vai para a
// reserva) e Tomás ganha o primeiro ponto na árvore dessa arma.
function escolherEstilo(estilo) {
  jogador.estilo = estilo;
  if (typeof darPrimeiroPonto === 'function') darPrimeiroPonto();
  const arma = criarItem(ARMA_DO_ESTILO[estilo], 'comum');
  jogador.armas = [arma, jogador.armas[0]];
  jogador.escudos = [null, null];
  jogador.armaAtiva = 0;
  avisar(`Você recebeu: ${arma.nome}`);
  // Quem escolhe espada e escudo recebe também o escudo
  if (estilo === 'espada') {
    jogador.escudos[0] = criarItem('amendoa', 'comum');
    avisar(`Você recebeu: ${jogador.escudos[0].nome}`);
  }
  avisar('Primeira habilidade aprendida: veja na janela do Tomás (T). Use com F.');
  // Todo soldado da guarda recebe um gambesão
  if (!jogador.equipamento.armadura) jogador.equipamento.armadura = criarItem('gambesao', 'comum');
  recalcularAtributos();
}

// O escudo do conjunto em uso (ou null)
function escudoAtivo() {
  return jogador.escudos[jogador.armaAtiva];
}

function atualizarJogador(dt) {
  // Direção NA TELA a partir das teclas (W = cima, S = baixo...)
  let telaDX = 0, telaDY = 0;
  if (teclas['w']) telaDY -= 1;
  if (teclas['s']) telaDY += 1;
  if (teclas['a']) telaDX -= 1;
  if (teclas['d']) telaDX += 1;
  // Joystick do celular: direção analógica na tela (o y vale o dobro porque
  // a tela isométrica achata a altura pela metade)
  const joyTela = typeof joystickAtivo === 'function' ? joystickAtivo() : null;
  if (joyTela) { telaDX = joyTela.x; telaDY = joyTela.y * 2; }
  const usandoTeclado = telaDX !== 0 || telaDY !== 0;

  // Rezando: fica ajoelhado. Andar interrompe a oração.
  if (jogador.rezando) {
    if (usandoTeclado || mouse.pressionado) interromperOracao('Você se levantou.');
    else return;
  }
  // Na investida, quem move Tomás é js/habilidades.js
  if (jogador.investida) return;

  // Botão direito segurado: ataca na direção do cursor, parado
  if (mouse.direito && !usandoTeclado) {
    const p = pontoDoMouseNoMundo();
    destino = null; alvoInimigo = null;
    atacar(anguloAte(p.x, p.y));
  }

  // Inimigo clicado: chega perto e ataca até ele cair
  if (alvoInimigo && !usandoTeclado) {
    if (alvoInimigo.morto) {
      alvoInimigo = null;
    } else {
      const s = statsDaArma(armaAtiva());
      const alcance = s.projetil ? ALCANCE_BESTA_AUTO
                    : s.alcance / METROS_POR_TILE + jogador.raio + alvoInimigo.tipo.raio + FOLGA_ALVO * 0.8;
      // (a folga é a mesma que o golpe dá ao alvo escolhido: assim Tomás golpeia
      // mesmo quando o inimigo empaca do outro lado de uma quina)
      const d = Math.hypot(alvoInimigo.x - jogador.x, alvoInimigo.y - jogador.y);
      // Com a besta, só atira se nada estiver no caminho do virote
      const visivel = !s.projetil || linhaDeTiroLivre(jogador.x, jogador.y, alvoInimigo.x, alvoInimigo.y);
      if (d <= alcance && visivel) {
        destino = null;
        atacar(anguloAte(alvoInimigo.x, alvoInimigo.y));
      } else {
        destino = { x: alvoInimigo.x, y: alvoInimigo.y };
      }
    }
  }

  // Durante um golpe, o jogador fica parado: o peso está no golpe
  if (ataque) return;

  // Segurando o botão esquerdo, o destino acompanha o cursor
  if (mouse.pressionado) definirDestinoPeloMouse();

  let mundoDX = 0, mundoDY = 0;
  const lento = typeof fatorDoChao === 'function' ? fatorDoChao(jogador.x, jogador.y) : 1;   // água rasa
  let velocidade = jogador.velocidade * lento;

  if (usandoTeclado) {
    // TECLADO: tem prioridade e cancela cliques e alvos.
    // Converte a direção da tela para o mundo e normaliza
    // (sem isso, a diagonal seria mais rápida).
    destino = null; npcAlvo = null; alvoInimigo = null; alvoItem = null; oratorioAlvo = null;
    mundoDX = telaDX + telaDY;
    mundoDY = telaDY - telaDX;
    const comprimento = Math.hypot(mundoDX, mundoDY);
    mundoDX /= comprimento;
    mundoDY /= comprimento;
  } else if (destino) {
    // MOUSE: anda até o destino, contornando paredes e colunas (js/caminhos.js)
    const distancia = Math.hypot(destino.x - jogador.x, destino.y - jogador.y);
    if (distancia < 0.05) {
      destino = null; // chegou
    } else {
      const portalNoDestino = ehPortal(tileEm(destino.x, destino.y));
      const p = passoNoCaminho(jogador, destino.x, destino.y, jogador.raio, portalNoDestino) || destino;
      const dx = p.x - jogador.x, dy = p.y - jogador.y;
      const dp = Math.hypot(dx, dy) || 1;
      mundoDX = dx / dp;
      mundoDY = dy / dp;
      // Perto do destino, diminui o passo para não "passar do ponto"
      velocidade = Math.min(jogador.velocidade * lento, distancia / dt);
    }
  }
  if (mundoDX || mundoDY) jogador.angulo = Math.atan2(mundoDY, mundoDX);

  // Move um eixo de cada vez, para deslizar ao longo das paredes
  // (bloqueia em paredes, NPCs e inimigos)
  // Andando por clique, só entra na passagem que é o destino do clique
  // (passar rente à boca do Poço a caminho de outro lugar não troca de mapa)
  const evitarPassagem = !usandoTeclado && destino;
  const outraPassagem = (x, y) => evitarPassagem && ehPortal(tileEm(x, y)) &&
    (Math.round(x) !== Math.round(destino.x) || Math.round(y) !== Math.round(destino.y));
  const bloqueado = (x, y) => outraPassagem(x, y) ||
                              colide(x, y, jogador.raio) ||
                              colideComNpc(x, y, jogador.raio) ||
                              colideComInimigo(x, y, jogador.raio) ||
                              colideComOratorio(x, y, jogador.raio);
  const antesX = jogador.x, antesY = jogador.y;
  const novoX = jogador.x + mundoDX * velocidade * dt;
  if (!bloqueado(novoX, jogador.y)) jogador.x = novoX;
  const novoY = jogador.y + mundoDY * velocidade * dt;
  if (!bloqueado(jogador.x, novoY)) jogador.y = novoY;

  // Preso numa parede indo para um clique? Desiste do destino.
  const andou = Math.hypot(jogador.x - antesX, jogador.y - antesY);
  if (destino && !mouse.pressionado && !alvoInimigo && andou < 0.001) destino = null;

  // Pisou numa passagem? Troca de mapa.
  const tileAqui = tileEm(jogador.x, jogador.y);
  const portal = ehPortal(tileAqui) ? mapaAtual.portais[tileAqui] : null;
  if (portal && portal.trava && !flags[portal.trava]) {
    // passagem trancada até um ponto da história: volta um passo
    avisarUmaVez(portal.aviso || 'Ainda não.');
    jogador.x = antesX; jogador.y = antesY; destino = null;
  } else if (portal) {
    // Entra direto só quem clicou (ou tocou) na própria passagem. Andando pelo
    // teclado ou pelo joystick, o jogo pergunta antes, para ninguém cair
    // numa masmorra só por passar por cima da entrada.
    const tx = Math.round(jogador.x), ty = Math.round(jogador.y);
    const clicou = !usandoTeclado && destino && Math.round(destino.x) === tx && Math.round(destino.y) === ty;
    if (clicou) iniciarTransicao(portal);
    else {
      jogador.x = antesX; jogador.y = antesY; destino = null;
      if (!passagemRecusada || passagemRecusada.x !== tx || passagemRecusada.y !== ty) perguntarPassagem(portal, tx, ty);
    }
  }
  // Recusou entrar: só pergunta de novo depois de se afastar da passagem
  if (passagemRecusada && Math.hypot(jogador.x - passagemRecusada.x, jogador.y - passagemRecusada.y) > 1.6) passagemRecusada = null;
}

// Desenha Tomás com os sprites do Flare (js/sprites.js), escolhendo a
// animação pelo que ele está fazendo. Se as imagens ainda não carregaram,
// usa o bloco antigo.
function desenharJogador(cx, cy) {
  const agora = performance.now();
  const andando = estaAndando(jogador);
  let nome = 'stance', fracao;
  if (jogador.giro) { nome = 'swing'; fracao = (agora / 260) % 1; }
  else if (jogador.investida) { nome = 'run'; fracao = (agora / 300) % 1; }
  else if (ataque) { nome = ataque.stats.projetil ? 'shoot' : 'swing'; fracao = ataque.t / ataque.total; }
  else if (jogador.rezando) { nome = 'block'; fracao = 0.99; }
  else if (andando) { nome = 'run'; fracao = faseDaCorrida(jogador, jogador.altura); }
  const tempo = animar(jogador, nome, agora);
  if (jogador.bencao > 0) {
    ctx.beginPath();
    ctx.ellipse(cx, cy, meiaLargPx(1.4), meiaLargPx(1.4) / 2, 0, 0, Math.PI * 2);
    ctx.strokeStyle = 'rgba(240, 225, 170, 0.6)';
    ctx.stroke();
  }
  desenharBrilhoDeNivel(cx, cy);
  if (desenharAvatar(aparenciaDoJogador(), jogador.angulo, nome, tempo, fracao, cx, cy, jogador.altura)) return;
  desenharJogadorBloco(cx, cy);
}

// O jogador como bloco (antes de as imagens carregarem)
function desenharJogadorBloco(cx, cy) {
  ctx.beginPath();
  ctx.ellipse(cx, cy, meiaLargPx(1), meiaLargPx(1) / 2, 0, 0, Math.PI * 2);
  ctx.fillStyle = 'rgba(0, 0, 0, 0.35)';
  ctx.fill();
  // Ajoelhado rezando, fica mais baixo; com a Bênção, um brilho claro em volta
  const altura = jogador.rezando ? 1.1 : jogador.altura;
  if (jogador.bencao > 0) {
    ctx.beginPath();
    ctx.ellipse(cx, cy, meiaLargPx(1.4), meiaLargPx(1.4) / 2, 0, 0, Math.PI * 2);
    ctx.strokeStyle = 'rgba(240, 225, 170, 0.6)';
    ctx.stroke();
  }
  desenharBlocoMetros(cx, cy, 0.6, altura, ['#e8b931', '#a07a12', '#c79a1c']);
  // Um risco no chão mostra para onde o jogador está virado
  const frente = mundoParaTela(jogador.x + Math.cos(jogador.angulo) * 0.45, jogador.y + Math.sin(jogador.angulo) * 0.45);
  const base = mundoParaTela(jogador.x, jogador.y);
  ctx.beginPath();
  ctx.moveTo(base.x + camera.x, base.y + camera.y);
  ctx.lineTo(frente.x + camera.x, frente.y + camera.y);
  ctx.strokeStyle = 'rgba(232, 185, 49, 0.8)';
  ctx.lineWidth = 2;
  ctx.stroke();
  ctx.lineWidth = 1;
}

;
