;
// ===== js/dialogo.js =====
// =====================================================================
// DIÁLOGO: a caixa de conversa na parte de baixo da tela
// =====================================================================
// Enquanto há um diálogo aberto, "dialogo" guarda o estado; senão é null.
// O jogador não se move durante a conversa.
//
// Controles: clique, Espaço ou E avançam. Nas escolhas, clique ou teclas 1 a 4.

let dialogo = null;
let viagemPendente = null;   // { destino, chegada } pedido numa conversa

// O que já aconteceu na história. Mais tarde o sistema de quests vai usar isso.
const flags = {};

const LETRAS_POR_SEGUNDO = 45; // velocidade do efeito de "máquina de escrever"

function iniciarDialogo(nome, npc) {
  const falas = DIALOGOS[nome];
  if (!falas) { console.warn('Diálogo não encontrado:', nome); return; }
  dialogo = { falas: falas, npc: npc, id: null };
  irParaFala('inicio');
}

function irParaFala(id) {
  const fala = dialogo.falas[id];
  dialogo.id = id;
  dialogo.fala = fala;
  dialogo.letras = 0;          // quantas letras já apareceram
  dialogo.opcaoSobMouse = -1;
  if (fala.efeito) aplicarEfeito(fala.efeito);
}

function aplicarEfeito(efeito) {
  if (efeito.flag) flags[efeito.flag] = true;
  if (efeito.flag2) flags[efeito.flag2] = true;
  if (efeito.estilo) escolherEstilo(efeito.estilo);
  if (efeito.loja) lojaPendente = efeito.loja;   // abre a loja quando a conversa acabar
  if (efeito.contratar) contratarCompanheiro(efeito.contratar);
  if (efeito.tratar) tratarCompanheiro();
  if (efeito.ouro) { jogador.ouro += efeito.ouro; avisar(`Você recebeu ${efeito.ouro} de ouro.`); }
  if (efeito.aviso) avisar(efeito.aviso);
  // { item: { base: 'cruz', raridade: 'lendario' } } dá um item (no alforje, ou no chão se não couber)
  // { itens: [ {...}, {...} ] } dá vários
  for (const pedido of [efeito.item, ...(efeito.itens || [])].filter(Boolean)) {
    const it = criarItem(pedido.base, pedido.raridade || 'comum');
    if (jogador.alforje.length < TAMANHO_ALFORJE) jogador.alforje.push(it);
    else largarItem(it, jogador.x, jogador.y);
  }
  // { lendario: 'Nome' } dá um item lendário específico (js/equipamento.js, LENDARIOS)
  if (efeito.lendario) {
    const l = LENDARIOS.find((x) => x.nome === efeito.lendario);
    if (l) {
      const it = criarItem(l.base, 'lendario');
      Object.assign(it, { nome: l.nome, efeitos: { ...l.efeitos }, texto: l.texto });
      if (jogador.alforje.length < TAMANHO_ALFORJE) jogador.alforje.push(it); else largarItem(it, jogador.x, jogador.y);
      avisar(`Você recebeu: ${l.nome}`);
    }
  }
  // viajar para outro mapa quando a conversa acabar (ex.: partir com o exército)
  if (efeito.viajar) viagemPendente = efeito.viajar;
  // { remedios: { oximel: 2 } } coloca remédios no cinto
  for (const [tipo, n] of Object.entries(efeito.remedios || {})) {
    cinto[tipo] = Math.min(maximoPorRemedio(), cinto[tipo] + n);
    avisar(`Você recebeu: ${n} × ${REMEDIOS[tipo].nome}`);
  }
}

function textoCompleto() {
  return dialogo.letras >= dialogo.fala.texto.length;
}

// Avança: se o texto ainda está aparecendo, mostra tudo de uma vez;
// senão, vai para a próxima fala ou fecha o diálogo.
function avancarDialogo() {
  if (!textoCompleto()) { dialogo.letras = dialogo.fala.texto.length; return; }
  if (dialogo.fala.escolhas) return; // precisa escolher uma opção
  if (dialogo.fala.proximo) irParaFala(dialogo.fala.proximo);
  else dialogo = null;
}

function escolherOpcao(indice) {
  const opcoes = dialogo.fala.escolhas;
  if (!opcoes || !textoCompleto() || !opcoes[indice]) return;
  const escolha = opcoes[indice];
  if (escolha.efeito) aplicarEfeito(escolha.efeito);
  irParaFala(escolha.ir);
}

function atualizarDialogo(dt) {
  if (!dialogo) return;
  dialogo.letras = Math.min(dialogo.fala.texto.length, dialogo.letras + LETRAS_POR_SEGUNDO * dt);
}

// --- Entrada durante o diálogo ---

window.addEventListener('keydown', (e) => {
  if (!dialogo) return;
  const tecla = e.key.toLowerCase();
  if (tecla === ' ' || tecla === 'enter' || tecla === 'e') {
    e.preventDefault();
    // Evita que o mesmo "E" que abriu a conversa já pule a primeira fala
    if (dialogo.letras === 0) return;
    avancarDialogo();
  }
  if (tecla >= '1' && tecla <= '4') escolherOpcao(Number(tecla) - 1);
});

canvas.addEventListener('mousedown', (e) => {
  if (!dialogo || e.button !== 0) return;
  if (dialogo.letras === 0) return; // o clique que abriu a conversa
  if (dialogo.fala.escolhas && textoCompleto()) {
    const i = opcaoNoPonto(e.clientX, e.clientY);
    if (i >= 0) escolherOpcao(i);
  } else {
    avancarDialogo();
  }
});

// --- Desenho da caixa ---

// Quebra um texto em linhas que caibam numa largura (em pixels)
function quebrarLinhas(texto, largura) {
  texto = T(texto);                              // o idioma do jogo (js/idioma.js)
  const palavras = texto.split(' ');
  const linhas = [];
  let atual = '';
  for (const p of palavras) {
    const teste = atual ? atual + ' ' + p : p;
    if (ctx.measureText(teste).width > largura && atual) {
      linhas.push(atual);
      atual = p;
    } else {
      atual = teste;
    }
  }
  if (atual) linhas.push(atual);
  return linhas;
}

function desenharDialogo() {
  if (!dialogo) return;
  const fala = dialogo.fala;
  const toque = typeof MODO !== 'undefined' && MODO.toque;
  const largura = Math.min(760, canvas.width - 32);
  const x = (canvas.width - largura) / 2;
  const margem = toque ? 16 : 20;
  const alturaLinha = toque ? 23 : 22;
  const fonteTexto = (toque ? '17px' : '16px') + ' Alegreya, Georgia, serif';
  const fonteOpcao = (toque ? '16px' : '15px') + ' Alegreya, Georgia, serif';

  // Mede tudo antes de desenhar: texto, opções (que podem quebrar em várias linhas)
  ctx.font = fonteTexto;
  const linhasTexto = quebrarLinhas(fala.texto, largura - margem * 2 - 8);
  const opcoes = (fala.escolhas && textoCompleto()) ? fala.escolhas : [];
  ctx.font = fonteOpcao;
  const linhasOpcoes = opcoes.map((op, i) => quebrarLinhas(`${i + 1}. ${op.texto}`, largura - margem * 2 - 12));
  const altOpcao = (ls) => Math.max(toque ? 38 : 26, ls.length * 19 + 8);
  const alturaOpcoes = opcoes.length ? 12 + linhasOpcoes.reduce((s, ls) => s + altOpcao(ls) + 4, 0) : 0;
  const cabecalho = margem + 26;
  const rodape = margem + 8;

  // A caixa cresce até caber; se o texto for maior que a tela, ele rola
  const alturaMax = canvas.height - (toque ? 20 : 32) - alturaHud();
  const alturaTextoToda = linhasTexto.length * alturaLinha + 6;
  const espacoTexto = Math.max(alturaLinha * 2, Math.min(alturaTextoToda, alturaMax - cabecalho - alturaOpcoes - rodape));
  const altura = cabecalho + espacoTexto + alturaOpcoes + rodape;
  const y = canvas.height - altura - (toque ? 10 : 16) - alturaHud();

  // Fundo da caixa
  ctx.fillStyle = 'rgba(20, 17, 14, 0.95)';
  ctx.fillRect(x, y, largura, altura);
  ctx.strokeStyle = '#8c7a55';
  ctx.lineWidth = 2;
  ctx.strokeRect(x + 1, y + 1, largura - 2, altura - 2);
  ctx.lineWidth = 1;

  // Quem fala
  ctx.font = 'bold 15px Alegreya, Georgia, serif';
  ctx.fillStyle = '#e8b931';
  ctx.fillText(fala.quem, x + margem, y + margem + 12);

  // Texto, aparecendo letra a letra, numa região que rola
  const tx = x + margem, ty = y + cabecalho, tw = largura - margem * 2 + 6;
  const chave = 'dialogo';
  if (dialogo.falaRolada !== fala) { zerarRolagem(chave); dialogo.falaRolada = fala; }
  let off = regiaoRolavel(chave, tx, ty, tw, espacoTexto, alturaTextoToda);
  // enquanto o texto aparece, acompanha a linha que está sendo escrita
  if (!textoCompleto()) {
    let resto = Math.floor(dialogo.letras), linhaAtual = 0;
    for (let i = 0; i < linhasTexto.length; i++) { if (resto <= linhasTexto[i].length) { linhaAtual = i; break; } resto -= linhasTexto[i].length + 1; linhaAtual = i; }
    mostrarAte(chave, (linhaAtual + 1) * alturaLinha + 6);
    off = ROLAGEM[chave].y;
  }
  ctx.save();
  recortar(tx - 2, ty, tw, espacoTexto);
  ctx.font = fonteTexto;
  ctx.fillStyle = '#efe7d6';
  let restantes = Math.floor(dialogo.letras);
  linhasTexto.forEach((linha, i) => {
    const parte = linha.slice(0, Math.max(0, restantes));
    restantes -= linha.length + 1;
    const ly = ty + 16 + i * alturaLinha - off;
    if (ly > ty - alturaLinha && ly < ty + espacoTexto + alturaLinha) ctx.fillText(parte, tx, ly);
  });
  ctx.restore();
  barraDeRolagem(chave);

  // Opções de escolha (sempre à vista, embaixo do texto)
  dialogo.retOpcoes = [];
  dialogo.opcaoSobMouse = -1;
  let oy = ty + espacoTexto + 12;
  opcoes.forEach((op, i) => {
    const ls = linhasOpcoes[i], h = altOpcao(ls);
    const r = { x: x + margem - 6, y: oy, w: largura - margem * 2 + 12, h };
    dialogo.retOpcoes.push(r);
    const sob = !toque && mouseEm(r);
    if (sob) dialogo.opcaoSobMouse = i;
    ctx.fillStyle = sob ? 'rgba(232, 185, 49, 0.18)' : 'rgba(255, 255, 255, 0.05)';
    ctx.fillRect(r.x, r.y, r.w, r.h);
    if (toque) { ctx.strokeStyle = 'rgba(140, 122, 85, 0.5)'; ctx.strokeRect(r.x + 0.5, r.y + 0.5, r.w - 1, r.h - 1); }
    ctx.font = fonteOpcao;
    ctx.fillStyle = sob ? '#ffe9a8' : '#d9cfbb';
    const y0 = r.y + (h - ls.length * 19) / 2 + 14;
    ls.forEach((l, k) => ctx.fillText(l, x + margem, y0 + k * 19));
    oy += h + 4;
  });

  // Dica de como continuar
  if (textoCompleto() && !opcoes.length) {
    ctx.font = '12px monospace';
    ctx.fillStyle = '#9c8f74';
    ctx.textAlign = 'right';
    const verbo = toque ? 'toque' : 'clique ou Espaço';
    ctx.fillText(fala.proximo ? `${verbo} ▸` : `${verbo} para fechar`, x + largura - margem, y + altura - 10);
    ctx.textAlign = 'left';
  }
}

// Qual opção está no ponto (calculado na hora do clique, não no quadro anterior:
// no celular o dedo pousa e clica no mesmo instante)
function opcaoNoPonto(px, py) {
  if (!dialogo || !dialogo.retOpcoes) return -1;
  return dialogo.retOpcoes.findIndex((r) => px >= r.x && px <= r.x + r.w && py >= r.y && py <= r.y + r.h);
}

