const RAIO_NPC = 0.25;         // tamanho para colisão, em tiles
const DISTANCIA_CONVERSA = 1.3; // quão perto (em tiles) o jogador precisa estar

// NPCs do mapa onde o jogador está agora ("aparece" = só em certa parte da história)
function npcsDoMapa() {
  return NPCS.filter((n) => MAPAS[n.mapa] === mapaAtual && (!n.aparece || n.aparece()));
}

// O jogador esbarra num NPC? (usado no movimento)
function colideComNpc(x, y, raio) {
  return npcsDoMapa().some((n) => Math.hypot(n.x - x, n.y - y) < raio + RAIO_NPC);
}

// O NPC mais próximo do jogador, se estiver perto o bastante para conversar
function npcProximo() {
  let melhor = null, melhorDist = DISTANCIA_CONVERSA;
  for (const n of npcsDoMapa()) {
    const d = Math.hypot(n.x - jogador.x, n.y - jogador.y);
    if (d < melhorDist) { melhor = n; melhorDist = d; }
  }
  return melhor;
}

// Qual NPC está sob o cursor? Comparamos na TELA, porque o jogador clica
// no corpo do personagem, que fica acima do chão.
function npcSobOMouse() {
  for (const n of npcsDoMapa()) {
    const p = mundoParaTela(n.x, n.y);
    const sx = (p.x + camera.x) * zoom;
    const sy = (p.y + camera.y) * zoom;
    const meiaLarg = (meiaLargPx(0.6) + 6) * zoom;
    const alturaTela = altPx(n.altura) * zoom;
    if (Math.abs(mouse.x - sx) < meiaLarg && mouse.y < sy + 6 * zoom && mouse.y > sy - alturaTela - 8) {
      return n;
    }
  }
  return null;
}

function conversarCom(npc) {
  destino = null;
  npcAlvo = null;
  iniciarDialogo(npc.conversa(), npc);
}

// NPC que o jogador clicou e está indo encontrar
let npcAlvo = null;

// Chamado a cada quadro: se o jogador clicou num NPC e chegou perto, conversa
function atualizarNpcs() {
  if (npcAlvo && Math.hypot(npcAlvo.x - jogador.x, npcAlvo.y - jogador.y) < DISTANCIA_CONVERSA) {
    conversarCom(npcAlvo);
  }
}

// (O clique num NPC é tratado em js/entrada.js: o jogador anda até ele
// e, ao chegar perto, atualizarNpcs() começa a conversa.)

// Tecla E: conversa com o NPC mais próximo
window.addEventListener('keydown', (e) => {
  if (e.key.toLowerCase() !== 'e' || dialogo || transicao || menuOratorio) return;
  const npc = npcProximo();
  if (npc) conversarCom(npc);
});

// Desenho de um NPC: com sprites, virado para o jogador quando ele está perto
function desenharNpc(npc, cx, cy) {
  const dist = Math.hypot(jogador.x - npc.x, jogador.y - npc.y);
  const angulo = dist < 5 ? Math.atan2(jogador.y - npc.y, jogador.x - npc.x) : Math.PI / 4; // senão, olha para o sul
  // Pose à vontade (respirando), não a postura de combate
  // caído (ferido no chão): o último quadro da animação de queda
  if (npc.caido && npc.visual && desenharAvatar(APARENCIAS[npc.visual], Math.PI / 4, 'die', 1, 0.99, cx, cy, npc.altura)) return;
  const tempo = animar(npc, 'idle', performance.now());
  if (npc.visual && desenharAvatar(APARENCIAS[npc.visual], angulo, 'idle', tempo, undefined, cx, cy, npc.altura)) return;
  ctx.beginPath();
  ctx.ellipse(cx, cy, meiaLargPx(1), meiaLargPx(1) / 2, 0, 0, Math.PI * 2);
  ctx.fillStyle = 'rgba(0, 0, 0, 0.35)';
  ctx.fill();
  desenharBlocoMetros(cx, cy, 0.6, npc.altura, npc.cores);
}

