// Inimigos do mapa atual. São recriados sempre que o jogador entra no mapa.
let inimigos = [];

function criarInimigosDoMapa(nomeMapa) {
  inimigos = (SPAWNS[nomeMapa] || []).map((s) => {
    const t = TIPOS_INIMIGO[s.tipo];
    return {
      tipo: t, x: s.x, y: s.y, casaX: s.x, casaY: s.y,
      vida: t.vida, estado: 'parado', preparo: 0, recarga: 0,
      morto: false, tempoMorto: 0, flash: 0
    };
  });
  if (typeof promoverLideres === 'function') promoverLideres(nomeMapa);   // líderes e campeões (js/achados.js)
}

function inimigosVivos() {
  return inimigos.filter((i) => !i.morto);
}

function atualizarInimigos(dt) {
  for (const ini of inimigos) {
    if (ini.morto) { ini.tempoMorto += dt; continue; }
    const t = ini.tipo;
    ini.flash = Math.max(0, ini.flash - dt);
    ini.recarga = Math.max(0, ini.recarga - dt);
    // Atordoado (empurrão de escudo): fica parado por um instante
    if (ini.atordoado > 0) { ini.atordoado -= dt; continue; }
    // Movido por outro sistema (a carga do Qutlugh, a fuga no fim da batalha)
    if (ini.controlado) continue;

    // Quem ele ataca: o jogador ou o companheiro, o que estiver mais perto
    const alvo = alvoDoInimigo(ini);
    ini.alvo = alvo;
    const dx = alvo.x - ini.x, dy = alvo.y - ini.y;
    const dist = Math.hypot(dx, dy);
    const alcanceTiles = t.alcance / METROS_POR_TILE + t.raio + 0.2;

    // Percebe o jogador e vai atrás; desiste se ele fugir para longe
    if (ini.estado !== 'perseguindo' && dist < t.aggro && jogador.vida > 0) ini.estado = 'perseguindo';
    if (ini.estado === 'perseguindo' && dist > t.aggro * 2.5 && !ini.aggroBatalha) ini.estado = 'voltando';
    // Segurando um posto (o muro de escudos): só sai dele contra quem chega perto
    let paraOPosto = false;
    if (ini.posto && ini.preparo <= 0 && Math.hypot(alvo.x - ini.posto.x, alvo.y - ini.posto.y) > ini.posto.raio) {
      if (Math.hypot(ini.posto.x - ini.x, ini.posto.y - ini.y) < 0.15) { ini.estado = 'parado'; ini.angulo = ini.posto.angulo; continue; }
      ini.estado = 'perseguindo'; paraOPosto = true;
    }

    // Atacando: espera o "preparo" e acerta (ou atira) se ainda der
    if (ini.preparo > 0) {
      ini.preparo -= dt;
      if (ini.preparo <= 0) {
        if (t.comportamento === 'atirador') atirarFlecha(ini);
        else if (dist <= alcanceTiles + 0.15 && (typeof dentroDoGolpe !== 'function' || dentroDoGolpe(ini, alvo))) {
          if (alvo === jogador) ferirJogador(sortear(t.dano[0], t.dano[1]), ini);
          else if (alvo.ferir) alvo.ferir(sortear(t.dano[0], t.dano[1]), ini);
          else if (companheiroAtivo()) ferirCompanheiro(sortear(t.dano[0], t.dano[1]));
        }
        ini.recarga = t.recarga;
        ini.angGolpe = undefined;
        // bate e corre (às vezes: nem todo golpe vira fuga)
        if (t.comportamento === 'recua' && Math.random() < (t.chanceRecuo ?? 1)) ini.recuo = t.tempoRecuo;
      }
      continue;
    }

    let alvoX = null, alvoY = null, fugindo = false;
    if (paraOPosto) {
      alvoX = ini.posto.x; alvoY = ini.posto.y;
    } else if (ini.estado === 'perseguindo' && ini.recuo > 0) {
      // Batedor: depois do golpe, se afasta do jogador por um instante
      ini.recuo -= dt;
      alvoX = ini.x - dx; alvoY = ini.y - dy; fugindo = true;
    } else if (ini.estado === 'perseguindo' && t.comportamento === 'atirador') {
      // Arqueiro: atira de longe; se o jogador chega perto, recua
      // Recua só por um tempo: depois de ~1,5 s fugindo, cansa e atira de perto mesmo
      const [perto, longe] = t.distancia;
      const enxerga = linhaDeTiroLivre(ini.x, ini.y, alvo.x, alvo.y);
      ini.cansado = Math.max(0, (ini.cansado || 0) - dt);
      const podeFugir = ini.cansado <= 0;
      if (dist < perto && podeFugir) {
        alvoX = ini.x - dx; alvoY = ini.y - dy; fugindo = true;
        ini.fuga = (ini.fuga || 0) + dt;
        if (ini.fuga > 1.5) { ini.fuga = 0; ini.cansado = 4; }
      }
      else if (dist > longe || !enxerga) { alvoX = alvo.x; alvoY = alvo.y; }
      else {
        if (ini.recarga <= 0) { ini.preparo = t.preparo; ini.angGolpe = Math.atan2(dy, dx); }   // para e mira (a direção trava)
        continue;
      }
    } else if (ini.estado === 'perseguindo') {
      if (dist <= alcanceTiles) {
        if (ini.recarga <= 0) { ini.preparo = t.preparo; ini.angGolpe = Math.atan2(dy, dx); } // começa o ataque (a direção trava)
        continue;
      }
      alvoX = alvo.x; alvoY = alvo.y;
    } else if (ini.estado === 'voltando') {
      if (Math.hypot(ini.casaX - ini.x, ini.casaY - ini.y) < 0.2) {
        // de volta em casa: só se cura se ninguém o feriu nos últimos 10 s (senão, a besta de longe nunca vencia)
        ini.estado = 'parado'; if (!((ini.semDano ?? 99) < 10)) ini.vida = t.vida; continue;
      }
      alvoX = ini.casaX; alvoY = ini.casaY;
    }
    if (alvoX === null) continue;

    // Contorna paredes e colunas (js/caminhos.js); fugindo, vai reto mesmo
    if (!fugindo) {
      const p = passoNoCaminho(ini, alvoX, alvoY, t.raio);
      if (p) { alvoX = p.x; alvoY = p.y; }
      else if (ini.estado === 'perseguindo') { ini.estado = 'voltando'; continue; }   // não há como chegar
    }

    // Anda em direção ao alvo, um eixo de cada vez, sem atravessar paredes,
    // o jogador ou outros inimigos
    const ax = alvoX - ini.x, ay = alvoY - ini.y;
    const d = Math.hypot(ax, ay) || 1;
    ini.fugindo = fugindo;
    const passo = t.vel * dt * (fugindo ? 0.7 : 1) * (typeof fatorDoChao === 'function' ? fatorDoChao(ini.x, ini.y) : 1);
    const livre = (x, y) => !colide(x, y, t.raio) &&
      Math.hypot(jogador.x - x, jogador.y - y) >= t.raio + jogador.raio &&
      !inimigos.some((o) => o !== ini && !o.morto && Math.hypot(o.x - x, o.y - y) < t.raio + o.tipo.raio) &&
      !(typeof colideComAliado === 'function' && colideComAliado(x, y, t.raio));
    const nx = ini.x + (ax / d) * passo;
    if (livre(nx, ini.y)) ini.x = nx;
    const ny = ini.y + (ay / d) * passo;
    if (livre(ini.x, ny)) ini.y = ny;
  }
}

// O jogador, ou o companheiro se ele estiver bem mais perto do inimigo
function alvoDoInimigo(ini) {
  // Na batalha de Montgisard há outros alvos: os Templários e a Vera Cruz
  if (typeof alvoNaBatalha === 'function') { const a = alvoNaBatalha(ini); if (a) return a; }
  if (!companheiroNoMapa() || companheiro.morto) return jogador;
  const dj = Math.hypot(jogador.x - ini.x, jogador.y - ini.y);
  const dc = Math.hypot(companheiro.x - ini.x, companheiro.y - ini.y);
  return dc + 0.5 < dj ? companheiro : jogador;
}

// Um arqueiro solta a flecha na direção do alvo (com um pequeno erro de mira)
function atirarFlecha(ini) {
  const alvo = ini.alvo || jogador;
  if (!linhaDeTiroLivre(ini.x, ini.y, alvo.x, alvo.y)) return;
  const erro = (Math.random() - 0.5) * 0.12;
  // a flecha vai para onde ele mirou no começo (quem rola sai da linha)
  const a = (ini.angGolpe ?? Math.atan2(alvo.y - ini.y, alvo.x - ini.x)) + erro;
  projeteis.push({
    x: ini.x, y: ini.y, dx: Math.cos(a), dy: Math.sin(a),
    restante: ini.tipo.alcance / METROS_POR_TILE, inimigo: true, origem: ini,
    dano: sortear(ini.tipo.dano[0], ini.tipo.dano[1])
  });
}

// O jogador esbarra num inimigo vivo?
function colideComInimigo(x, y, raio) {
  return inimigos.some((i) => !i.morto && Math.hypot(i.x - x, i.y - y) < raio + i.tipo.raio);
}

// Qual inimigo está sob o cursor (comparando na tela, no corpo dele)
function inimigoSobOMouse() {
  for (const ini of inimigosVivos()) {
    if (typeof explorado === 'function' && !explorado(ini.x, ini.y)) continue;   // na névoa
    const p = mundoParaTela(ini.x, ini.y);
    const sx = (p.x + camera.x) * zoom, sy = (p.y + camera.y) * zoom;
    const meia = (meiaLargPx(Math.max(ini.tipo.largura, 0.6)) + 8) * zoom;
    if (Math.abs(mouse.x - sx) < meia && mouse.y < sy + 8 * zoom &&
        mouse.y > sy - altPx(Math.max(ini.tipo.altura, 0.9)) * zoom - 8) return ini;
  }
  return null;
}

function desenharInimigo(ini, cx, cy) {
  const t = ini.tipo;
  if (t.elite) desenharAuraDeElite(ini, cx, cy);
  if (t.visual && desenharInimigoSprite(ini, cx, cy)) return;
  if (ini.morto) {
    // Corpo caído: um bloco baixo e escuro, que some aos poucos
    ctx.globalAlpha = Math.max(0, 1 - ini.tempoMorto / 8);
    desenharBlocoMetros(cx, cy, Math.max(t.largura, t.altura * 0.6), 0.2, ['#3d2a22', '#2a1c16', '#33231c']);
    ctx.globalAlpha = 1;
    return;
  }
  ctx.beginPath();
  ctx.ellipse(cx, cy, meiaLargPx(t.largura * 1.4), meiaLargPx(t.largura * 1.4) / 2, 0, 0, Math.PI * 2);
  ctx.fillStyle = 'rgba(0, 0, 0, 0.35)';
  ctx.fill();
  // Pisca em branco ao ser atingido; fica avermelhado ao preparar um ataque
  // e fica azulado quando atordoado
  const cores = ini.flash > 0 ? ['#ffffff', '#dddddd', '#eeeeee']
              : ini.atordoado > 0 ? ['#8fa3c4', '#5a6b88', '#738aa8']
              : ini.preparo > 0 ? ['#d0604a', '#8a3a2c', '#a8483a'] : t.cores;
  // Enquanto não tem sprite próprio, o chacal dá pulinhos ao correr
  // (um a cada ~0,9 m, preso à distância, como os passos dos humanos)
  let salto = 0;
  if (estaAndando(ini)) salto = Math.abs(Math.sin(Math.PI * ((ini._distancia || 0) / 0.9))) * altPx(0.12);
  desenharBlocoMetros(cx, cy - salto, t.largura, t.altura, cores);
}

// Inimigo desenhado com sprites (humanos e animais). Devolve false se as imagens não estão prontas.
function desenharInimigoSprite(ini, cx, cy) {
  const t = ini.tipo;
  const andando = estaAndando(ini);
  // Olha para o jogador quando o persegue; ao voltar, para onde está indo
  const foco = ini.alvo || jogador;
  if (ini.estado === 'perseguindo') ini.angulo = Math.atan2(foco.y - ini.y, foco.x - ini.x);
  else if (ini.estado === 'voltando') ini.angulo = Math.atan2(ini.casaY - ini.y, ini.casaX - ini.x);
  if (ini.angulo === undefined) ini.angulo = Math.PI / 4;

  let nome = 'stance', fracao, tempo;
  if (ini.morto) { nome = 'die'; tempo = ini.tempoMorto; }
  else if (ini.preparo > 0) { nome = t.comportamento === 'atirador' ? 'shoot' : 'swing'; fracao = 1 - ini.preparo / t.preparo; }
  else if (ini.atordoado > 0) { nome = 'hit'; fracao = 0.99; }
  else if (andando) { nome = 'run'; fracao = faseDaCorrida(ini, t.altura, APARENCIAS[t.visual].cicloCorrida); }
  // fugindo, ele corre de costas para o jogador
  if (andando && ini.fugindo && !ini.morto) ini.angulo = Math.atan2(ini.y - foco.y, ini.x - foco.x);
  const t2 = animar(ini, nome, performance.now());
  if (tempo === undefined) tempo = t2;

  // Corpos caídos somem aos poucos; ao levar um golpe, brilha por um instante
  if (ini.morto) ctx.globalAlpha = Math.max(0, 1 - Math.max(0, ini.tempoMorto - 4) / 4);
  if (ini.flash > 0) ctx.filter = 'brightness(2.2)';
  const ok = desenharAvatar(APARENCIAS[t.visual], ini.angulo, nome, tempo, fracao, cx, cy, t.altura);
  ctx.filter = 'none';
  ctx.globalAlpha = 1;
  return ok;
}

// Barra de vida sobre o inimigo (só depois de ferido) — desenhada sem zoom
function desenharVidaInimigo(ini, cx, cy) {
  if (ini.morto || ini.vida >= ini.tipo.vida) return;
  const larg = 34;
  const x = cx * zoom - larg / 2;
  const y = (cy - altPx(ini.tipo.altura)) * zoom - 14;
  ctx.fillStyle = 'rgba(0,0,0,0.6)';
  ctx.fillRect(x - 1, y - 1, larg + 2, 6);
  ctx.fillStyle = '#c0392b';
  ctx.fillRect(x, y, larg * (ini.vida / ini.tipo.vida), 4);
}

;
// ===== js/combate.js =====
// =====================================================================
// COMBATE: ataques do jogador, virotes, dano, maestria e morte
// =====================================================================
// Sem magia: cada golpe tem alcance real (em metros), uma largura em graus
// e um tempo. O golpe só acerta no "momento do impacto", um pouco depois
// de começar, e quem estiver dentro do alcance e do arco leva o dano.

let ataque = null;         // golpe em andamento do jogador, ou null
let projeteis = [];        // virotes de besta voando
let numeros = [];          // números de dano subindo na tela
let mensagens = [];        // avisos no centro da tela
let alvoInimigo = null;    // inimigo clicado: o jogador vai até ele e ataca

const MOMENTO_IMPACTO = 0.35;  // o golpe acerta a 35% da duração do ataque
// Golpe com alvo (clicou no inimigo): o golpe acompanha o alvo e tem esta folga
// de alcance (tiles), para quem recua no último instante não escapar sempre
const FOLGA_ALVO = 0.45;
// Cambaleio: um golpe que tira pelo menos esta fração da vida máxima faz o inimigo
// cambalear (interrompe o ataque e o recuo), como o "hit recovery" do Diablo 2
const CAMBALEIO_FRACAO = 0.25, CAMBALEIO_TEMPO = 0.4;
const VELOCIDADE_VIROTE = 20;  // tiles por segundo (40 m/s)
const ALCANCE_BESTA_AUTO = 9;  // ao clicar num inimigo com a besta, atira desta distância (tiles)

function armaAtiva() {
  return jogador.armas[jogador.armaAtiva] || PUNHOS;   // sem arma: punhos
}

function avisar(texto) {
  mensagens.push({ texto, tempo: 3 });
}

// Há caminho livre para um virote entre dois pontos? (sem paredes, pedras ou árvores)
function linhaDeTiroLivre(x0, y0, x1, y1) {
  // passos curtos: o virote passa rente às quinas, e a mira tem de ver as mesmas quinas
  const passos = Math.ceil(Math.hypot(x1 - x0, y1 - y0) / 0.05);
  for (let i = 1; i < passos; i++) {
    const t = tileEm(x0 + (x1 - x0) * i / passos, y0 + (y1 - y0) * i / passos);
    if (ehSolido(t) && !TILES[t]?.agua) return false;
  }
  return true;
}

// Ângulo (no mundo) de onde o jogador está até um ponto
function anguloAte(x, y) {
  return Math.atan2(y - jogador.y, x - jogador.x);
}

// Começa um ataque na direção de um ângulo
function atacar(angulo) {
  const item = armaAtiva();
  if (ataque || !item || jogador.rezando || jogador.giro || jogador.investida) return;
  const s = statsDaArma(item);
  jogador.angulo = angulo;
  ataque = { t: 0, total: s.tempo, angulo, stats: s, aplicado: false, alvo: alvoInimigo };
}

let ultimoAviso = 0;
function avisarUmaVez(texto) {
  if (performance.now() - ultimoAviso > 1200) { avisar(texto); ultimoAviso = performance.now(); }
}

function atualizarAtaque(dt) {
  if (!ataque) return;
  ataque.t += dt;
  if (!ataque.aplicado && ataque.t >= ataque.total * MOMENTO_IMPACTO) {
    ataque.aplicado = true;
    const s = ataque.stats;
    if (s.projetil) {
      desgasteAoAcertar();                 // cada tiro gasta um pouco a besta
      // Tiro duplo e chuva de virotes: vários virotes em leque
      const n = s.virotes || 1, leque = (s.leque || 0) * Math.PI / 180;
      for (let k = 0; k < n; k++) {
        const a = ataque.angulo + (n > 1 ? -leque / 2 + leque * k / (n - 1) : 0);
        projeteis.push({
          x: jogador.x, y: jogador.y, dx: Math.cos(a), dy: Math.sin(a),
          restante: s.alcance / METROS_POR_TILE, stats: s, perfura: !!s.perfura, acertados: []
        });
      }
      if (s.recuo) recuarDepoisDoTiro(ataque.angulo, s.recuo);
      efeitoDeTiro(ataque.angulo);
    } else {
      // Acerta todos dentro do alcance e do arco do golpe
      const alcance = s.alcance / METROS_POR_TILE + jogador.raio;
      let acertou = false;
      // O alvo escolhido: o golpe vira para ele e alcança com uma pequena folga
      const alvo = ataque.alvo;
      if (alvo && !alvo.morto && Math.hypot(alvo.x - jogador.x, alvo.y - jogador.y) <= alcance + alvo.tipo.raio + FOLGA_ALVO) {
        ataque.angulo = jogador.angulo = anguloAte(alvo.x, alvo.y);
        ferirInimigo(alvo, s); acertou = true;
      }
      for (const ini of inimigosVivos()) {
        if (ini === alvo) continue;
        const d = Math.hypot(ini.x - jogador.x, ini.y - jogador.y);
        if (d > alcance + ini.tipo.raio) continue;
        let dif = Math.abs(anguloAte(ini.x, ini.y) - ataque.angulo);
        if (dif > Math.PI) dif = 2 * Math.PI - dif;
        if (dif <= (s.arco / 2) * Math.PI / 180 || d < ini.tipo.raio + jogador.raio + 0.1) { ferirInimigo(ini, s); acertou = true; }
      }
      if (acertou) desgasteAoAcertar();    // o golpe que acerta gasta a arma
      efeitoDeGolpe(ataque);               // o rastro do aço (js/efeitos.js)
      golpeNosAchados(ataque.angulo, alcance, s.arco);   // jarros e baús quebram com o golpe
    }
  }
  // Fim do golpe; na Fúria (série), o próximo golpe começa em seguida
  if (ataque.t >= ataque.total) ataque = proximoDaSerie(ataque);
}

function atualizarProjeteis(dt) {
  // O virote anda em passinhos: num passo grande ele "pulava" o inimigo colado
  // em Tomás (tiro à queima-roupa que atravessava sem acertar)
  const total = VELOCIDADE_VIROTE * dt, sub = Math.max(1, Math.ceil(total / 0.15));
  for (let k = 0; k < sub; k++) passoDosProjeteis(total / sub);
  projeteis = projeteis.filter((p) => p.restante > 0);
}

function passoDosProjeteis(passo) {
  for (const p of projeteis) {
    if (p.restante <= 0) continue;
    p.x += p.dx * passo; p.y += p.dy * passo; p.restante -= passo;
    if (ehSolido(tileEm(p.x, p.y)) && !TILES[tileEm(p.x, p.y)]?.agua) p.restante = 0; // bateu na parede
    if (p.inimigo) {
      // flecha de um inimigo: só fere o jogador
      if (jogador.vida > 0 && Math.hypot(jogador.x - p.x, jogador.y - p.y) < jogador.raio + 0.15) {
        ferirJogador(p.dano, p.origem); p.restante = 0;
      } else if (companheiroNoMapa() && !companheiro.morto && Math.hypot(companheiro.x - p.x, companheiro.y - p.y) < RAIO_COMP + 0.15) {
        ferirCompanheiro(p.dano); p.restante = 0;
      } else if (typeof alvosDaBatalha === 'function') {
        const a = alvosDaBatalha().find((a) => Math.hypot(a.x - p.x, a.y - p.y) < (a.raio || 0.25) + 0.15);
        if (a) { a.ferir(p.dano, p.origem); p.restante = 0; }
      }
      continue;
    }
    // Virote perfurante: atravessa e acerta cada inimigo uma vez
    const alvo = inimigosVivos().find((i) => !p.acertados?.includes(i) && Math.hypot(i.x - p.x, i.y - p.y) < i.tipo.raio + 0.15);
    if (alvo) {
      ferirInimigo(alvo, p.stats);
      if (p.perfura) p.acertados.push(alvo); else p.restante = 0;
    }
  }
}

function ferirInimigo(ini, s) {
  let dano = sortear(s.dano[0], s.dano[1]);
  // Golpe crítico: dano dobrado
  const critico = s.critico && Math.random() * 100 < s.critico;
  if (critico) dano *= 2;
  // Inimigo com escudo segura parte do golpe que vem de frente (não quando atordoado)
  const escudoIni = ini.guardaQuebrada > 0 ? 0 : (ini.escudo ?? ini.tipo.escudo);   // guarda quebrada: sem escudo
  if (escudoIni && !s.ignoraEscudo && !(ini.atordoado > 0) && ini.angulo !== undefined) {
    let dif = Math.abs(Math.atan2(jogador.y - ini.y, jogador.x - ini.x) - ini.angulo);
    if (dif > Math.PI) dif = 2 * Math.PI - dif;
    if (dif < Math.PI / 2) dano = Math.max(1, Math.round(dano * (1 - escudoIni)));
  }
  // Dano sagrado: soma-se ao golpe e não é segurado pelo escudo do inimigo
  const sagrado = s.sagrado && s.sagrado[1] > 0 ? sortear(s.sagrado[0], s.sagrado[1]) : 0;
  ini.vida -= dano + sagrado;
  ini.flash = 0.12;
  ini.estado = 'perseguindo';
  if (s.atordoa) { ini.atordoado = Math.max(ini.atordoado || 0, s.atordoa); ini.preparo = 0; } // empurrão de escudo, golpe no elmo...
  else if (critico && s.atordoaCritico) { ini.atordoado = Math.max(ini.atordoado || 0, s.atordoaCritico * (ini.tipo.flagAoMorrer ? 0.35 : 1)); ini.preparo = 0; }
  // Golpe pesado: o inimigo cambaleia (perde o ataque que preparava e para de recuar)
  else if (dano >= ini.tipo.vida * CAMBALEIO_FRACAO && !(ini.atordoado > 0)) {
    ini.atordoado = CAMBALEIO_TEMPO; ini.preparo = 0; ini.recuo = 0;
  }
  numeros.push({ x: ini.x, y: ini.y, altura: ini.tipo.altura, texto: critico ? `${dano}!` : String(dano),
                 cor: critico ? '#ffb347' : '#fff3c4', tempo: critico ? 1.2 : 0.9, grande: critico });
  if (sagrado) numeros.push({ x: ini.x + 0.3, y: ini.y - 0.3, altura: ini.tipo.altura + 0.3, texto: `+${sagrado}`, cor: COR_SAGRADO, tempo: 1 });
  efeitoDeAcerto(ini, critico, sagrado, !!((ataque && ataque.especial) || jogador.giro));
  if (ini.vida <= 0) matarInimigo(ini);
}

// A maestria saiu (agora são as árvores de habilidade por arma, js/habilidades.js)
function ganharMaestria() {}

function matarInimigo(ini) {
  ini.morto = true;
  ini.vida = 0;
  if (alvoInimigo === ini) alvoInimigo = null;
  ganharDevocaoPorVitoria(ini);
  ganharExperiencia(experienciaDoInimigo(ini));
  if (ini.tipo.flagAoMorrer) flags[ini.tipo.flagAoMorrer] = true; // avança missões
  // Rede de segurança: mapa limpo, missão cumprida (se o alvo dela estava aqui)
  if (!inimigosVivos().length) for (const o of inimigos) if (o.tipo.flagAoMorrer) flags[o.tipo.flagAoMorrer] = true;
  if (Math.random() < ini.tipo.chanceItem) {
    // Só cai o que esse tipo de inimigo poderia carregar (loot em js/inimigos.js)
    largarItem(gerarItemAleatorio(ini.tipo.raridadeMinima, ini.tipo.loot), ini.x, ini.y);
  }
  const r = ini.tipo.remedios;
  if (r && Math.random() < r.chance) largarItem(sortearRemedio(r.tipos), ini.x, ini.y);
  largarOuro(ini);
  largarGema(ini);
}

function ferirJogador(dano, origem) {
  // O escudo segura parte do golpe quando o jogador não está atacando
  // A armadura reduz todo golpe; o escudo segura parte dele quando não se está atacando
  dano = dano * (1 - reducaoPorDefesa());
  // (com a Muralha ou o pavês, bloqueia mesmo atacando)
  if (!ataque || bonus.bloqueioTotal || bonus.bloqueioSemEscudo) dano = dano * (1 - bloqueioTotal());
  dano = Math.max(1, Math.round(dano));
  jogador.vida -= dano;
  jogador.feridoFlash = 0.25;
  interromperOracao('A oração foi interrompida.');
  numeros.push({ x: jogador.x, y: jogador.y, altura: jogador.altura, texto: String(dano), cor: '#ff7a6b', tempo: 0.9 });
  desgasteAoApanhar();                  // a armadura (e o escudo) sentem o golpe
  if (jogador.vida <= 0) morrerJogador();
}

// Ao cair, o jogador é levado de volta a Ascalão e cuidado pelos seus
function morrerJogador() {
  jogador.vida = 0;
  ataque = null; alvoInimigo = null; destino = null;
  const atoAqui = typeof atoDoMapa === 'function' ? atoDoMapa(nomeDoMapaAtual()) : 1;
  const ato2 = atoAqui === 2, ato3 = atoAqui === 3;
  avisar(ato3 ? 'Você caiu. Os seus o levaram ao acampamento do rei.'
    : ato2 ? 'Você caiu. Os seus o levaram para Ibelin.' : 'Você caiu. Os seus o levaram de volta a Ascalão.');
  perderOuroAoCair();
  iniciarTransicao(ato3 ? { destino: 'campoReal', chegada: { x: 20, y: 18.5 }, renascer: true }
                 : ato2 ? { destino: 'ibelin', chegada: { x: 19, y: 26 }, renascer: true }
                        : { destino: 'ascalao', chegada: { x: 23, y: 77 }, renascer: true });
}

// A vida volta bem devagar (mais com a Esperança e com bônus de regeneração);
// a devoção volta devagar também, mais com a Fé (atributo) e com a Caridade
function atualizarRecuperacao(dt) {
  if (jogador.vida > 0) jogador.vida = Math.min(jogador.vidaMax, jogador.vida + (0.6 + (bonus.regenVida || 0)) * dt);
  if (jogador.vida > 0) jogador.devocao = Math.min(jogador.devocaoMax, jogador.devocao + (bonus.regenDevocao || 0) * dt);
  jogador.feridoFlash = Math.max(0, (jogador.feridoFlash || 0) - dt);
  for (const n of numeros) n.tempo -= dt;
  numeros = numeros.filter((n) => n.tempo > 0);
  for (const m of mensagens) m.tempo -= dt;
  mensagens = mensagens.filter((m) => m.tempo > 0);
}

// Ao entrar num mapa: inimigos novos, nada voando
function aoEntrarNoMapa() {
  criarInimigosDoMapa(nomeDoMapaAtual());
  // baixa o cenário deste mapa e dos vizinhos (para a próxima passagem não esperar)
  preCarregarCenario(nomeDoMapaAtual());
  for (const p of Object.values(mapaAtual.portais || {})) preCarregarCenario(p.destino);
  if (nomeDoMapaAtual() === 'dunas') flags.foiAsDunas = true;
  if (nomeDoMapaAtual() === 'cisternas') flags.desceuCisternas = true;
  if (nomeDoMapaAtual() === 'acampamento') flags.entrouAcampamento = true;
  if (nomeDoMapaAtual() === 'torre') flags.foiATorre = true;
  const m = nomeDoMapaAtual();
  if (m === 'ibelin') { flags.foiAIbelin = true; renovarEstoque(); }
  if (m === 'ramla') flags.foiARamla = true;
  if (m === 'lida') flags.foiALida = true;
  if (m === 'poroes') flags.desceuPoroes = true;
  if (m === 'caverna') flags.foiACaverna = true;
  if (m === 'campoReal') { flags.foiAoCampoReal = true; renovarEstoque(); }
  if (m === 'colinas') flags.foiAsColinas = true;
  if (m === 'ravina') flags.foiARavina = true;
  if (m === 'campo') flags.foiAoCampo = true;
  if (nomeDoMapaAtual() === 'ascalao') renovarEstoque();   // o Bulos recebe mercadoria nova
  projeteis = []; ataque = null; alvoInimigo = null;
  trazerCompanheiro();   // o companheiro chega junto
}

// --- Desenho dos efeitos (dentro do zoom) ---

// O arco do golpe, desenhado no chão enquanto o ataque acontece
function desenharGolpe() {
  desenharEfeitosDeHabilidade();
  if (typeof desenharAuraNoChao === 'function') desenharAuraNoChao();
  if (!ataque || ataque.stats.projetil) return;
  const s = ataque.stats;
  const r = s.alcance / METROS_POR_TILE + jogador.raio;
  const meio = (s.arco / 2) * Math.PI / 180;
  const progresso = ataque.t / ataque.total;
  const alpha = progresso < MOMENTO_IMPACTO ? 0.15 : 0.35 * (1 - progresso);
  ctx.beginPath();
  const centro = mundoParaTela(jogador.x, jogador.y);
  ctx.moveTo(centro.x + camera.x, centro.y + camera.y);
  for (let i = 0; i <= 16; i++) {
    const a = ataque.angulo - meio + (2 * meio * i) / 16;
    const p = mundoParaTela(jogador.x + Math.cos(a) * r, jogador.y + Math.sin(a) * r);
    ctx.lineTo(p.x + camera.x, p.y + camera.y);
  }
  ctx.closePath();
  // Golpe especial em dourado; golpe comum em branco
  ctx.fillStyle = ataque.especial ? `rgba(240, 190, 60, ${alpha * 1.5})` : `rgba(255, 235, 190, ${alpha})`;
  ctx.fill();
}

function desenharProjeteis() {
  for (const p of projeteis) {
    const a = mundoParaTela(p.x, p.y);
    const b = mundoParaTela(p.x - p.dx * 0.4, p.y - p.dy * 0.4);
    const h = altPx(1.3); // virote voa na altura do peito
    ctx.beginPath();
    ctx.moveTo(a.x + camera.x, a.y + camera.y - h);
    ctx.lineTo(b.x + camera.x, b.y + camera.y - h);
    ctx.strokeStyle = p.inimigo ? '#d8c9a4' : '#3b2a1a';
    ctx.lineWidth = 2;
    ctx.stroke();
    ctx.lineWidth = 1;
  }
}

// --- Desenho sem zoom: números, mensagens e barras ---

function desenharNumeros() {
  ctx.font = 'bold 15px monospace';
  ctx.textAlign = 'center';
  for (const n of numeros) {
    ctx.font = n.grande ? 'bold 20px monospace' : 'bold 15px monospace';
    const p = mundoParaTela(n.x, n.y);
    const subida = (1 - n.tempo) * 30;
    const x = (p.x + camera.x) * zoom;
    const y = (p.y + camera.y - altPx(n.altura)) * zoom - 18 - subida;
    ctx.fillStyle = 'rgba(0,0,0,0.7)';
    ctx.fillText(n.texto, x + 1, y + 1);
    ctx.fillStyle = n.cor;
    ctx.fillText(n.texto, x, y);
  }
  ctx.textAlign = 'left';
}

function desenharMensagens() {
  ctx.font = 'bold 18px Alegreya, Georgia, serif';
  ctx.textAlign = 'center';
  mensagens.slice(-3).forEach((m, i) => {
    ctx.globalAlpha = Math.min(1, m.tempo);
    // faixa escura atrás, para ler mesmo por cima de uma janela aberta
    const larg = ctx.measureText(m.texto).width + 28;
    ctx.fillStyle = 'rgba(14, 11, 8, 0.82)';
    ctx.fillRect(canvas.width / 2 - larg / 2, canvas.height * 0.28 + i * 26 - 19, larg, 25);
    ctx.fillStyle = 'rgba(0,0,0,0.75)';
    ctx.fillText(m.texto, canvas.width / 2 + 1, canvas.height * 0.28 + i * 26 + 1);
    ctx.fillStyle = '#f1e6c8';
    ctx.fillText(m.texto, canvas.width / 2, canvas.height * 0.28 + i * 26);
  });
  ctx.globalAlpha = 1;
  ctx.textAlign = 'left';
}

// Vida, experiência, devoção e arma ativa, no canto inferior esquerdo
function desenharBarras() {
  const x = 16, larg = 220;
  const y = canvas.height - 92;
  const barra = (yy, valor, max, cor, rotulo) => {
    ctx.fillStyle = 'rgba(0,0,0,0.65)';
    ctx.fillRect(x - 2, yy - 2, larg + 4, 18);
    ctx.fillStyle = cor;
    ctx.fillRect(x, yy, larg * Math.max(0, valor) / max, 14);
    ctx.font = '11px monospace';
    ctx.fillStyle = '#fff';
    ctx.fillText(`${rotulo} ${Math.ceil(valor)} / ${max}`, x + 6, yy + 11);
  };
  barra(y - 22, jogador.vida, jogador.vidaMax, '#a8322a', 'Vida');
  // Experiência: barra fina com o nível
  ctx.fillStyle = 'rgba(0,0,0,0.65)';
  ctx.fillRect(x - 2, y - 2, larg + 4, 18);
  ctx.fillStyle = '#5a4a8a';
  ctx.fillRect(x, y + 9, larg * fracaoDoNivel(), 5);
  ctx.font = '11px monospace';
  ctx.fillStyle = '#e6dcff';
  ctx.fillText(`Nível ${jogador.nivel}${jogador.nivel >= NIVEL_MAXIMO ? ' (máximo)' : ` · ${Math.floor(fracaoDoNivel() * 100)}%`}`, x + 6, y + 8);
  if (jogador.pontosAtributo || jogador.pontosHabilidade) {
    const piscar = Math.floor(performance.now() / 500) % 2 === 0;
    ctx.fillStyle = piscar ? '#ffe58a' : '#c9a25a';
    ctx.textAlign = 'right';
    ctx.fillText(`pontos: T`, x + larg - 4, y + 8);
    ctx.textAlign = 'left';
  }
  barra(y + 22, jogador.devocao, jogador.devocaoMax, '#8f9fc4', 'Devoção');
  ctx.font = 'bold 12px monospace';
  ctx.fillStyle = COR_OURO;
  ctx.fillText(`${jogador.ouro} de ouro`, x + larg + 12, y - 11);
  desenharAvisosDeDesgaste(x, y - 34);
  desenharVidaCompanheiro();
  ctx.font = '11px monospace';
  ctx.fillStyle = '#e9dcb4';
  const extras = [];
  if (jogador.bencao > 0) extras.push(`Bênção ${Math.ceil(jogador.bencao)} s`);
  if (jogador.rezando) extras.push('Rezando...');
  ['F', 'G', 'H'].forEach((t, k) => { const h = habilidadeDoAtalho(k); if (h) extras.push(`${t}: ${h.nome} (${h.custo})`); });
  const vir = virtudeAtiva();
  if (vir) extras.push(`Virtude: ${vir.nome}`);
  for (const p of jogador.posturas || []) extras.push(`${p.nome} ${Math.ceil(p.restante)} s`);
  ctx.fillText(extras.join(' · '), x + larg + 12, y + 33);

  const item = armaAtiva();
  if (item) {
    const b = BASES_ARMAS[item.base];
    const arv = arvoreDaArma(item);
    const m = arv && pontosNaArvore(arv) ? ` · ${pontosNaArvore(arv)} pts na árvore` : '';
    ctx.font = 'bold 13px Alegreya, Georgia, serif';
    ctx.fillStyle = RARIDADES[item.raridade].cor;
    ctx.fillText(item.nome, x, y + 58);
    const escudo = escudoAtivo();
    if (escudo) {
      const w = ctx.measureText(item.nome + '  ').width;
      ctx.fillStyle = corDoItem(escudo);
      ctx.fillText('+ ' + escudo.nome, x + w, y + 58);
    }
    ctx.font = '11px monospace';
    ctx.fillStyle = '#bbb';
    const reserva = jogador.armas[1 - jogador.armaAtiva];
    ctx.fillText(`${b.nome}${m}${reserva ? ' · Q troca para ' + reserva.nome : ''}`, x, y + 74);
  }

  // Tela avermelhada ao levar um golpe
  if (jogador.feridoFlash > 0) {
    ctx.fillStyle = `rgba(160, 20, 10, ${jogador.feridoFlash * 0.8})`;
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  }
}

;
// ===== js/companheiro.js =====
// =====================================================================
// COMPANHEIRO: um homem contratado que luta ao lado de Tomás
// =====================================================================
// Como os mercenários do Diablo 2: contratado com ouro, um por vez, segue o
// jogador de mapa em mapa e luta sozinho. Se cair, a Irmã Inês cuida dele
// (pago) e ele volta a servir.
//
// Cada ato tem os seus. No Ato I, o capitão da guarda de Ascalão cede um
// besteiro ou um sargento depois da missão "Saqueadores na estrada".

const TIPOS_COMPANHEIRO = {
  besteiro: {
    nome: 'Pedro, besteiro da guarda', ato: 1, preco: 150, visual: 'besteiro',
    vidaMax: 70, dano: [4, 8], vel: 2.3, altura: 1.75,
    distancia: [3, 6.5],             // atira de longe; recua se o inimigo chegar perto
    preparo: 0.6, recarga: 1.6,
    texto: 'Atira de longe com a besta. Frágil se cercado.'
  },
  sargento: {
    nome: 'Gil, sargento da guarda', ato: 1, preco: 150, visual: 'sargento',
    vidaMax: 115, dano: [5, 9], vel: 2.3, altura: 1.78,
    alcance: 2.2,                    // metros (lança)
    preparo: 0.45, recarga: 1.2, defesa: 0.3,   // o escudo segura 30% dos golpes
    texto: 'Lança e escudo. Segura os inimigos na linha de frente.'
  },
  // Ato II: em Ibelin
  guia: {
    nome: 'Yusuf, guia sírio', ato: 2, preco: 300, visual: 'guia',
    vidaMax: 120, dano: [7, 12], vel: 2.6, altura: 1.75,
    alcance: 2.2, preparo: 0.35, recarga: 1.0, defesa: 0.1,
    texto: 'Lança curta e pés ligeiros. Conhece cada trilha da planície.'
  },
  turcopolo: {
    nome: 'Sargis, turcópolo armênio', ato: 2, preco: 300, visual: 'turcopolo',
    vidaMax: 95, dano: [7, 12], vel: 2.4, altura: 1.75,
    distancia: [3, 7], preparo: 0.5, recarga: 1.3,
    texto: 'Arqueiro a serviço dos francos. Atira rápido e de longe.'
  }
};
const PRECO_TRATAR = 80;            // a Irmã Inês cuida do companheiro caído
const RAIO_COMP = 0.22;

let companheiro = null;   // { tipo, x, y, vida, morto, ... } ou null

function contratarCompanheiro(tipo) {
  const t = TIPOS_COMPANHEIRO[tipo];
  if (companheiro && companheiro.tipo === tipo) { avisar(`${t.nome} já está com você.`); return; }
  if (jogador.ouro < t.preco) { avisar(`Contratar custa ${t.preco} de ouro.`); return; }
  // Um companheiro por vez: quem estava com você volta para a guarda dele
  if (companheiro) avisar(`${TIPOS_COMPANHEIRO[companheiro.tipo].nome} voltou para os seus.`);
  jogador.ouro -= t.preco;
  companheiro = { tipo, x: jogador.x + 0.8, y: jogador.y + 0.4, vida: t.vidaMax, morto: false, preparo: 0, recarga: 0, angulo: 0,
                  mapa: nomeDoMapaAtual() };
  avisar(`${t.nome} agora luta ao seu lado.`);
}

function tratarCompanheiro() {
  if (!companheiro || !companheiro.morto) return;
  if (jogador.ouro < PRECO_TRATAR) { avisar(`Cuidar dele custa ${PRECO_TRATAR} de ouro.`); return; }
  jogador.ouro -= PRECO_TRATAR;
  companheiro.morto = false;
  companheiro.vida = TIPOS_COMPANHEIRO[companheiro.tipo].vidaMax;
  companheiro.x = jogador.x + 0.8; companheiro.y = jogador.y + 0.4; companheiro.mapa = nomeDoMapaAtual();
  avisar(`${TIPOS_COMPANHEIRO[companheiro.tipo].nome} está de pé de novo.`);
}

const companheiroAtivo = () => companheiro && !companheiro.morto;
const companheiroNoMapa = () => companheiro && companheiro.mapa === nomeDoMapaAtual();

// Ao trocar de mapa, ele chega junto
function trazerCompanheiro() {
  if (!companheiroAtivo()) return;
  companheiro.x = jogador.x + 0.6; companheiro.y = jogador.y + 0.6;
  companheiro.mapa = nomeDoMapaAtual();
  if (colide(companheiro.x, companheiro.y, RAIO_COMP)) { companheiro.x = jogador.x; companheiro.y = jogador.y; }
  companheiro.preparo = 0;
}

function ferirCompanheiro(dano) {
  const t = TIPOS_COMPANHEIRO[companheiro.tipo];
  dano = Math.max(1, Math.round(dano * (1 - (t.defesa || 0))));
  companheiro.vida -= dano;
  companheiro.flash = 0.15;
  numeros.push({ x: companheiro.x, y: companheiro.y, altura: t.altura, texto: String(dano), cor: '#f0a080', tempo: 0.8 });
  if (companheiro.vida <= 0) {
    companheiro.vida = 0; companheiro.morto = true; companheiro.tempoMorto = 0;
    avisar(`${t.nome} caiu! A Irmã Inês pode cuidar dele em Ascalão.`);
  }
}

// O inimigo vivo mais perto dele que valha atacar (perto também do jogador)
function alvoDoCompanheiro() {
  let melhor = null, melhorD = 7;
  for (const ini of inimigosVivos()) {
    const d = Math.hypot(ini.x - companheiro.x, ini.y - companheiro.y);
    const dj = Math.hypot(ini.x - jogador.x, ini.y - jogador.y);
    if (dj > 9) continue;
    const peso = ini.estado === 'perseguindo' ? d - 2 : d;   // prefere quem já está lutando
    if (peso < melhorD) { melhor = ini; melhorD = peso; }
  }
  return melhor;
}

function moverCompanheiro(alvoX, alvoY, vel, dt) {
  const ax = alvoX - companheiro.x, ay = alvoY - companheiro.y;
  const d = Math.hypot(ax, ay);
  if (d < 0.05) return false;
  const passo = Math.min(d, vel * dt);
  const livre = (x, y) => !colide(x, y, RAIO_COMP) && !colideComInimigo(x, y, RAIO_COMP);
  const nx = companheiro.x + ax / d * passo, ny = companheiro.y + ay / d * passo;
  if (livre(nx, companheiro.y)) companheiro.x = nx;
  if (livre(companheiro.x, ny)) companheiro.y = ny;
  companheiro.angulo = Math.atan2(ay, ax);
  return true;
}

function atualizarCompanheiro(dt) {
  if (!companheiroNoMapa()) return;
  if (companheiro.morto) { companheiro.tempoMorto += dt; return; }
  const t = TIPOS_COMPANHEIRO[companheiro.tipo];
  companheiro.flash = Math.max(0, (companheiro.flash || 0) - dt);
  companheiro.recarga = Math.max(0, companheiro.recarga - dt);
  companheiro.vida = Math.min(t.vidaMax, companheiro.vida + 0.8 * dt);   // se recupera devagar

  // Muito longe (o jogador correu ou viajou): alcança o jogador
  const dj = Math.hypot(jogador.x - companheiro.x, jogador.y - companheiro.y);
  if (dj > 12) { trazerCompanheiro(); return; }

  const alvo = companheiro.alvo && !companheiro.alvo.morto ? companheiro.alvo : alvoDoCompanheiro();
  companheiro.alvo = alvo;

  // Mirando ou preparando o golpe
  if (companheiro.preparo > 0) {
    companheiro.preparo -= dt;
    if (companheiro.preparo <= 0 && alvo) {
      if (t.distancia) {
        const a = Math.atan2(alvo.y - companheiro.y, alvo.x - companheiro.x) + (Math.random() - 0.5) * 0.08;
        projeteis.push({ x: companheiro.x, y: companheiro.y, dx: Math.cos(a), dy: Math.sin(a), restante: 10,
                         stats: { dano: t.dano }, doCompanheiro: true });
      } else {
        const alcance = t.alcance / METROS_POR_TILE + RAIO_COMP + alvo.tipo.raio + 0.15;
        if (Math.hypot(alvo.x - companheiro.x, alvo.y - companheiro.y) <= alcance) ferirInimigo(alvo, { dano: t.dano });
      }
      companheiro.recarga = t.recarga;
    }
    return;
  }
  companheiro.andando = false;

  if (alvo) {
    const d = Math.hypot(alvo.x - companheiro.x, alvo.y - companheiro.y);
    companheiro.angulo = Math.atan2(alvo.y - companheiro.y, alvo.x - companheiro.x);
    if (t.distancia) {
      const [perto, longe] = t.distancia;
      const enxerga = linhaDeTiroLivre(companheiro.x, companheiro.y, alvo.x, alvo.y);
      if (d < perto) companheiro.andando = moverCompanheiro(companheiro.x * 2 - alvo.x, companheiro.y * 2 - alvo.y, t.vel * 0.9, dt);
      else if (d > longe || !enxerga) companheiro.andando = moverCompanheiro(alvo.x, alvo.y, t.vel, dt);
      else if (companheiro.recarga <= 0) companheiro.preparo = t.preparo;
    } else {
      const alcance = t.alcance / METROS_POR_TILE + RAIO_COMP + alvo.tipo.raio;
      if (d > alcance) companheiro.andando = moverCompanheiro(alvo.x, alvo.y, t.vel, dt);
      else if (companheiro.recarga <= 0) companheiro.preparo = t.preparo;
    }
    return;
  }
  // Sem inimigos: acompanha o jogador, um pouco atrás
  if (dj > 2.2) {
    const a = jogador.angulo + Math.PI * 0.8;
    companheiro.andando = moverCompanheiro(jogador.x + Math.cos(a) * 1.3, jogador.y + Math.sin(a) * 1.3, Math.max(t.vel, jogador.velocidade * 1.05), dt);
  }
}

// --- Desenho -------------------------------------------------------------

function desenharCompanheiro(cx, cy) {
  const t = TIPOS_COMPANHEIRO[companheiro.tipo];
  const andando = estaAndando(companheiro);
  let nome = 'stance', fracao, tempo;
  if (companheiro.morto) { nome = 'die'; tempo = companheiro.tempoMorto; }
  else if (companheiro.preparo > 0) { nome = t.distancia ? 'shoot' : 'swing'; fracao = 1 - companheiro.preparo / t.preparo; }
  else if (andando) { nome = 'run'; fracao = faseDaCorrida(companheiro, t.altura); }
  const t2 = animar(companheiro, nome, performance.now());
  if (tempo === undefined) tempo = t2;
  if (companheiro.flash > 0) ctx.filter = 'brightness(1.8)';
  const ok = desenharAvatar(APARENCIAS[t.visual], companheiro.angulo, nome, tempo, fracao, cx, cy, t.altura);
  ctx.filter = 'none';
  if (!ok) desenharBlocoMetros(cx, cy, 0.6, t.altura, ['#6a8fb0', '#3f5a73', '#557590']);
}

// Barra de vida e nome, sem zoom (como no D2, o mercenário mostra a vida)
function desenharVidaCompanheiro() {
  if (!companheiro) return;
  ctx.textAlign = 'left';
  const t = TIPOS_COMPANHEIRO[companheiro.tipo];
  const x = 16, y = 86;
  ctx.fillStyle = 'rgba(0,0,0,0.6)'; ctx.fillRect(x - 2, y - 14, 154, 30);
  ctx.font = '11px Alegreya, Georgia, serif'; ctx.fillStyle = companheiro.morto ? '#e0574a' : '#d9cfbb';
  ctx.fillText(companheiro.morto ? `${t.nome} (caído)` : t.nome, x + 2, y - 2);
  ctx.fillStyle = '#3a1512'; ctx.fillRect(x + 2, y + 3, 146, 7);
  ctx.fillStyle = '#a8322a'; ctx.fillRect(x + 2, y + 3, 146 * companheiro.vida / t.vidaMax, 7);
}

;
// ===== js/itens.js =====
// =====================================================================
// ITENS: no chão, no alforje e no corpo do jogador
// =====================================================================
// Como no D2: itens caem com o nome na cor da raridade. Clique para pegar.
// Tecla I abre o equipamento; Q troca entre os dois conjuntos de armas.

const TAMANHO_ALFORJE = 40;   // 8 x 5 casas (js/itens.js, desenharPainel)
const itensNoChao = {};      // por mapa: { ascalao: [ {item, x, y}, ... ], ... }
let alvoItem = null;         // item no chão que o jogador clicou para pegar
let inventarioAberto = false;
let rotulosNoChao = [];      // retângulos dos nomes no chão (para o clique)
let areasPainel = [];        // retângulos clicáveis do painel
let menuItem = null;         // janela de opções de um item (equipar, largar, vender...)

function nomeDoMapaAtual() {
  return Object.keys(MAPAS).find((k) => MAPAS[k] === mapaAtual);
}

function itensDoMapa() {
  const nome = nomeDoMapaAtual();
  return itensNoChao[nome] || (itensNoChao[nome] = []);
}

function largarItem(item, x, y) {
  itensDoMapa().push({ item, x: x + (Math.random() - 0.5) * 0.6, y: y + (Math.random() - 0.5) * 0.6 });
  if (!item.tipo && ['raro', 'lendario', 'conjunto'].includes(item.raridade)) {
    avisar(`${RARIDADES[item.raridade].nome}: ${item.nome}`);
  }
}

// Cor do nome de um item: a da raridade, ou a cor dos remédios
function corDoItem(item) {
  if (item.tipo === 'ouro') return COR_OURO;
  if (item.tipo === 'gema') return GEMAS[item.gema].cor;
  return item.tipo === 'remedio' ? COR_REMEDIO : RARIDADES[item.raridade].cor;
}

// Pega um item do chão. Vai direto para o corpo se o lugar dele estiver vazio;
// senão, para o alforje.
function pegarItem(noChao) {
  alvoItem = null;
  const item = noChao.item;
  const i = jogador.armaAtiva;
  if (item.tipo === 'ouro') {
    pegarOuro(item);                                    // o ouro vai direto para a bolsa
  } else if (item.tipo === 'gema') {
    if (jogador.alforje.length >= TAMANHO_ALFORJE) { avisar('O alforje está cheio.'); return; }
    jogador.alforje.push(item);                         // gemas vão para o alforje
  } else if (item.tipo === 'remedio') {
    if (!guardarRemedio(item)) return;                 // remédios vão para o cinto
  } else {
    const cat = categoriaDe(item);
    const armaAtual = jogador.armas[i];
    if (cat === 'arma' && !jogador.armas[1]) jogador.armas[1] = item;
    else if (cat === 'escudo' && !jogador.escudos[i] && armaAtual && BASES_ARMAS[armaAtual.base].maos === 1) jogador.escudos[i] = item;
    else if (cat === 'anel' && !jogador.equipamento.anel1) jogador.equipamento.anel1 = item;
    else if (cat === 'anel' && !jogador.equipamento.anel2) jogador.equipamento.anel2 = item;
    else if (cat !== 'arma' && cat !== 'escudo' && cat !== 'anel' && !jogador.equipamento[cat]) jogador.equipamento[cat] = item;
    else if (jogador.alforje.length < TAMANHO_ALFORJE) jogador.alforje.push(item);
    else { avisar('O alforje está cheio.'); return; }
    recalcularAtributos();
  }
  const lista = itensDoMapa();
  lista.splice(lista.indexOf(noChao), 1);
}

function atualizarItens() {
  if (alvoItem && Math.hypot(alvoItem.x - jogador.x, alvoItem.y - jogador.y) < 0.9) pegarItem(alvoItem);
  // O ouro é pego só de passar por cima
  const ouro = itensDoMapa().find((c) => c.item.tipo === 'ouro' && Math.hypot(c.x - jogador.x, c.y - jogador.y) < 0.6);
  if (ouro) pegarItem(ouro);
}

function trocarArma() {
  if (!jogador.armas[1 - jogador.armaAtiva] || ataque) return;
  jogador.armaAtiva = 1 - jogador.armaAtiva;
  recalcularAtributos(); // o bônus de conjunto pode mudar com a troca
}

window.addEventListener('keydown', (e) => {
  if (dialogo || menuOratorio || diarioAberto) return;
  const t = e.key.toLowerCase();
  if (t === 'q') trocarArma();
  if (t === 'i') { inventarioAberto = !inventarioAberto; menuItem = null; }
  if (e.key === 'Escape') menuItem = null;
});

// Item no chão sob o cursor (pelo nome escrito)
function itemNoChaoSobOMouse() {
  const r = rotulosNoChao.find((r) => mouse.x > r.x && mouse.x < r.x + r.w && mouse.y > r.y && mouse.y < r.y + r.h);
  return r ? r.noChao : null;
}

const mouseEm = (r) => mouse.x > r.x && mouse.x < r.x + r.w && mouse.y > r.y && mouse.y < r.y + r.h;

// Clique dentro do painel de equipamento. Devolve true se o clique foi nele.
function cliqueNoPainel(botao) {
  if (!inventarioAberto) return false;
  // Janela do item aberta: o clique escolhe uma opção ou fecha a janela
  if (menuItem) { cliqueNoMenuItem(botao); return true; }
  if (!mouseEm(retanguloPainel())) return false;
  const area = areasPainel.find(mouseEm);
  // Com uma gema escolhida, o próximo clique num item é para encaixá-la
  if (gemaSelecionada) {
    if (botao === 0 && area && area.item && area.item !== gemaSelecionada && !area.item.tipo) encaixarGema(gemaSelecionada, area.item);
    gemaSelecionada = null;
    return true;
  }
  if (area && area.acao) area.acao(botao);
  return true;
}

// --- Desenho no chão ---

function desenharItensNoChao() {
  for (const c of itensDoMapa()) {
    const p = mundoParaTela(c.x, c.y);
    desenharLosango(p.x + camera.x, p.y + camera.y, 9, 4.5, corDoItem(c.item), 'rgba(0,0,0,0.6)');
  }
}

// Nomes dos itens no chão, como no D2 (sem zoom).
// Para a tela não ficar poluída: o nome só aparece perto de Tomás (3,5 tiles),
// com o mouse em cima do item ou segurando Alt. Lendários e peças de conjunto
// ficam sempre com o nome à mostra.
let teclaAlt = false;
window.addEventListener('keydown', (e) => { if (e.key === 'Alt') { teclaAlt = true; e.preventDefault(); } });
window.addEventListener('keyup', (e) => { if (e.key === 'Alt') teclaAlt = false; });
window.addEventListener('blur', () => { teclaAlt = false; });
const NOME_SEMPRE_A_MOSTRA = new Set(['lendario', 'conjunto']);
function desenharNomesNoChao() {
  rotulosNoChao = [];
  ctx.font = 'bold 12px Alegreya, Georgia, serif';
  for (const c of itensDoMapa()) {
    if (!explorado(c.x, c.y)) continue;
    const p = mundoParaTela(c.x, c.y);
    const cx = (p.x + camera.x) * zoom, cy = (p.y + camera.y) * zoom;
    const perto = Math.hypot(c.x - jogador.x, c.y - jogador.y) < 3.5;
    const sobreOItem = mouse.x > cx - 14 && mouse.x < cx + 14 && mouse.y > cy - 12 && mouse.y < cy + 10;
    const mostra = NOME_SEMPRE_A_MOSTRA.has(c.item.raridade) || perto || teclaAlt || sobreOItem || alvoItem === c;
    if (!mostra) {   // sem nome: o próprio losango continua clicável
      rotulosNoChao.push({ x: cx - 14, y: cy - 12, w: 28, h: 22, noChao: c });
      continue;
    }
    const larg = ctx.measureText(c.item.nome).width + 10;
    const x = cx - larg / 2;
    const y = cy - 26;
    const sob = alvoItem === c || sobreOItem || (mouse.x > x && mouse.x < x + larg && mouse.y > y && mouse.y < y + 17);
    ctx.fillStyle = sob ? 'rgba(40, 34, 26, 0.95)' : 'rgba(0, 0, 0, 0.7)';
    ctx.fillRect(x, y, larg, 17);
    ctx.fillStyle = corDoItem(c.item);
    ctx.fillText(c.item.nome, x + 5, y + 13);
    rotulosNoChao.push({ x, y, w: larg, h: 17, noChao: c });
    rotulosNoChao.push({ x: cx - 14, y: cy - 12, w: 28, h: 22, noChao: c });
  }
}

// --- Painel de equipamento (tecla I) ---

// Como no Diablo 2: à esquerda o "boneco" com um quadro para cada peça;
// à direita o alforje em grade (por enquanto, um item por quadro).
const ALFORJE_COLUNAS = 8, ALFORJE_LINHAS = 5;

function retanguloPainel() {
  // no celular, a tela toda; no computador, acima do painel de baixo (js/hud.js)
  if (MODO.toque) { const w = Math.min(760, canvas.width - 16), h = canvas.height - 16; return { x: (canvas.width - w) / 2, y: 8, w, h }; }
  const hud = alturaHud();
  const w = Math.min(760, canvas.width - 24), h = Math.min(560, canvas.height - 72 - hud);
  return { x: canvas.width - w - 12, y: Math.max(56, (canvas.height - hud - h) / 2), w, h };
}

// Um quadro do painel (espaço do corpo ou casa do alforje)
function desenharQuadro(x, y, w, h, item, rotulo) {
  const sob = mouseEm({ x, y, w, h });
  ctx.fillStyle = sob ? 'rgb(46, 39, 30)' : 'rgb(30, 26, 21)';
  ctx.fillRect(x, y, w, h);
  // borda na cor da raridade; casa vazia em cinza
  ctx.strokeStyle = item ? corDoItem(item) : '#4a4236';
  ctx.globalAlpha = item ? 0.9 : 1;
  ctx.lineWidth = item && item.raridade && item.raridade !== 'comum' ? 2 : 1;
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
  ctx.globalAlpha = 1; ctx.lineWidth = 1;
  if (item && item === gemaSelecionada) { ctx.strokeStyle = '#e8b931'; ctx.lineWidth = 2; ctx.strokeRect(x + 2, y + 2, w - 4, h - 4); ctx.lineWidth = 1; }
  else if (gemaSelecionada && item && !item.tipo && engastesLivres(item) > 0) { ctx.fillStyle = 'rgba(80, 190, 100, 0.18)'; ctx.fillRect(x, y, w, h); }
  if (item) {
    if (item.raridade && item.raridade !== 'comum') {   // um brilho de fundo na cor da raridade
      const g = ctx.createRadialGradient(x + w / 2, y + h / 2, 2, x + w / 2, y + h / 2, Math.max(w, h) * 0.6);
      g.addColorStop(0, corDoItem(item) + '33'); g.addColorStop(1, corDoItem(item) + '00');
      ctx.fillStyle = g; ctx.fillRect(x, y, w, h);
    }
    desenharIcone(item, x + w / 2, y + h / 2, Math.min(w, h) * 0.8);
    if (gasto(item) || quebrado(item)) { ctx.fillStyle = quebrado(item) ? 'rgba(200, 50, 40, 0.35)' : 'rgba(200, 150, 40, 0.25)'; ctx.fillRect(x + 1, y + h - 5, w - 2, 4); }
  } else if (rotulo) {
    ctx.font = `${Math.max(9, Math.round(w / 6))}px Alegreya SC, Georgia, serif`;
    ctx.fillStyle = '#5e5547';
    ctx.textAlign = 'center';
    ctx.fillText(rotulo, x + w / 2, y + h / 2 + 4);
    ctx.textAlign = 'left';
  }
}

function desenharPainel() {
  areasPainel = [];
  if (!inventarioAberto) return;
  const p = retanguloPainel();
  ctx.fillStyle = 'rgb(20, 17, 14)';
  ctx.fillRect(p.x, p.y, p.w, p.h);
  ctx.strokeStyle = '#8c7a55';
  ctx.lineWidth = 2;
  ctx.strokeRect(p.x + 1, p.y + 1, p.w - 2, p.h - 2);
  ctx.lineWidth = 1;
  // fechar (no celular é o único jeito; no computador, I ou Esc também fecham)
  const fechar = { x: p.x + p.w - 36, y: p.y + 6, w: 30, h: 30 };
  areasPainel.push({ ...fechar, acao: (b) => { if (b === 0) { inventarioAberto = false; menuItem = null; } } });
  ctx.font = 'bold 18px monospace'; ctx.fillStyle = mouseEm(fechar) ? '#ffe9a8' : '#8f846c';
  ctx.fillText('×', fechar.x + 9, fechar.y + 21);
  const titulo = (texto, x, y) => {
    ctx.font = 'bold 15px Alegreya, Georgia, serif';
    ctx.fillStyle = '#e8b931';
    ctx.fillText(texto, x, y);
  };
  // tamanho das casas: cabe o boneco (3 colunas) e o alforje (8 colunas) lado a lado
  const S = Math.max(30, Math.min(58, Math.floor((p.w - 56) / (3.4 + ALFORJE_COLUNAS * 0.86)), Math.floor((p.h - 120) / 6.2)));
  // as casas do alforje usam o espaço que sobra à direita (no celular, ficam maiores que o boneco)
  const sobraL = p.w - (3 * S + 2 * Math.round(S * 0.14)) - 64;
  const C = Math.max(28, Math.min(64, Math.floor(sobraL / ALFORJE_COLUNAS) - 3, Math.floor((p.h - 96) / ALFORJE_LINHAS) - 3));
  const gap = Math.round(S * 0.14);
  const larguraBoneco = 3 * S + 2 * gap;
  const xEsq = p.x + 16, xDir = p.x + 32 + larguraBoneco;
  const quadro = (x, y, w, h, item, rotulo, acao) => {
    areasPainel.push({ x, y, w, h, item, acao });
    desenharQuadro(x, y, w, h, item, rotulo);
  };
  const noCorpo = (item, onde, id) => (b) => item && b === 0 && abrirMenuItem(item, { corpo: true, onde, id });
  const eq = jogador.equipamento, i = jogador.armaAtiva;
  const arma = jogador.armas[i], escudo = jogador.escudos[i];
  const duasMaos = arma && BASES_ARMAS[arma.base].maos === 2;

  // --- O boneco
  titulo('Equipamento', xEsq, p.y + 26);
  const c0 = xEsq, c1 = xEsq + S + gap, c2 = xEsq + 2 * (S + gap);
  let y = p.y + 38;
  quadro(c1, y, S, S, eq.elmo, 'elmo', noCorpo(eq.elmo, 'corpo', 'elmo'));
  quadro(c2 + S * 0.2, y + S * 0.2, S * 0.6, S * 0.6, eq.colar, 'colar', noCorpo(eq.colar, 'corpo', 'colar'));
  y += S + gap;
  const alto = Math.round(S * 1.6);
  quadro(c0, y, S, alto, arma, 'arma', noCorpo(arma, 'arma'));
  quadro(c1, y, S, alto, eq.armadura, 'armadura', noCorpo(eq.armadura, 'corpo', 'armadura'));
  quadro(c2, y, S, alto, escudo, duasMaos ? '2 mãos' : 'escudo', noCorpo(escudo, 'escudo'));
  y += alto + gap;
  quadro(c0 + S * 0.2, y + S * 0.1, S * 0.6, S * 0.6, eq.anel1, 'anel', noCorpo(eq.anel1, 'corpo', 'anel1'));
  quadro(c1, y + S * 0.15, S, S * 0.6, eq.cinto, 'cinto', noCorpo(eq.cinto, 'corpo', 'cinto'));
  quadro(c2 + S * 0.2, y + S * 0.1, S * 0.6, S * 0.6, eq.anel2, 'anel', noCorpo(eq.anel2, 'corpo', 'anel2'));
  y += S * 0.85 + gap;
  quadro(c0, y, S, S, eq.luvas, 'luvas', noCorpo(eq.luvas, 'corpo', 'luvas'));
  quadro(c2, y, S, S, eq.botas, 'botas', noCorpo(eq.botas, 'corpo', 'botas'));
  // reserva (tecla Q), pequena, entre luvas e botas
  const rA = jogador.armas[1 - i], rE = jogador.escudos[1 - i];
  const m = S * 0.46;
  quadro(c1, y + S * 0.27, m, m, rA, 'Q', (b) => rA && b === 0 && abrirMenuItem(rA, { reserva: true, onde: 'arma' }));
  quadro(c1 + S - m, y + S * 0.27, m, m, rE, '', (b) => rE && b === 0 && abrirMenuItem(rE, { reserva: true, onde: 'escudo' }));
  ctx.font = '10px monospace'; ctx.fillStyle = '#8f846c';
  ctx.textAlign = 'center'; ctx.fillText('reserva', c1 + S / 2, y + S * 0.27 + m + 11); ctx.textAlign = 'left';
  y += S + gap + 6;

  // --- Atributos, embaixo do boneco
  ctx.font = '12px Alegreya, Georgia, serif';
  ctx.fillStyle = '#d9cfbb';
  const conj = Object.entries(CONJUNTOS).map(([id, c]) => [c.nome, pecasDoConjuntoEquipadas(id), c.pecas.length])
    .filter(([, n]) => n > 0).map(([nome, n, t]) => `${nome}: ${n}/${t}`);
  const atrib = [
    `Ouro ${jogador.ouro} · Nível ${jogador.nivel}`,
    `Vida ${Math.ceil(jogador.vida)}/${jogador.vidaMax} · Devoção ${jogador.devocaoMax}`,
    `Defesa ${defesaTotal()} (−${Math.round(reducaoPorDefesa() * 100)}% de dano)`,
    `Escudo ${Math.round(bloqueioTotal() * 100)}% · Cinto ${maximoPorRemedio()} de cada`,
    ...conj
  ];
  for (const a of atrib) { if (y > p.y + p.h - 10) break; ctx.fillText(a, xEsq, y + 10, larguraBoneco + 8); y += 16; }

  // --- O alforje em grade
  titulo(`Alforje ${jogador.alforje.length}/${TAMANHO_ALFORJE}`, xDir, p.y + 26);
  const y0 = p.y + 38;
  for (let k = 0; k < TAMANHO_ALFORJE; k++) {
    const cx = xDir + (k % ALFORJE_COLUNAS) * (C + 3), cy = y0 + Math.floor(k / ALFORJE_COLUNAS) * (C + 3);
    const item = jogador.alforje[k];
    quadro(cx, cy, C, C, item, '', (b) => {
      if (!item) return;
      if (b === 0) abrirMenuItem(item, { alforje: true });                         // janela de opções
      if (b === 2) { jogador.alforje.splice(k, 1); largarItem(item, jogador.x, jogador.y); }  // atalho: larga
    });
  }
  const yInfo = y0 + ALFORJE_LINHAS * (C + 3) + 18;
  ctx.font = '11px monospace';
  ctx.fillStyle = '#8f846c';
  if (gemaSelecionada) {
    ctx.fillStyle = '#e8b931';
    ctx.fillText(`Clique no item onde encaixar ${gemaSelecionada.nome} · Esc cancela`, xDir, yInfo);
    ctx.fillStyle = '#8f846c';
  } else {
    ctx.fillText(MODO.toque ? 'Toque num item para ver as opções' : 'Clique: opções · botão direito: larga', xDir, yInfo);
  }
  const merc = mercadorPerto();
  ctx.fillText(merc ? `Perto de ${merc.nome.split(',')[0]}: dá para vender` : 'Vender: perto de um mercador', xDir, yInfo + 16);
}

// --- Ícones dos itens, desenhados (sem imagens) ---------------------------
const COR_ACO = '#c9ccd1', COR_ACO_ESC = '#7c8088', COR_MADEIRA = '#8a5a32', COR_COURO = '#7a4e2c', COR_OURO_IC = '#d8b04a';
function desenharIcone(item, cx, cy, s) {
  ctx.save();
  ctx.translate(cx, cy);
  const u = s / 40;                       // o desenho é feito numa caixa de 40 x 40
  ctx.scale(u, u);
  ctx.lineCap = 'round'; ctx.lineJoin = 'round';
  const linha = (cor, larg, ...pts) => { ctx.strokeStyle = cor; ctx.lineWidth = larg; ctx.beginPath(); pts.forEach(([x, y], k) => k ? ctx.lineTo(x, y) : ctx.moveTo(x, y)); ctx.stroke(); };
  const forma = (cor, ...pts) => { ctx.fillStyle = cor; ctx.beginPath(); pts.forEach(([x, y], k) => k ? ctx.lineTo(x, y) : ctx.moveTo(x, y)); ctx.closePath(); ctx.fill(); };
  const contorno = () => { ctx.strokeStyle = 'rgba(0,0,0,0.6)'; ctx.lineWidth = 1.2; ctx.stroke(); };
  if (item.tipo === 'gema') {
    const cor = GEMAS[item.gema].cor;
    forma(cor, [0, -10], [9, -2], [0, 11], [-9, -2]); contorno();
    forma('rgba(255,255,255,0.45)', [0, -10], [4, -3], [0, -1], [-4, -3]);
  } else if (item.tipo === 'remedio') {
    if (item.remedio === 'bandagem') { forma('#e8e0cc', [-9, -6], [9, -6], [9, 6], [-9, 6]); contorno(); linha('#b8ab90', 1.5, [-9, 0], [9, 0]); }
    else { forma(item.remedio === 'teriaga' ? '#6a3a6a' : item.remedio === 'oximel' ? '#b8862a' : '#7a6a4a', [-6, -4], [6, -4], [8, 6], [6, 12], [-6, 12], [-8, 6]); contorno(); forma('#8a6a40', [-3, -10], [3, -10], [3, -4], [-3, -4]); }
  } else {
    const base = item.base;
    const cat = categoriaDe(item);
    if (cat === 'arma') {
      if (base === 'espada' || base === 'faca') {
        const L = base === 'faca' ? 10 : 15;
        linha(COR_ACO, 4, [-L * 0.8, L * 0.8], [L, -L]); linha('#fff', 1, [-L * 0.6, L * 0.6], [L, -L]);
        linha(COR_OURO_IC, 3, [-L * 0.9 + 4, L * 0.9 + 4 - 8], [-L * 0.9 - 4 + 8, L * 0.9 + 4]);
        linha(COR_COURO, 3.5, [-L * 0.85, L * 0.85], [-L * 1.2, L * 1.2]);
      } else if (base === 'acha' || base === 'machado') {
        const L = base === 'machado' ? 17 : 13;
        linha(COR_MADEIRA, 3.5, [-L, L], [L * 0.6, -L * 0.6]);
        forma(COR_ACO, [L * 0.3, -L * 0.9], [L * 1.0, -L * 0.2], [L * 0.7, -L * 0.1], [L * 0.6, -L * 0.6], [L * 0.2, -L * 0.6]); contorno();
      } else if (base === 'maca') {
        linha(COR_MADEIRA, 3.5, [-13, 13], [6, -6]);
        ctx.fillStyle = COR_ACO_ESC; ctx.beginPath(); ctx.arc(8, -8, 6, 0, Math.PI * 2); ctx.fill(); contorno();
        for (let k = 0; k < 6; k++) { const a = k * Math.PI / 3; linha(COR_ACO, 2, [8, -8], [8 + Math.cos(a) * 8, -8 + Math.sin(a) * 8]); }
      } else if (base === 'martelo') {
        linha(COR_MADEIRA, 3.5, [-13, 13], [7, -7]);
        forma(COR_ACO_ESC, [2, -16], [16, -2], [11, 3], [-3, -11]); contorno();
        forma(COR_ACO, [10, -14], [15, -9], [13, -7], [8, -12]);
      } else if (base === 'arco') {
        ctx.strokeStyle = '#6a4424'; ctx.lineWidth = 3.5; ctx.beginPath(); ctx.arc(-6, 6, 18, -1.45, 0.05); ctx.stroke();
        ctx.strokeStyle = '#d8c79c'; ctx.lineWidth = 2; ctx.beginPath(); ctx.arc(-6, 6, 18, -1.45, -1.25); ctx.stroke(); ctx.beginPath(); ctx.arc(-6, 6, 18, -0.15, 0.05); ctx.stroke();
        linha('#eee', 0.9, [-6 + Math.cos(-1.45) * 18, 6 + Math.sin(-1.45) * 18], [-6 + Math.cos(0.05) * 18, 6 + Math.sin(0.05) * 18]);
      } else if (base === 'lanca') {
        linha(COR_MADEIRA, 3, [-17, 17], [11, -11]);
        forma(COR_ACO, [17, -17], [13, -8], [10, -10], [8, -13]); contorno();
      } else if (base === 'besta' || base === 'bestaMao') {
        const k = base === 'bestaMao' ? 0.75 : 1;
        linha(COR_MADEIRA, 4.5, [-14 * k, 12 * k], [10 * k, -8 * k]);
        ctx.strokeStyle = '#5a3a20'; ctx.lineWidth = 2.5; ctx.beginPath(); ctx.arc(4 * k, -2 * k, 13 * k, -2.2, -0.2); ctx.stroke();
        linha('#ddd', 0.8, [4 * k + Math.cos(-2.2) * 13 * k, -2 * k + Math.sin(-2.2) * 13 * k], [4 * k + Math.cos(-0.2) * 13 * k, -2 * k + Math.sin(-0.2) * 13 * k]);
      } else if (base === 'punhos') {
        ctx.fillStyle = '#c9a07a'; ctx.beginPath(); ctx.arc(0, 0, 8, 0, Math.PI * 2); ctx.fill(); contorno();
      }
    } else if (cat === 'escudo') {
      if (base === 'escudoRedondo') { ctx.fillStyle = '#7a5530'; ctx.beginPath(); ctx.arc(0, 0, 16, 0, Math.PI * 2); ctx.fill(); contorno(); ctx.strokeStyle = '#4a3018'; ctx.lineWidth = 2; ctx.beginPath(); ctx.arc(0, 0, 11, 0, Math.PI * 2); ctx.stroke(); ctx.fillStyle = COR_ACO; ctx.beginPath(); ctx.arc(0, 0, 5, 0, Math.PI * 2); ctx.fill(); }
      else if (base === 'broquel') { ctx.fillStyle = COR_ACO_ESC; ctx.beginPath(); ctx.arc(0, 0, 13, 0, Math.PI * 2); ctx.fill(); contorno(); ctx.fillStyle = COR_ACO; ctx.beginPath(); ctx.arc(0, 0, 5, 0, Math.PI * 2); ctx.fill(); }
      else {
        const fundo = base === 'escudoCruz' ? '#c9a03a' : '#7a3a2a';
        forma(fundo, [-12, -16], [12, -16], [12, -2], [0, 18], [-12, -2]); contorno();
        if (base === 'escudoCruz') { linha('#9a1a14', 4, [0, -15], [0, 14]); linha('#9a1a14', 4, [-11, -6], [11, -6]); }
        else linha(COR_OURO_IC, 2, [0, -15], [0, 14]);
      }
    } else if (cat === 'elmo') {
      if (base === 'capuz') { forma(COR_COURO, [-12, 14], [-12, -2], [-6, -13], [6, -13], [12, -2], [12, 14], [6, 14], [6, 0], [-6, 0], [-6, 14]); contorno(); }
      else if (base === 'capelo') { forma(COR_ACO_ESC, [-12, 15], [-12, -3], [-6, -13], [6, -13], [12, -3], [12, 15], [6, 15], [6, 0], [-6, 0], [-6, 15]); contorno(); }
      else if (base === 'keffiyeh') { forma('#e8e0cc', [-13, 15], [-12, -4], [0, -13], [12, -4], [13, 15], [6, 15], [6, 0], [-6, 0], [-6, 15]); contorno(); linha('#2a2a2a', 2.5, [-11, -4], [11, -4]); }
      else if (base === 'turbante') { forma(COR_ACO_ESC, [-12, 15], [-12, 2], [12, 2], [12, 15], [6, 15], [6, 6], [-6, 6], [-6, 15]); contorno(); forma('#efe7d6', [-12, 3], [-10, -9], [0, -14], [10, -9], [12, 3]); contorno(); linha('#c8b898', 1.5, [-10, -4], [10, -8]); }
      else if (base === 'elmoPontudo') { forma(COR_ACO, [-12, 6], [-10, -4], [0, -19], [10, -4], [12, 6]); contorno(); forma(COR_ACO_ESC, [-12, 6], [12, 6], [13, 15], [-13, 15]); contorno(); }
      else if (base === 'elmoGrande') { forma(COR_ACO, [-11, 15], [-11, -12], [11, -12], [11, 15]); contorno(); linha('#111', 2.5, [-9, -2], [-2, -2]); linha('#111', 2.5, [2, -2], [9, -2]); linha(COR_OURO_IC, 2, [0, -11], [0, 13]); }
      else { forma(COR_ACO, [-12, 8], [-11, -2], [0, -16], [11, -2], [12, 8]); contorno(); linha(COR_ACO_ESC, 3, [0, 8], [0, 15]); }
    } else if (cat === 'armadura') {
      const cor = { gambesao: '#b8a27a', sobreveste: '#c9a03a', jaque: '#6a4a2a', gibao: '#d8cfb4', couroCozido: '#8a5a2a', habito: '#5a4a3a',
                    couracaTurca: '#8a8270', lamelar: '#7a7a70', cazagante: '#7a2a2a', cotaSemMangas: '#9aa0a8' }[base] || COR_ACO_ESC;
      forma(cor, [-8, -15], [8, -15], [16, -8], [12, -2], [9, -5], [9, 16], [-9, 16], [-9, -5], [-12, -2], [-16, -8]); contorno();
      if (base === 'sobreveste') { linha('#9a1a14', 3.5, [0, -12], [0, 13]); linha('#9a1a14', 3.5, [-7, -3], [7, -3]); }
      if (['couracaTurca', 'lamelar'].includes(base)) for (let yy = -10; yy < 16; yy += 3) for (let xx = -8; xx < 9; xx += 4) linha('rgba(255,255,255,0.22)', 1, [xx, yy], [xx + 2, yy]);
      if (base === 'cotaSemMangas') forma('#2a241c', [-16, -8], [-9, -5], [-9, -15], [-8, -15]);
      if (base === 'cota') for (let yy = -10; yy < 16; yy += 4) linha('rgba(255,255,255,0.25)', 1, [-8, yy], [8, yy]);
    } else if (cat === 'luvas') {
      forma(base === 'manoplas' ? COR_ACO_ESC : COR_COURO, [-8, 14], [-8, -2], [-12, -6], [-9, -9], [-5, -4], [-5, -14], [7, -14], [8, 14]); contorno();
    } else if (cat === 'botas') {
      forma(base === 'botasCano' ? '#5a3a22' : COR_COURO, [-6, -15], [4, -15], [4, 8], [14, 10], [14, 15], [-6, 15]); contorno();
    } else if (cat === 'cinto') {
      forma(base === 'cintoCavaleiro' ? '#5a3a22' : COR_COURO, [-17, -4], [17, -4], [17, 4], [-17, 4]); contorno();
      ctx.strokeStyle = base === 'cintoCouro' ? '#999' : COR_OURO_IC; ctx.lineWidth = 2; ctx.strokeRect(-5, -6, 10, 12);
      if (base === 'cintoCavaleiro') for (const xx of [-13, -9, 9, 13]) forma(COR_OURO_IC, [xx - 1.5, -2], [xx + 1.5, -2], [xx + 1.5, 2], [xx - 1.5, 2]);
    } else if (cat === 'colar') {
      ctx.strokeStyle = '#a08a60'; ctx.lineWidth = 1.2; ctx.beginPath(); ctx.arc(0, -6, 11, 0.2, Math.PI - 0.2); ctx.stroke();
      if (base === 'relicario') { forma(COR_OURO_IC, [-5, 4], [5, 4], [5, 14], [-5, 14]); contorno(); }
      else { linha(COR_OURO_IC, 3, [0, 3], [0, 17]); linha(COR_OURO_IC, 3, [-5, 8], [5, 8]); }
    } else if (cat === 'anel') {
      ctx.strokeStyle = base === 'sinete' ? COR_OURO_IC : '#d8d8e0'; ctx.lineWidth = 3.5; ctx.beginPath(); ctx.arc(0, 3, 8, 0, Math.PI * 2); ctx.stroke();
      if (base === 'sinete') forma(COR_OURO_IC, [-4, -9], [4, -9], [4, -3], [-4, -3]);
    }
    // engastes: bolinhas das gemas no canto
    (item.gemas || []).forEach((g, k) => { ctx.fillStyle = GEMAS[g.gema].cor; ctx.beginPath(); ctx.arc(-15 + k * 6, 15, 2.6, 0, Math.PI * 2); ctx.fill(); });
  }
  ctx.restore();
}

// --- Janela de opções de um item ---------------------------------------

// Um mercador que compra (Bulos, Rogério) está perto o bastante para negociar?
function mercadorPerto() {
  return npcsDoMapa().find((n) => /Bulos|Rogério|Ugolino/.test(n.nome) && Math.hypot(n.x - jogador.x, n.y - jogador.y) < 6) || null;
}

// Tira o item de onde ele estiver (alforje, mão, reserva ou corpo)
function tirarItem(item) {
  const k = jogador.alforje.indexOf(item);
  if (k >= 0) { jogador.alforje.splice(k, 1); return true; }
  for (const lista of [jogador.armas, jogador.escudos]) {
    const j = lista.indexOf(item);
    if (j >= 0) { lista[j] = null; return true; }
  }
  for (const id in jogador.equipamento) if (jogador.equipamento[id] === item) { jogador.equipamento[id] = null; return true; }
  return false;
}

function abrirMenuItem(item, origem) {
  const opcoes = [];
  const op = (texto, fazer, ativa = true, dica = '') => opcoes.push({ texto, fazer, ativa, dica });
  const gema = item.tipo === 'gema';
  if (origem.alforje) {
    if (gema) op('Encaixar num item', () => { gemaSelecionada = item; });
    else if (item.tipo === 'remedio') {
      op('Usar agora', () => usarRemedioDoAlforje(item));
      op('Pôr no cinto', () => remedioParaOCinto(item), cinto[item.remedio] < maximoPorRemedio(),
         cinto[item.remedio] < maximoPorRemedio() ? '' : 'cinto cheio');
    }
    else op('Equipar', () => equipar(jogador.alforje.indexOf(item)));
  } else if (origem.reserva) {
    op('Usar este conjunto (Q)', () => trocarArma(), !ataque);
    op('Guardar no alforje', () => {
      if (jogador.alforje.length >= TAMANHO_ALFORJE) { avisar('O alforje está cheio.'); return; }
      tirarItem(item); jogador.alforje.push(item); recalcularAtributos();
    });
  } else {
    op('Desequipar (guardar no alforje)', () => desequipar(origem.onde, origem.id), jogador.alforje.length < TAMANHO_ALFORJE,
       jogador.alforje.length >= TAMANHO_ALFORJE ? 'alforje cheio' : '');
  }
  op('Largar no chão', () => { tirarItem(item); largarItem(item, jogador.x, jogador.y); recalcularAtributos(); });
  const m = mercadorPerto();
  const preco = precoDeVenda(item);
  op(`Vender por ${preco} de ouro`, () => {
    tirarItem(item); jogador.ouro += preco; estoqueMartim.push(item); recalcularAtributos();
    avisar(`${m.nome.split(',')[0]} pagou ${preco} de ouro.`);
  }, !!m, m ? '' : 'só perto de um mercador');
  opcoes[opcoes.length - 1].confirmar = true;
  op('Cancelar', () => {});
  menuItem = { item, opcoes, x: mouse.x, y: mouse.y };
}

// Janela do item: a ficha completa (detalhes) à esquerda e as opções à direita,
// no meio da tela. Vender pede um segundo toque (para não vender sem querer).
function desenharMenuItem() {
  if (!menuItem) return;
  const toque = MODO.toque;
  const alt = toque ? 40 : 30, optW = toque ? 250 : 236, fichaW = 340, pad = 12;
  const ficha = fichaDoItem(menuItem.item, menuItem.oferta) || { cor: corDoItem(menuItem.item), linhas: [{ t: menuItem.item.nome, cor: corDoItem(menuItem.item) }] };
  // linhas da ficha já quebradas
  const linhas = [];
  for (const l of ficha.linhas) {
    ctx.font = l.fonte || '13px Alegreya, Georgia, serif';
    for (const t of linhasDeTexto(l.t, fichaW - 24)) linhas.push({ ...l, t });
  }
  const altFicha = 16 + linhas.length * 20;
  const altOpc = 34 + menuItem.opcoes.length * alt;
  const w = Math.min(canvas.width - 16, fichaW + optW + pad * 3);
  const fw = w - optW - pad * 3;
  const h = Math.min(canvas.height - 16, Math.max(altFicha, altOpc) + pad * 2);
  const x = (canvas.width - w) / 2, y = (canvas.height - h) / 2;
  menuItem.janela = { x, y, w, h };
  // fundo escurecido e a janela
  ctx.fillStyle = 'rgba(0, 0, 0, 0.5)'; ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'rgb(18, 15, 12)'; ctx.fillRect(x, y, w, h);
  ctx.strokeStyle = ficha.cor; ctx.lineWidth = 2; ctx.strokeRect(x + 1, y + 1, w - 2, h - 2); ctx.lineWidth = 1;
  // ficha (rola se for comprida)
  const fx = x + pad, fy = y + pad, fh = h - pad * 2;
  const off = regiaoRolavel('fichaItem', fx, fy, fw, fh, altFicha);
  ctx.save(); recortar(fx, fy, fw, fh);
  linhas.forEach((l, i) => {
    ctx.font = l.fonte || '13px Alegreya, Georgia, serif'; ctx.fillStyle = l.cor;
    ctx.fillText(l.t, fx + 4, fy + 18 + i * 20 - off);
  });
  ctx.restore();
  barraDeRolagem('fichaItem');
  // separador e opções
  const ox = x + w - optW - pad;
  ctx.strokeStyle = '#3d362c'; ctx.beginPath(); ctx.moveTo(ox - pad / 2, y + pad); ctx.lineTo(ox - pad / 2, y + h - pad); ctx.stroke();
  ctx.font = FONTE_SC ? FONTE_SC(13) : 'bold 13px serif'; ctx.fillStyle = '#bba57a';
  ctx.fillText('O que fazer?', ox + 4, y + pad + 16);
  menuItem.opcoes.forEach((o, k) => {
    o.area = { x: ox, y: y + pad + 26 + k * alt, w: optW, h: alt - 4 };
    const sob = !toque && o.ativa && mouseEm(o.area);
    ctx.fillStyle = o.confirmando ? 'rgba(200, 70, 50, 0.35)' : sob ? 'rgba(232, 185, 49, 0.18)' : 'rgba(255, 255, 255, 0.04)';
    ctx.fillRect(o.area.x, o.area.y, o.area.w, o.area.h);
    if (o.confirmando) { ctx.strokeStyle = '#e0574a'; ctx.strokeRect(o.area.x + 0.5, o.area.y + 0.5, o.area.w - 1, o.area.h - 1); }
    ctx.font = (o.confirmando ? 'bold ' : '') + '13.5px Alegreya, Georgia, serif';
    ctx.fillStyle = !o.ativa ? '#5e574b' : o.confirmando ? '#ffd0c0' : '#efe7d6';
    const texto = o.confirmando ? (toque ? 'Toque de novo para vender' : 'Clique de novo para vender') : o.texto;
    ctx.fillText(texto, o.area.x + 8, o.area.y + o.area.h / 2 + 4, optW - 16);
    if (o.dica && !o.confirmando) {
      ctx.font = 'italic 11px Alegreya, Georgia, serif'; ctx.fillStyle = '#7d7363'; ctx.textAlign = 'right';
      ctx.fillText(o.dica, o.area.x + o.area.w - 6, o.area.y + o.area.h / 2 + 4);
      ctx.textAlign = 'left';
    }
  });
}

// Clique com a janela do item aberta. Devolve true se ela continua aberta.
function cliqueNoMenuItem(botao) {
  if (!menuItem) return false;
  const op = menuItem.opcoes.find((o) => o.area && mouseEm(o.area));
  if (op) {
    if (!op.ativa || botao !== 0) return true;
    if (op.confirmar && !op.confirmando) {           // vender: pede confirmação
      for (const o of menuItem.opcoes) o.confirmando = false;
      op.confirmando = true;
      return true;
    }
    menuItem = null;
    op.fazer();
    return false;
  }
  // dentro da janela (lendo a ficha): fica aberta; fora dela: fecha
  if (menuItem.janela && mouseEm(menuItem.janela)) {
    for (const o of menuItem.opcoes) o.confirmando = false;
    return true;
  }
  menuItem = null;
  return false;
}

// --- Ficha do item sob o cursor (no chão, no painel ou no cinto) ---

function desenharFicha() {
  if (menuItem) return;          // com a janela do item aberta, a ficha some
  let item = null;
  const noChao = itemNoChaoSobOMouse();
  if (noChao) item = noChao.item;
  if (inventarioAberto) {
    const area = areasPainel.find(mouseEm);
    if (area && area.item) item = area.item;
  }
  if (!item && remedioSobOMouse) item = { tipo: 'remedio', remedio: remedioSobOMouse, nome: REMEDIOS[remedioSobOMouse].nome };
  remedioSobOMouse = null;
  const oferta = ofertaSobOMouse();
  if (oferta && oferta.item) item = oferta.item;
  if (!item || item.tipo === 'ouro') return;
  mostrarFicha(item, oferta);
}

// Monta a ficha do item e a desenha (ou só devolve as linhas, para a janela do item)
let _capturaFicha = null;
function fichaDoItem(item, oferta) {
  _capturaFicha = {};
  try { mostrarFicha(item, oferta); } finally { var f = _capturaFicha; _capturaFicha = null; }
  return f.linhas ? f : null;
}

function mostrarFicha(item, oferta) {
  // Na loja, a ficha mostra o preço
  const preco = oferta && oferta.item === item
    ? { t: oferta.modo === 'comprar' ? `Preço: ${oferta.preco} de ouro` : `O Bulos paga: ${oferta.preco} de ouro`, cor: COR_OURO } : null;
  if (item.tipo === 'gema') {
    const ls = linhasDaFichaGema(item);
    if (preco) ls.push(preco); else ls.push({ t: `Vale ${precoDeVenda(item)} de ouro no ferreiro`, cor: '#8f846c' });
    desenharCaixaFicha(GEMAS[item.gema].cor, ls);
    return;
  }

  if (item.tipo === 'remedio') {
    const r = REMEDIOS[item.remedio];
    const efeitos = [r.vida && `${r.vida} de vida`, r.devocao && `${r.devocao} de devoção`].filter(Boolean).join(' e ');
    desenharCaixaFicha(COR_REMEDIO, [
      { t: r.nome, cor: COR_REMEDIO, fonte: 'bold 15px Alegreya, Georgia, serif' },
      { t: `Remédio · tecla ${r.tecla} · ${cinto[item.remedio]}/${maximoPorRemedio()} no cinto`, cor: '#a39a86' },
      { t: `Recupera ${efeitos} em ${r.duracao} s`, cor: '#efe7d6' },
      { t: r.texto, cor: '#d9cfbb', fonte: 'italic 13px Alegreya, Georgia, serif' },
      ...(preco ? [preco] : [])
    ]);
    return;
  }

  const cat = categoriaDe(item);
  const b = baseDe(item);
  const linhas = [
    { t: item.nome, cor: corDoItem(item), fonte: 'bold 15px Alegreya, Georgia, serif' },
    { t: `${RARIDADES[item.raridade].nome} · ${b.nome}${b.detalhe ? ', ' + b.detalhe : ''}`, cor: '#a39a86' }
  ];
  const branco = (t) => linhas.push({ t, cor: '#efe7d6' });

  if (cat === 'arma') {
    const s = statsDaArma(item);
    branco(`${b.maos === 2 ? 'Duas mãos' : 'Uma mão (aceita escudo)'} · Dano ${s.dano[0]} a ${s.dano[1]}`);
    branco(s.projetil ? `Alcance do virote ${Math.round(s.alcance)} m` : `Alcance ${s.alcance.toFixed(1)} m · golpe de ${s.arco}°`);
    branco(`${s.projetil ? 'Recarga' : 'Tempo de golpe'} ${s.tempo.toFixed(2)} s (${velocidadeDoGolpe(s.tempo)})`);
    if (s.sagrado[1] > 0) linhas.push({ t: `Dano sagrado ${s.sagrado[0]} a ${s.sagrado[1]}`, cor: COR_SAGRADO });
    if (s.fogo && s.fogo[1] > 0) linhas.push({ t: `Dano de fogo ${s.fogo[0]} a ${s.fogo[1]}`, cor: COR_FOGO });
    if (s.veneno > 0) linhas.push({ t: `Veneno: ${s.veneno} de dano por segundo, por 3 s`, cor: COR_VENENO });
    if (!s.projetil) {
      const media = (s.dano[0] + s.dano[1]) / 2;
      linhas.push({ t: `Dano por segundo ~${(media / s.tempo).toFixed(1)}`, cor: '#a39a86' });
    }
  } else if (cat === 'escudo') {
    branco(`Outra mão · segura ${Math.round(bloqueioDoEscudo(item) * 100)}% do golpe quando não se ataca`);
  } else if (b.defesa) {
    branco(`Defesa ${b.defesa}`);
  }
  if (b.capacidade) branco(`Cinto: +${b.capacidade} de cada remédio (cabem ${MAXIMO_SEM_CINTO + b.capacidade})`);
  if (temDurabilidade(item)) {
    linhas.push(quebrado(item) ? { t: `QUEBRADO · durabilidade 0 de ${item.durMax} (sem efeito até o conserto)`, cor: '#e0574a' }
                               : { t: `Durabilidade ${item.dur} de ${item.durMax}`, cor: gasto(item) ? '#e8b931' : '#a39a86' });
  }
  for (const [efeito, valor] of Object.entries(item.efeitos)) {
    linhas.push({ t: TEXTO_EFEITO[efeito](valor), cor: quebrado(item) ? '#55604f' : '#7fa6ef' });
  }
  const eng = linhaDosEngastes(item);
  if (eng) linhas.push(eng);
  if (item.texto) linhas.push({ t: item.texto, cor: '#d4a04c', fonte: 'italic 13px Alegreya, Georgia, serif' });

  // Peça de conjunto: as outras peças e os bônus, acesos quando valem
  if (item.conjunto) {
    const c = CONJUNTOS[item.conjunto];
    const n = pecasDoConjuntoEquipadas(item.conjunto);
    const equipados = itensEquipados().map((x) => x.nome);
    linhas.push({ t: c.nome, cor: '#6cc35f', fonte: 'bold 13px Alegreya, Georgia, serif' });
    for (const p of c.pecas) linhas.push({ t: '  ' + p.nome, cor: equipados.includes(p.nome) ? '#6cc35f' : '#55604f' });
    for (const [minimo, efeitos] of Object.entries(c.bonus)) {
      const texto = Object.entries(efeitos).map(([k, v]) => TEXTO_EFEITO[k](v)).join(', ');
      linhas.push({ t: `(${minimo} peças) ${texto}`, cor: n >= Number(minimo) ? '#6cc35f' : '#55604f' });
    }
  }

  const arvItem = cat === 'arma' && typeof arvoreDaArma === 'function' && arvoreDaArma(item);
  if (arvItem) {
    const t = ARVORES_ARMA.find((a) => a.id === arvItem);
    linhas.push({ t: `Árvore: ${t.nome.toLowerCase()} (${pontosNaArvore(arvItem)} pontos)`, cor: '#8f846c' });
  }
  if (preco) linhas.push(preco);
  else linhas.push({ t: `Vale ${precoDeVenda(item)} de ouro no ferreiro`, cor: '#8f846c' });
  desenharCaixaFicha(corDoItem(item), linhas);
}

function desenharCaixaFicha(corBorda, linhas) {
  if (_capturaFicha) { _capturaFicha.cor = corBorda; _capturaFicha.linhas = linhas; return; }
  // linhas compridas quebram; se a ficha não couber na tela (celular deitado), ela encolhe
  const larg = 340;
  const todas = [];
  for (const l of linhas) {
    ctx.font = l.fonte || '13px Alegreya, Georgia, serif';
    for (const t of linhasDeTexto(l.t, larg - 24)) todas.push({ ...l, t });
  }
  const altNormal = 16 + todas.length * 20;
  const escala = Math.min(1, (canvas.height - 16) / altNormal);
  const w = larg * escala, alt = altNormal * escala;
  let x = mouse.x + 18, y = mouse.y + 18;
  if (x + w > canvas.width - 8) x = mouse.x - w - 18;
  if (x < 8) x = 8;
  if (y + alt > canvas.height - 8) y = canvas.height - alt - 8;
  if (y < 8) y = 8;
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(escala, escala);
  ctx.fillStyle = 'rgba(12, 10, 8, 0.97)';
  ctx.fillRect(0, 0, larg, altNormal);
  ctx.strokeStyle = corBorda;
  ctx.strokeRect(0.5, 0.5, larg - 1, altNormal - 1);
  todas.forEach((l, i) => {
    ctx.font = l.fonte || '13px Alegreya, Georgia, serif';
    ctx.fillStyle = l.cor;
    ctx.fillText(l.t, 12, 24 + i * 20);
  });
  ctx.restore();
}

