    const g = ctx.createLinearGradient(0, yb, 0, yb + 6); g.addColorStop(0, '#e0574a'); g.addColorStop(1, '#8e1b14');
    ctx.fillStyle = g; ctx.fillRect(x + 12, yb, (w - 24) * frac, 6);
