let cronicaAberta = false;
let paginaSelecionada = null;
let novidadeNaCronica = false;
let paginasVistas = null;       // ids já liberados (para avisar só das novas)
let areasCronica = [];
let botaoCronica = null;

const paginasLiberadas = () => PAGINAS_CRONICA.filter((p) => p.libera());

// Chamado a cada quadro: avisa quando chega uma página nova
function atualizarCronica() {
  const ids = paginasLiberadas().map((p) => p.id);
  if (paginasVistas === null) { paginasVistas = new Set(ids); return; }   // ao abrir o jogo, não avisa das antigas
  for (const id of ids) {
    if (!paginasVistas.has(id)) {
      paginasVistas.add(id);
      const p = PAGINAS_CRONICA.find((x) => x.id === id);
      avisar(`Nova página na Crônica: ${p.titulo}`);
      novidadeNaCronica = true;
      paginaSelecionada = p;
    }
  }
}

function abrirCronica() {
  cronicaAberta = true;
  diarioAberto = false;
  novidadeNaCronica = false;
  if (!paginaSelecionada) paginaSelecionada = paginasLiberadas().slice(-1)[0];
}

window.addEventListener('keydown', (e) => {
  if (dialogo || menuOratorio || lojaAberta) return;
  const t = e.key.toLowerCase();
  if (t === 'c') cronicaAberta ? (cronicaAberta = false) : abrirCronica();
  else if (t === 'escape' && cronicaAberta) cronicaAberta = false;
});

// Cliques do botão e da crônica. Devolve true se o clique foi neles.
function cliqueNaCronica() {
  if (dentroDe(botaoCronica)) { cronicaAberta ? (cronicaAberta = false) : abrirCronica(); return true; }
  if (!cronicaAberta) return false;
  const area = areasCronica.find(dentroDe);
  if (area) area.acao();
  return true;
}

function desenharBotaoCronica(tempo) {
  // no celular, o botão fica na barra de cima (js/toque.js)
  botaoCronica = null; return;   // agora no painel de baixo (js/hud.js)
  const w = 120, h = 34;
  const x = canvas.width - 2 * w - 28, y = canvas.height - h - 16;
  botaoCronica = { x, y, w, h };
  const piscar = novidadeNaCronica && Math.floor(tempo / 450) % 2 === 0;
  ctx.fillStyle = piscar ? 'rgba(120, 90, 20, 0.95)' : 'rgba(20, 17, 14, 0.9)';
  ctx.fillRect(x, y, w, h);
  ctx.strokeStyle = novidadeNaCronica ? '#e8b931' : '#8c7a55';
  ctx.lineWidth = 2; ctx.strokeRect(x + 1, y + 1, w - 2, h - 2); ctx.lineWidth = 1;
  ctx.font = 'bold 14px Alegreya, Georgia, serif';
  ctx.fillStyle = dentroDe(botaoCronica) || piscar ? '#ffe9a8' : '#e8b931';
  ctx.fillText('Crônica', x + 14, y + 22);
  ctx.font = '11px monospace'; ctx.fillStyle = '#8f846c';
  ctx.fillText('C', x + w - 18, y + 21);
}

function desenharCronica() {
  areasCronica = [];
  if (!cronicaAberta) return;
  // no celular, a janela ocupa a tela toda abaixo da barra de botões
  const toque = typeof MODO !== 'undefined' && MODO.toque;
  const hud = alturaHud();
  const w = Math.min(760, canvas.width - (toque ? 16 : 32)), h = toque ? canvas.height - 16 : Math.min(500, canvas.height - 110 - hud);
  const x = (canvas.width - w) / 2, y = toque ? 8 : Math.max(16, (canvas.height - hud - h) / 2 - 30);

  // Pergaminho escuro
  ctx.fillStyle = 'rgba(30, 24, 16, 0.98)';
  ctx.fillRect(x, y, w, h);
  ctx.strokeStyle = '#c9a25a'; ctx.lineWidth = 2;
  ctx.strokeRect(x + 1, y + 1, w - 2, h - 2);
  ctx.strokeStyle = '#5c4a2c'; ctx.lineWidth = 1;
  ctx.strokeRect(x + 7.5, y + 7.5, w - 15, h - 15);

  ctx.font = 'bold 20px Alegreya, Georgia, serif'; ctx.fillStyle = '#e8b931';
  ctx.fillText('Crônica de 1177', x + 22, y + 36);
  const liberadas = paginasLiberadas();
  ctx.font = '12px monospace'; ctx.fillStyle = '#8f846c';
  ctx.fillText(`${liberadas.length} de ${PAGINAS_CRONICA.length} páginas`, x + 200, y + 35);

  const fechar = { x: x + w - 40, y: y + 14, w: 28, h: 28, acao: () => { cronicaAberta = false; } };
  areasCronica.push(fechar);
  ctx.font = 'bold 18px monospace'; ctx.fillStyle = dentroDe(fechar) ? '#ffe9a8' : '#8f846c';
  ctx.fillText('×', fechar.x + 8, fechar.y + 20);

  const toqueEstreito = toque && w < 640;
  const topo = y + 58, colEsq = toqueEstreito ? 190 : 236;
  const baseY = y + h - 16;
  ctx.strokeStyle = '#4a3d28';
  ctx.beginPath(); ctx.moveTo(x + colEsq + 22, topo); ctx.lineTo(x + colEsq + 22, baseY); ctx.stroke();

  // Lista de páginas (rola se não couber): as recebidas, e as que ainda virão
  const offL = regiaoRolavel('cronicaLista', x + 10, topo, colEsq + 8, baseY - topo, PAGINAS_CRONICA.length * 40);
  ctx.save();
  recortar(x + 10, topo, colEsq + 8, baseY - topo);
  PAGINAS_CRONICA.forEach((p, i) => {
    const temos = p.libera();
    const linha = { x: x + 14, y: topo + i * 40 - offL, w: colEsq, h: 36, acao: () => { if (temos) paginaSelecionada = p; } };
    if (linha.y + linha.h < topo || linha.y > baseY) return;
    // só a parte visível conta para o clique
    const vis = { ...linha, y: Math.max(linha.y, topo) };
    vis.h = Math.min(linha.y + linha.h, baseY) - vis.y;
    areasCronica.push(vis);
    const sel = paginaSelecionada === p;
    if (sel || (temos && dentroDe(vis))) {
      ctx.fillStyle = sel ? 'rgba(232, 185, 49, 0.15)' : 'rgba(255,255,255,0.04)';
      ctx.fillRect(linha.x, linha.y, linha.w, linha.h);
    }
    ctx.font = (sel ? 'bold ' : '') + '14px Alegreya, Georgia, serif';
    ctx.fillStyle = temos ? (sel ? '#ffe9a8' : '#e2d6bb') : '#5c554a';
    ctx.fillText(temos ? p.titulo : 'Página ainda não escrita', linha.x + 10, linha.y + 16, colEsq - 16);
    ctx.font = '11px monospace'; ctx.fillStyle = temos ? '#a08a5c' : '#4a443a';
    ctx.fillText(p.data, linha.x + 10, linha.y + 31);
  });
  ctx.restore();
  barraDeRolagem('cronicaLista');

  // A página escolhida (mede, depois desenha numa região que rola)
  const p = paginaSelecionada && paginaSelecionada.libera() ? paginaSelecionada : null;
  const dx = x + colEsq + 44, dw = w - colEsq - 74;
  if (!p) return;
  const blocos = [];
  const escrever = (texto, cor, fonte, entre = 20) => {
    ctx.font = fonte;
    for (const l of linhasDeTexto(texto, dw)) blocos.push({ l, cor, fonte, alt: entre });
    blocos[blocos.length - 1].alt += 8;
  };
  blocos.push({ l: p.titulo, cor: '#e8b931', fonte: 'bold 19px Alegreya, Georgia, serif', alt: 20 });
  blocos.push({ l: p.data, cor: '#a08a5c', fonte: 'italic 13px Alegreya, Georgia, serif', alt: 26 });
  const fonteTexto = (toque ? '16px' : '15px') + ' Alegreya, Georgia, serif';
  for (const par of p.texto) escrever(par, '#e8dfc8', fonteTexto, toque ? 21 : 20);
  if (p.tomas) escrever(p.tomas, '#c9a25a', 'italic 14px Alegreya, Georgia, serif');
  blocos[blocos.length - 1].alt += 4;
  escrever('Fonte: ' + p.fonte, '#8f846c', '12px Alegreya, Georgia, serif', 17);
  const total = blocos.reduce((t, b) => t + b.alt, 0) + 10;
  if (paginaRolada !== p) { zerarRolagem('cronicaPagina'); paginaRolada = p; }
  const ry = topo, rh = baseY - topo;
  const off = regiaoRolavel('cronicaPagina', dx - 6, ry, dw + 20, rh, total);
  ctx.save();
  recortar(dx - 6, ry, dw + 20, rh);
  let dy = topo + 18 - off;
  for (const b of blocos) { ctx.font = b.fonte; ctx.fillStyle = b.cor; ctx.fillText(b.l, dx, dy); dy += b.alt; }
  ctx.restore();
  barraDeRolagem('cronicaPagina');
}
let paginaRolada = null;

