// Monta a aparência de Tomás a partir do que ele tem equipado
function aparenciaDoJogador() {
  const eq = jogador.equipamento;
  const arma = armaAtiva(), escudo = escudoAtivo();
  return {
    sexo: 'm',
    cabeca: eq.elmo ? VISUAL_ITEM[eq.elmo.base] : 'male_head1',
    tronco: eq.armadura ? VISUAL_ITEM[eq.armadura.base] : 'cloth_shirt',
    pernas: eq.armadura && ['cota', 'sobreveste', 'cazagante'].includes(eq.armadura.base) ? 'chain_greaves'
          : eq.armadura && ['couracaTurca', 'gibao', 'lamelar'].includes(eq.armadura.base) ? 'calca_branca' : 'cloth_pants',
    maos: eq.luvas ? VISUAL_ITEM[eq.luvas.base] : null,
    pes: eq.botas ? VISUAL_ITEM[eq.botas.base] : 'cloth_sandals',
    main: arma ? VISUAL_ITEM[arma.base] || null : null,
    off: escudo ? VISUAL_ITEM[escudo.base] : null
  };
}

