// ---------------------------------------------------------------------
// Estado de animação de cada personagem
// ---------------------------------------------------------------------
// Guardamos a animação atual e quando ela começou, para saber o quadro.
function animar(obj, nome, agora) {
  if (!obj._anim || obj._anim.nome !== nome) obj._anim = { nome, inicio: agora };
  return (agora - obj._anim.inicio) / 1000;
}

// Anda? Comparamos com a posição do quadro anterior. Também somamos a
// distância percorrida (em metros), que comanda a animação de corrida.
// Uma pequena folga (0,1 s) evita piscar a pose parada quando o
// personagem esbarra numa parede por um único quadro.
function estaAndando(obj) {
  const agora = performance.now();
  const passo = obj._ultimaPos ? Math.hypot(obj.x - obj._ultimaPos.x, obj.y - obj._ultimaPos.y) : 0;
  obj._ultimaPos = { x: obj.x, y: obj.y };
  if (passo > 1.5) return false;   // trocou de mapa ou viajou: não é passo
  if (passo > 0.0005) {
    obj._distancia = (obj._distancia || 0) + passo * METROS_POR_TILE;
    obj._andouEm = agora;
  }
  return obj._andouEm !== undefined && agora - obj._andouEm < 100;
}

// PÉS PRESOS AO CHÃO
// A corrida foi renderizada em 16 quadros escolhidos (medindo os ossos do pé
// no modelo 3D) para que o pé apoiado avance sempre a mesma distância de um
// quadro para o outro. Um ciclo inteiro (duas passadas) mede 3,24 m para um
// personagem de 1,75 m. Trocamos o quadro pela distância andada, e não pelo
// relógio: assim o pé no chão acompanha o chão, em qualquer velocidade.
const CICLO_CORRIDA_M = 3.24;
function faseDaCorrida(obj, altura, cicloM) {
  const ciclo = cicloM || CICLO_CORRIDA_M * altura / 1.75;
  return ((obj._distancia || 0) % ciclo) / ciclo;
}

