// Índice: id -> { h, arvore, fileira }
const INDICE_HABILIDADES = {};
for (const [arvore, lista] of Object.entries(HABILIDADES)) for (const h of lista) INDICE_HABILIDADES[h.id] = { h, arvore, fileira: h.fil };

const caminhoDoJogador = () => jogador.estilo || flags.caminho || null;
const arvoreDoCaminho = () => ARVORE_DO_CAMINHO[caminhoDoJogador()] || 'espada';
const pontosEm = (id) => (jogador.habilidades && jogador.habilidades[id]) || 0;
const maximoDe = (h) => h.tipo === 'passiva' ? MAX_PASSIVA : MAX_ATIVA;
const custoDe = (h) => h.custo;
// Pontos a mais vindos dos itens no corpo: "+1 em Aparar" (hab_aparar) e
// "+1 nas habilidades de espada" (arv_espada). Valem mesmo acima do máximo.
function extraDosItens(id) {
  const info = INDICE_HABILIDADES[id];
  if (!info) return 0;
  let n = 0;
  const itens = [jogador.armas[jogador.armaAtiva], jogador.escudos[jogador.armaAtiva], ...Object.values(jogador.equipamento || {})];
  for (const it of itens) {
    if (!it || !it.efeitos || (typeof quebrado === 'function' && quebrado(it))) continue;
    n += (it.efeitos['hab_' + id] || 0) + (it.efeitos['arv_' + info.arvore] || 0);
  }
  return n;
}
const nivelDe = (id) => pontosEm(id) + extraDosItens(id);
const pontosNaArvore = (arv) => HABILIDADES[arv].reduce((s, h) => s + pontosEm(h.id), 0);

// A árvore da arma na mão (a do escudo vale à parte)
function arvoreDaArma(item) {
  if (!item) return null;
  const a = ARVORES_ARMA.find((t) => t.armas && t.armas.includes(item.base));
  return a ? a.id : null;
}
function arvoreValeAgora(arv) {
  if (arv === 'escudo') return !!escudoAtivo();
  return arvoreDaArma(armaAtiva()) === arv;
}

// Pode pôr mais um ponto? Devolve null se pode, ou o motivo
function motivoParaNaoAprender(id) {
  const info = INDICE_HABILIDADES[id];
  if (!info) return 'Habilidade desconhecida.';
  if (pontosEm(id) >= maximoDe(info.h)) return 'Já está no máximo.';
  if (jogador.nivel < NIVEL_DA_FILEIRA[info.fileira]) return `Pede nível ${NIVEL_DA_FILEIRA[info.fileira]}.`;
  const precisa = PONTOS_NA_ARVORE[info.fileira];
  if (pontosNaArvore(info.arvore) < precisa) return `Pede ${precisa} pontos nesta árvore.`;
  if (!jogador.pontosHabilidade) return 'Sem pontos de habilidade.';
  return null;
}

function aprenderHabilidade(id) {
  const motivo = motivoParaNaoAprender(id);
  if (motivo) { avisarUmaVez(motivo); return false; }
  jogador.habilidades[id] = pontosEm(id) + 1;
  jogador.pontosHabilidade--;
  const h = INDICE_HABILIDADES[id].h;
  // a ativa aprendida vai para o primeiro atalho livre
  if (h.tipo === 'ativa' && !jogador.atalhos.includes(id)) {
    const livre = jogador.atalhos.findIndex((x) => !x);
    if (livre >= 0) jogador.atalhos[livre] = id;
  }
  recalcularAtributos();
  return true;
}

// Ponto de graça no começo: a primeira ativa da árvore do caminho
function darPrimeiroPonto() {
  const arv = arvoreDoCaminho();
  const h = HABILIDADES[arv].find((x) => x.fil === 0 && x.tipo === 'ativa');
  if (h && !pontosEm(h.id)) { jogador.habilidades[h.id] = 1; if (!jogador.atalhos[0]) jogador.atalhos[0] = h.id; }
}

// A arma na mão é da árvore desta habilidade?
function armaDaHabilidade(h) {
  const arv = INDICE_HABILIDADES[h.id].arvore;
  return arvoreValeAgora(arv);
}

// --- Bônus das passivas, da proficiência e das posturas (somados em recalcularAtributos) ---
function bonusDasHabilidades() {
  const total = {};
  const somar = (ef) => { for (const [k, v] of Object.entries(ef)) if (typeof v === 'number') total[k] = (total[k] || 0) + v; };
  if (jogador.habilidades) {
    for (const [arv, lista] of Object.entries(HABILIDADES)) {
      if (!arvoreValeAgora(arv)) continue;
      for (const h of lista) {
        const r = nivelDe(h.id);
        if (r && h.tipo === 'passiva') somar(h.ef(r));
      }
    }
    // proficiência: cada ponto na árvore da arma na mão
    const arv = arvoreDaArma(armaAtiva());
    if (arv) { const n = pontosNaArvore(arv); somar({ danoPct: PROFICIENCIA.danoPct * n, tempoPct: PROFICIENCIA.tempoPct * n }); }
  }
  for (const p of jogador.posturas || []) somar(p.efeitos);
  return total;
}

// --- Usar uma habilidade ativa ---
let efeitosVisuais = [];   // anéis no chão (brado, investida, postura)
let areasDeFogo = [];      // o chão em chamas do virote incendiário

function ocupado() { return !!(ataque || jogador.rezando || jogador.giro || jogador.investida || jogador.rolamento); }

function usarHabilidade(id, angulo) {
  if (!id) { avisarUmaVez('Nenhuma habilidade neste atalho. Escolha uma na janela do Tomás (T).'); return; }
  const info = INDICE_HABILIDADES[id];
  const r = nivelDe(id);
  if (!info || !r) return;
  const h = info.h;
  if (ocupado()) return;
  if (info.arvore === 'escudo' ? !escudoAtivo() : !armaDaHabilidade(h)) {
    const arv = ARVORES_ARMA.find((a) => a.id === info.arvore);
    if (arv.escudo) avisarUmaVez('Precisa de um escudo na outra mão.');
    else avisarUmaVez(`${h.nome} pede ${arv.nome.toLowerCase()} na mão.`);
    return;
  }
  if (jogador.devocao < custoDe(h)) { avisarUmaVez('Sem devoção. Reze (R) ou vá a um oratório.'); return; }
  jogador.devocao -= custoDe(h);
  const e = h.ef(r);
  jogador.angulo = angulo;
  const base = () => {
    const s = { ...statsDaArma(armaAtiva()) };
    if (e.danoMult) s.dano = s.dano.map((d) => Math.round(d * e.danoMult));
    if (e.alcanceMult) s.alcance *= e.alcanceMult;
    if (e.arco) s.arco = e.arco;
    if (e.critico) s.critico = Math.max(s.critico, e.critico);
    s.tempo += e.tempoExtra || 0;
    s.atordoa = e.atordoa || 0;
    for (const k of ['ignoraEscudo', 'guardaMult', 'quebraEscudo', 'gancho', 'misericordia', 'martelar', 'incendio', 'sagradoExtra', 'fogoExtra', 'venenoExtra', 'detonaVeneno'])
      if (e[k] !== undefined) s[k] = e[k];
    return s;
  };
  switch (h.modo) {
    case 'golpe':
      ataque = { t: 0, total: base().tempo, angulo, stats: base(), aplicado: false, especial: h, alvo: alvoInimigo };
      break;
    case 'serie': {
      const s = base(); s.tempo = Math.max(0.2, (s.tempo - (e.tempoExtra || 0)) * e.tempoMult);
      ataque = { t: 0, total: s.tempo, angulo, stats: s, aplicado: false, especial: h, alvo: alvoInimigo, serie: e.golpes - 1 };
      break;
    }
    case 'tiro': {
      const s = base();
      Object.assign(s, { perfura: !!e.perfura, virotes: e.virotes || 1, leque: e.leque || 0, recuo: e.recuo || 0 });
      ataque = { t: 0, total: s.tempo, angulo, stats: s, aplicado: false, especial: h, alvo: alvoInimigo };
      break;
    }
    case 'giro': {
      const s = base(); s.arco = 360;
      jogador.giro = { restante: e.duracao, prox: 0, intervalo: e.intervalo, stats: s };
      destino = { x: jogador.x + Math.cos(angulo) * 4, y: jogador.y + Math.sin(angulo) * 4 };
      alvoInimigo = null;
      break;
    }
    case 'investida': {
      const s = base();
      jogador.investida = { dx: Math.cos(angulo), dy: Math.sin(angulo), restante: e.distancia, vel: 10, stats: s, golpe: true };
      destino = null;
      break;
    }
    case 'postura':
      jogador.posturas = (jogador.posturas || []).filter((p) => p.id !== h.id);
      jogador.posturas.push({ id: h.id, nome: h.nome, restante: e.duracao, total: e.duracao, efeitos: e.efeitos || {}, cor: h.cor,
                              firmar: e.firmar, pontas: e.pontas });
      recalcularAtributos();
      break;
    case 'aparar':
      jogador.aparando = e.janela; jogador.atordoaAparar = e.atordoa;
      destino = null; alvoInimigo = null;
      break;
    case 'brado': {
      const s = e.danoMult ? base() : null;
      for (const ini of inimigosVivos()) {
        if (Math.hypot(ini.x - jogador.x, ini.y - jogador.y) <= e.raio) {
          if (s) ferirInimigo(ini, s);
          ini.atordoado = Math.max(ini.atordoado || 0, e.atordoa * (ini.tipo.flagAoMorrer ? 0.35 : 1)); ini.preparo = 0; ini.recuo = 0; ini.estado = 'perseguindo';
        }
      }
      efeitosVisuais.push({ x: jogador.x, y: jogador.y, raio: e.raio, t: 0, dur: 0.6, cor: '255, 200, 120' });
      efeitoDeBrado(e.raio);
      if (s) tremerTela(0.22, 5);
      break;
    }
  }
  avisar(h.nome);
}

// F, G e H (e o botão do meio do mouse = F); no celular, os três botões de habilidade
function atacarEspecial(angulo, atalho = 0) { usarHabilidade(jogador.atalhos[atalho], angulo); }
function habilidadeDoAtalho(k) { const i = INDICE_HABILIDADES[jogador.atalhos[k]]; return i && nivelDe(i.h.id) ? i.h : null; }
function habilidadeDoF() { return habilidadeDoAtalho(0); }
const TECLAS_ATALHO = ['f', 'g', 'h'];

window.addEventListener('keydown', (e) => {
  if (dialogo || menuOratorio || transicao) return;
  const k = TECLAS_ATALHO.indexOf(e.key.toLowerCase());
  if (k >= 0) {
    const p = pontoDoMouseNoMundo();
    atacarEspecial(anguloAte(p.x, p.y), k);
  }
});
canvas.addEventListener('mousedown', (e) => {
  if (e.button !== 1 || dialogo || menuOratorio || transicao) return;
  e.preventDefault();
  const p = pontoDoMouseNoMundo();
  atacarEspecial(anguloAte(p.x, p.y), 0);
});

// Golpe em série: quando um golpe termina, começa o próximo (o Martelar pesa mais a cada um)
function proximoDaSerie(a) {
  if (!(a.serie > 0)) return null;
  let angulo = a.angulo;
  if (a.alvo && !a.alvo.morto) angulo = anguloAte(a.alvo.x, a.alvo.y);
  jogador.angulo = angulo;
  let stats = a.stats;
  if (stats.martelar) stats = { ...stats, dano: stats.dano.map((d) => Math.round(d * stats.martelar)) };
  return { t: 0, total: a.total, angulo, stats, aplicado: false, especial: a.especial, alvo: a.alvo, serie: a.serie - 1 };
}

// --- O que as habilidades fazem a cada golpe de Tomás (chamado por js/combate_base.js) ---
// Antes do golpe: muda os números; depois: empurra, puxa, sangra, racha o escudo
function antesDoGolpe(ini, s) {
  if (s.aliado) return s;
  const b = bonus;
  const s2 = { ...s, dano: [...s.dano] };
  // resposta: depois de aparar ou rolar, o próximo golpe é crítico
  if (jogador.respostaPronta && b.respostaPct) {
    s2.critico = 100; s2.dano = s2.dano.map((d) => Math.round(d * (1 + b.respostaPct / 100)));
    jogador.respostaPronta = false;
  }
  // embalo: golpes seguidos somam
  if (b.embaloPct && jogador.embalo) s2.dano = s2.dano.map((d) => Math.round(d * (1 + b.embaloPct * jogador.embalo / 100)));
  // olho de genovês: crítico em quem está longe
  if (b.criticoLonge && Math.hypot(ini.x - jogador.x, ini.y - jogador.y) * METROS_POR_TILE > 6) s2.critico = (s2.critico || 0) + b.criticoLonge;
  if (b.atordoaCritico) s2.atordoaCritico = b.atordoaCritico;
  if (b.guardaPct) s2.guardaMult = (s2.guardaMult || 1) * (1 + b.guardaPct / 100);
  // golpe no elmo e companhia: nos chefes, só um terço da tontura
  if (s2.atordoa && ini.tipo.flagAoMorrer) s2.atordoa *= 0.35;
  // misericórdia: tonto ou sem guarda e com pouca vida = morre
  // (nos chefes, só com metade disso)
  if (s2.misericordia && (ini.atordoado > 0 || ini.guardaQuebrada > 0) && ini.vida < ini.tipo.vida * s2.misericordia * (ini.tipo.flagAoMorrer ? 0.5 : 1)) {
    s2.dano = [Math.ceil(ini.vida) + 99, Math.ceil(ini.vida) + 99]; s2.ignoraEscudo = 1;
  }
  return s2;
}
function depoisDoGolpe(ini, s) {
  if (s.aliado || ini.morto) return;
  const b = bonus;
  if (b.embaloPct) jogador.embalo = Math.min(3, (jogador.embalo || 0) + 1);
  if (b.sangraDps) ini.sangra = { dps: b.sangraDps, t: 3 };
  const chefe = !!ini.tipo.flagAoMorrer;
  const empurrar = (dist, sentido = 1) => {
    if (chefe) dist *= 0.3;
    const a = Math.atan2(ini.y - jogador.y, ini.x - jogador.x) * 1;
    for (let k = 0; k < 6; k++) {
      const nx = ini.x + Math.cos(a) * sentido * dist / 6, ny = ini.y + Math.sin(a) * sentido * dist / 6;
      if (colide(nx, ny, ini.tipo.raio) || (sentido < 0 && Math.hypot(nx - jogador.x, ny - jogador.y) < 0.9)) break;
      ini.x = nx; ini.y = ny;
    }
  };
  if (b.empurra && !s.projetil) empurrar(b.empurra);
  if (s.quebraEscudo && (ini.escudo ?? ini.tipo.escudo)) {
    ini.escudo = 0;
    numeros.push({ x: ini.x, y: ini.y, altura: ini.tipo.altura + 0.6, texto: 'Escudo rachado!', cor: '#ffd76a', tempo: 1.2 });
  }
  if (s.gancho) {
    if (ini.guardaMax && !(ini.guardaQuebrada > 0) && typeof quebrarGuarda === 'function') quebrarGuarda(ini);
    empurrar(1.2, -1);
  }
}

// Defesas das habilidades quando Tomás é atingido (chamado por js/combate_base.js).
// Devolve o dano que sobra (0 = nada pegou).
function defesaDasHabilidades(dano, origem) {
  jogador.embalo = 0;
  // aparar: o golpe que chega na janela é anulado e quem bateu fica aberto
  if (jogador.aparando > 0 && origem && origem.tipo && Math.hypot(origem.x - jogador.x, origem.y - jogador.y) < 3) {
    origem.atordoado = Math.max(origem.atordoado || 0, (jogador.atordoaAparar || 1) * (origem.tipo.flagAoMorrer ? 0.5 : 1));
    origem.preparo = 0;
    jogador.respostaPronta = true;
    numeros.push({ x: jogador.x, y: jogador.y, altura: jogador.altura + 0.3, texto: 'Aparou!', cor: '#ffe9a8', tempo: 0.9, grande: true });
    if (typeof tocar === 'function') tocar('aco', { vol: 0.8 });
    if (typeof tremerTela === 'function') tremerTela(0.1, 2);
    return 0;
  }
  const b = bonus;
  const deFrente = origem && Math.abs(((Math.atan2(origem.y - jogador.y, origem.x - jogador.x) - jogador.angulo + 3 * Math.PI) % (2 * Math.PI)) - Math.PI) < Math.PI / 3;
  // flechas de frente batem no escudo (Rocha, Erguer o escudo)
  if (b.flechasDeFrente && escudoAtivo() && deFrente && origem && origem.tipo && origem.tipo.comportamento === 'atirador') {
    numeros.push({ x: jogador.x, y: jogador.y, altura: jogador.altura, texto: 'bloqueou', cor: '#c9d6f0', tempo: 0.7 });
    return 0;
  }
  // bloqueio no último instante: chance de atordoar quem bateu
  if (b.contraGolpe && escudoAtivo() && origem && origem.tipo && deFrente && Math.random() * 100 < b.contraGolpe) {
    origem.atordoado = Math.max(origem.atordoado || 0, origem.tipo.flagAoMorrer ? 0.5 : 1.2); origem.preparo = 0;
  }
  if (b.reducaoAtacando && ataque) dano *= 1 - b.reducaoAtacando / 100;
  return dano;
}

// Recuo depois do tiro (Tiro de recuo): salta para trás, sem golpe
function recuarDepoisDoTiro(angulo, distancia) {
  jogador.investida = { dx: -Math.cos(angulo), dy: -Math.sin(angulo), restante: distancia, vel: 9, golpe: false };
}

// --- A cada quadro: giro, investida, posturas, sangue, fogo e a lança firmada ---
function atualizarHabilidades(dt) {
  if (jogador.aparando > 0) jogador.aparando -= dt;
  // posturas acabam
  if (jogador.posturas && jogador.posturas.length) {
    for (const p of jogador.posturas) p.restante -= dt;
    const antes = jogador.posturas.length;
    jogador.posturas = jogador.posturas.filter((p) => p.restante > 0);
    if (jogador.posturas.length !== antes) recalcularAtributos();
  }
  // lança firmada e muralha de pontas: quem entra no alcance leva a ponta
  for (const p of jogador.posturas || []) {
    if (!p.firmar && !p.pontas) continue;
    const arma = armaAtiva();
    if (!arma || arvoreDaArma(arma) !== 'lanca') continue;
    const s = statsDaArma(arma);
    const alcance = s.alcance / METROS_POR_TILE + jogador.raio;
    for (const ini of inimigosVivos()) {
      const d = Math.hypot(ini.x - jogador.x, ini.y - jogador.y);
      if (d > alcance + ini.tipo.raio) { ini._fora = true; continue; }
      if ((ini._pontaEm || 0) > performance.now() - 1200) continue;
      const veioCorrendo = ini._fora && estaAndando(ini);
      if (p.firmar && !veioCorrendo) continue;
      ini._pontaEm = performance.now(); ini._fora = false;
      const mult = p.firmar || p.pontas;
      ferirInimigo(ini, { ...s, dano: s.dano.map((x) => Math.round(x * mult)), atordoa: p.firmar ? 0.8 : 0 });
    }
  }
  // sangramento
  for (const ini of inimigos) {
    if (ini.morto || !ini.sangra) continue;
    ini.sangra.t -= dt;
    ini.vida -= ini.sangra.dps * dt;
    if (ini.vida <= 0) matarInimigo(ini);
    if (ini.sangra.t <= 0) ini.sangra = null;
  }
  // chão em chamas
  for (const f of areasDeFogo) {
    f.t += dt;
    for (const ini of inimigosVivos()) if (Math.hypot(ini.x - f.x, ini.y - f.y) < f.raio + ini.tipo.raio) {
      ini.vida -= f.dps * dt; ini.estado = 'perseguindo';
      if (ini.vida <= 0) matarInimigo(ini);
    }
    if (Math.random() < 0.5 && typeof emitir === 'function')
      emitir(1, () => ({ tipo: 'luz', x: f.x + acaso(-f.raio, f.raio) * 0.7, y: f.y + acaso(-f.raio, f.raio) * 0.7, z: 0.1,
                         vx: 0, vy: 0, vz: acaso(0.8, 1.6), vida: 0, dur: acaso(0.4, 0.8), cor: '255, 140, 50', tam: acaso(1, 2) }));
  }
  areasDeFogo = areasDeFogo.filter((f) => f.t < f.dur);
  // giro: acerta todos em volta a cada intervalo
  const g = jogador.giro;
  if (g) {
    g.restante -= dt; g.prox -= dt;
    jogador.angulo += dt * 14;
    if (g.prox <= 0) {
      g.prox = g.intervalo;
      const alcance = g.stats.alcance / METROS_POR_TILE + jogador.raio;
      let acertou = false;
      for (const ini of inimigosVivos())
        if (Math.hypot(ini.x - jogador.x, ini.y - jogador.y) <= alcance + ini.tipo.raio) { ferirInimigo(ini, g.stats); acertou = true; }
      if (acertou) desgasteAoAcertar();
    }
    if (g.restante <= 0) jogador.giro = null;
  }
  // investida: corre em linha reta até bater, chegar perto de um inimigo ou acabar a distância
  const v = jogador.investida;
  if (v) {
    const passo = Math.min(v.restante, v.vel * dt);
    const nx = jogador.x + v.dx * passo, ny = jogador.y + v.dy * passo;
    const parede = colide(nx, ny, jogador.raio) || colideComNpc(nx, ny, jogador.raio);
    const inimigoPerto = v.golpe && inimigosVivos().some((i) => Math.hypot(i.x - nx, i.y - ny) < i.tipo.raio + jogador.raio + 0.25);
    if (!parede && !colideComInimigo(nx, ny, jogador.raio)) { jogador.x = nx; jogador.y = ny; }
    v.restante -= passo;
    if (parede || inimigoPerto || v.restante <= 0 || colideComInimigo(nx, ny, jogador.raio)) {
      jogador.investida = null;
      if (v.golpe) {
        poeiraNosPes(jogador.x, jogador.y, 10, 1.8);
        tremerTela(0.15, 3);
        const s = v.stats;
        ataque = { t: s.tempo * MOMENTO_IMPACTO, total: s.tempo, angulo: Math.atan2(v.dy, v.dx), stats: s, aplicado: false, especial: true };
      }
    }
  }
  for (const f of efeitosVisuais) f.t += dt;
  efeitosVisuais = efeitosVisuais.filter((f) => f.t < f.dur);
}

// Virote incendiário: onde ele para, o chão pega fogo
const _atualizarProjeteisOrigHab = atualizarProjeteis;
atualizarProjeteis = function (dt) {
  const antes = projeteis.filter((p) => p.stats && p.stats.incendio);
  _atualizarProjeteisOrigHab(dt);
  for (const p of antes) if (!projeteis.includes(p)) {
    const f = p.stats.incendio;
    areasDeFogo.push({ x: p.x, y: p.y, raio: f.raio, dps: f.dps, t: 0, dur: f.dur });
  }
};

// Cobrir: o companheiro perto de Tomás leva menos dano
const _ferirCompanheiroOrigHab = ferirCompanheiro;
ferirCompanheiro = function (dano) {
  if (bonus.cobrirPct && companheiro && Math.hypot(companheiro.x - jogador.x, companheiro.y - jogador.y) < 3) dano *= 1 - bonus.cobrirPct / 100;
  return _ferirCompanheiroOrigHab(dano);
};

// --- Desenho no chão (dentro do zoom) ---
function desenharEfeitosDeHabilidade() {
  const anel = (x, y, raio, cor, alfa, largura = 3) => {
    const p = mundoParaTela(x, y);
    ctx.beginPath();
    ctx.ellipse(p.x + camera.x, p.y + camera.y, meiaLargPx(raio * 4), meiaLargPx(raio * 4) / 2, 0, 0, Math.PI * 2);
    ctx.strokeStyle = `rgba(${cor}, ${alfa})`;
    ctx.lineWidth = largura; ctx.stroke(); ctx.lineWidth = 1;
  };
  for (const f of efeitosVisuais) if (f.t >= 0) anel(f.x, f.y, f.raio * Math.min(1, f.t / f.dur * 1.6), f.cor, 0.8 * (1 - f.t / f.dur), 4);
  for (const f of areasDeFogo) {
    const p = mundoParaTela(f.x, f.y);
    const fade = Math.min(1, (f.dur - f.t) / 0.6);
    ctx.beginPath();
    ctx.ellipse(p.x + camera.x, p.y + camera.y, meiaLargPx(f.raio * 4), meiaLargPx(f.raio * 4) / 2, 0, 0, Math.PI * 2);
    ctx.fillStyle = `rgba(255, 120, 40, ${0.22 * fade + 0.06 * Math.sin(performance.now() / 90)})`; ctx.fill();
  }
  if (jogador.giro) {
    const r = jogador.giro.stats.alcance / METROS_POR_TILE + jogador.raio;
    anel(jogador.x, jogador.y, r, '240, 190, 60', 0.45, 5);
  }
  if (jogador.aparando > 0) anel(jogador.x, jogador.y, 0.5, '255, 233, 168', 0.8, 3);
  for (const p of jogador.posturas || []) {
    const cor = p.cor === '#d8705a' ? '216, 112, 90' : p.cor === '#8fbf6a' ? '143, 191, 106' : p.cor === '#c9a24a' ? '201, 162, 74' : '127, 166, 239';
    anel(jogador.x, jogador.y, 0.55, cor, 0.35 + 0.35 * Math.min(1, p.restante), 3);
  }
}

// --- Jogo salvo antigo (maestria e as árvores por caminho): devolve os pontos ---
const VERSAO_HABILIDADES = 2;
function migrarHabilidades() {
  if (!jogador.atalhos) jogador.atalhos = [null, null, null];
  if (jogador.versaoHabilidades === VERSAO_HABILIDADES) return;
  const secundarias = MISSOES.filter((m) => m.tipo === 'Secundária' && flags['pontoSec_' + m.id]).length;
  jogador.habilidades = {};
  jogador.atalhos = [null, null, null];
  jogador.posturas = [];
  jogador.pontosHabilidade = Math.max(0, (jogador.nivel || 1) - 1) + secundarias;
  if (jogador.estilo) darPrimeiroPonto();
  jogador.versaoHabilidades = VERSAO_HABILIDADES;
  recalcularAtributos();
}

// --- Itens com +1 em habilidades -------------------------------------------
// Sufixos "+1 nas habilidades de <árvore>" nas armas da árvore (e nos escudos,
// para a do escudo) e em anéis e colares; nas peças raras, às vezes "+1 ou +2"
// numa habilidade só. Alguns lendários também trazem.
const NOMES_SUFIXO_ARVORE = {
  espada: 'do Mestre de Esgrima', impacto: 'do Quebra-Escudos', lanca: 'do Lanceiro',
  machado: 'do Varegue', besta: 'do Besteiro', escudo: 'do Escudeiro'
};
for (const a of ARVORES_ARMA) {
  const bases = a.escudo ? ESCUDOS : a.armas;
  AFIXOS.push({ m: NOMES_SUFIXO_ARVORE[a.id], f: NOMES_SUFIXO_ARVORE[a.id], tipo: 'sufixo', efeito: 'arv_' + a.id, min: 1, max: 1, chance: 0.3,
                so: [...bases, ...(typeof JOIAS !== 'undefined' ? JOIAS : [])] });
  TEXTO_EFEITO['arv_' + a.id] = (v) => `+${v} nas habilidades de ${a.nome.toLowerCase()}`;
}
for (const [id, info] of Object.entries(INDICE_HABILIDADES)) TEXTO_EFEITO['hab_' + id] = (v) => `+${v} em ${info.h.nome}`;

// Peça rara: 15% de chance de +1 ou +2 numa habilidade (da árvore da arma ou do escudo; joia: qualquer árvore)
const _criarItemOrigHab = criarItem;
criarItem = function (base, raridade) {
  const item = _criarItemOrigHab(base, raridade);
  if (raridade === 'raro' && Math.random() < 0.15) {
    const arv = BASES_ESCUDOS[item.base] ? 'escudo' : arvoreDaArma(item)
              || (BASES_EQUIP[item.base] && ['anel', 'colar'].includes(BASES_EQUIP[item.base].cat) ? escolherUm(ARVORES_ARMA).id : null);
    if (arv) {
      const h = escolherUm(HABILIDADES[arv]);
      const v = Math.random() < 0.3 ? 2 : 1;
      item.afixos.push({ efeito: 'hab_' + h.id, valor: v });
      item.efeitos['hab_' + h.id] = (item.efeitos['hab_' + h.id] || 0) + v;
    }
  }
  return item;
};

// Lendários com +habilidades
const _maisHab = { 'Juramento de Ibelin': { arv_espada: 1 }, 'Lança de São Jorge': { arv_lanca: 1 }, 'Machado de Haroldo': { arv_machado: 1 },
                   'Besta do Genovês': { hab_tiroMirado: 2 }, 'Escudo do Castelão de Gaza': { arv_escudo: 1 },
                   'Anel do Patriarca': { hab_aparar: 1 }, 'Manoplas do Ferreiro de Acre': { hab_pancada: 1 } };
for (const l of LENDARIOS) if (_maisHab[l.nome]) Object.assign(l.efeitos, _maisHab[l.nome]);

;
// ===== js/painel_tomas.js =====
// =====================================================================
// PAINEL DO TOMÁS: atributos, habilidades e virtudes (tecla T)
// =====================================================================
// Como as janelas de personagem e de habilidades do Diablo 2, juntas numa
// só, com três abas. No celular, abre pelo botão "Tomás" na barra de cima.

let painelTomasAberto = false;
let abaTomas = 'atributos';
let habilidadeMarcada = null;
let areasTomas = [];

function abrirPainelTomas(aba) {
  painelTomasAberto = true;
  if (aba) abaTomas = aba;
  diarioAberto = false; cronicaAberta = false;
  if (typeof atlasAberto !== 'undefined' && atlasAberto) fecharAtlas();
}

window.addEventListener('keydown', (e) => {
  if (dialogo || menuOratorio) return;
  const t = e.key.toLowerCase();
  if (t === 't') painelTomasAberto ? (painelTomasAberto = false) : abrirPainelTomas();
  else if (t === 'escape' && painelTomasAberto) painelTomasAberto = false;
});

function cliqueNoPainelTomas() {
  if (!painelTomasAberto) return false;
  const a = areasTomas.find(dentroDe);
  if (a) a.acao();
  return true;   // com o painel aberto, nenhum clique vai para o mundo
}

// --- Desenho ---
function botaoTomas(x, y, w, h, texto, ativo, acao, cor = '#e8b931') {
  const r = { x, y, w, h, acao };
  if (acao) areasTomas.push(r);
  const sob = acao && dentroDe(r);
  ctx.fillStyle = !acao ? 'rgba(255,255,255,0.03)' : ativo ? 'rgba(232, 185, 49, 0.2)' : sob ? 'rgba(255,255,255,0.08)' : 'rgba(255,255,255,0.04)';
  ctx.fillRect(x, y, w, h);
  ctx.strokeStyle = !acao ? '#3d362c' : ativo ? cor : '#5c5040';
  ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
  ctx.font = (ativo ? 'bold ' : '') + '14px Alegreya, Georgia, serif';
  ctx.fillStyle = !acao ? '#6b6356' : ativo || sob ? '#ffe9a8' : '#d9cfbb';
  ctx.textAlign = 'center';
  ctx.fillText(texto, x + w / 2, y + h / 2 + 5);
  ctx.textAlign = 'left';
}

function escreverLinhas(texto, x, y, largura, fonte, cor, altura = 18, limite = Infinity) {
  ctx.font = fonte; ctx.fillStyle = cor;
  for (const l of linhasDeTexto(texto, largura)) { if (y > limite) break; ctx.fillText(l, x, y); y += altura; }
  return y;
}

function desenharPainelTomas() {
  areasTomas = [];
  if (!painelTomasAberto) return;
  const toque = typeof MODO !== 'undefined' && MODO.toque;
  const w = Math.min(880, canvas.width - (toque ? 16 : 32));
  const hud = alturaHud();
  const h = toque ? canvas.height - 16 : Math.min(580, canvas.height - 100 - hud);
  const x = (canvas.width - w) / 2, y = toque ? 8 : Math.max(16, (canvas.height - hud - h) / 2 - 20);
  ctx.fillStyle = 'rgb(16, 13, 10)';
  ctx.fillRect(x, y, w, h);
  ctx.strokeStyle = '#c9a25a'; ctx.lineWidth = 2;
  ctx.strokeRect(x + 1, y + 1, w - 2, h - 2);
  ctx.lineWidth = 1;

  // Cabeçalho: nome, nível e caminho
  const caminho = caminhoDoJogador();
  ctx.font = 'bold 19px Alegreya, Georgia, serif'; ctx.fillStyle = '#e8b931';
  ctx.fillText(`Tomás de Ramla · nível ${jogador.nivel}`, x + 20, y + 30);
  ctx.font = '13px Alegreya, Georgia, serif'; ctx.fillStyle = '#a39a86';
  const nomeCaminho = caminho ? (CAMINHOS.find((c) => c.id === caminho) || {}).nome : 'sem caminho';
  ctx.fillText(nomeCaminho || '', x + 20, y + 48);

  // Abas
  const abas = [['atributos', 'Atributos', jogador.pontosAtributo], ['habilidades', 'Habilidades', jogador.pontosHabilidade], ['virtudes', 'Virtudes', jogador.pontosHabilidade]];
  let ax = x + Math.max(250, w - 3 * 128 - 56);
  for (const [id, nome, pts] of abas) {
    botaoTomas(ax, y + 14, 120, 30, pts ? `${nome} (${pts})` : nome, abaTomas === id, () => { abaTomas = id; });
    ax += 128;
  }
  const fechar = { x: x + w - 38, y: y + 14, w: 28, h: 28, acao: () => { painelTomasAberto = false; } };
  areasTomas.push(fechar);
  ctx.font = 'bold 18px monospace'; ctx.fillStyle = dentroDe(fechar) ? '#ffe9a8' : '#8f846c';
  ctx.fillText('×', fechar.x + 8, fechar.y + 20);

  const area = { x: x + 20, y: y + 62, w: w - 40, h: h - 74 };
  ctx.strokeStyle = '#3d362c';
  ctx.beginPath(); ctx.moveTo(x + 12, area.y - 6); ctx.lineTo(x + w - 12, area.y - 6); ctx.stroke();
  if (abaTomas === 'atributos') desenharAbaAtributos(area);
  else if (abaTomas === 'habilidades') desenharAbaHabilidades(area);
  else desenharAbaVirtudes(area);
}

function desenharAbaAtributos(a) {
  const col = Math.min(400, a.w / 2 - 10);
  let y = a.y + 18;
  // Experiência
  const fim = jogador.nivel >= NIVEL_MAXIMO;
  ctx.font = '13px Alegreya, Georgia, serif'; ctx.fillStyle = '#a39a86';
  ctx.fillText(fim ? 'Nível máximo' : `Experiência ${jogador.xp} · próximo nível em ${xpTotalAte(jogador.nivel + 1)}`, a.x, y);
  y += 8;
  ctx.fillStyle = 'rgba(255,255,255,0.07)'; ctx.fillRect(a.x, y, col, 8);
  ctx.fillStyle = '#7a64c0'; ctx.fillRect(a.x, y, col * fracaoDoNivel(), 8);
  y += 30;
  ctx.font = 'bold 15px Alegreya, Georgia, serif';
  ctx.fillStyle = jogador.pontosAtributo ? '#ffe58a' : '#8f846c';
  ctx.fillText(jogador.pontosAtributo ? `Pontos para distribuir: ${jogador.pontosAtributo}` : 'Nenhum ponto para distribuir', a.x, y);
  y += 14;
  const linhaH = Math.max(42, Math.min(60, (a.y + a.h - y - 8) / 4));
  for (const at of ATRIBUTOS) {
    const valor = jogador.atributos[at.id];
    ctx.fillStyle = 'rgba(255,255,255,0.04)'; ctx.fillRect(a.x, y, col, linhaH - 6);
    ctx.font = 'bold 15px Alegreya, Georgia, serif'; ctx.fillStyle = '#efe7d6';
    ctx.fillText(at.nome, a.x + 12, y + 20);
    ctx.font = 'bold 18px Alegreya, Georgia, serif'; ctx.fillStyle = '#e8b931';
    ctx.textAlign = 'right'; ctx.fillText(String(valor), a.x + col - 52, y + 22); ctx.textAlign = 'left';
    if (linhaH >= 50) { ctx.font = '12px Alegreya, Georgia, serif'; ctx.fillStyle = '#8f846c'; ctx.fillText(at.texto, a.x + 12, y + 38); }
    botaoTomas(a.x + col - 40, y + 6, 32, linhaH - 18, '+', false, jogador.pontosAtributo ? () => gastarPontoDeAtributo(at.id) : null);
    y += linhaH;
  }

  // Coluna da direita: números finais
  const x2 = a.x + col + 30, w2 = a.w - col - 30;
  let y2 = a.y + 18;
  const arma = armaAtiva();
  const s = arma ? statsDaArma(arma) : null;
  const linhas = [
    ['Vida', `${Math.ceil(jogador.vida)} / ${jogador.vidaMax}`],
    ['Devoção', `${Math.floor(jogador.devocao)} / ${jogador.devocaoMax}`],
    ['Defesa', `${defesaTotal()} (reduz ${Math.round(reducaoPorDefesa() * 100)}% do dano)`],
    ['Bloqueio', `${Math.round(bloqueioTotal() * 100)}%`],
    ['Resistências', `fogo ${resistenciaDe('fogo')}% · veneno ${resistenciaDe('veneno')}%`],
    ['Recupera vida', `${(0.6 + (bonus.regenVida || 0)).toFixed(1)} por segundo`],
    ['Corrida', `${Math.round(jogador.velocidade / VELOCIDADE_BASE * 100)}%`]
  ];
  if (s) linhas.push(
    ['Arma', arma.nome],
    ['Dano', `${s.dano[0]} a ${s.dano[1]}${s.sagrado[1] ? ` + sagrado ${s.sagrado[0]} a ${s.sagrado[1]}` : ''}`],
    ['Golpe', `${s.tempo.toFixed(2)} s (${velocidadeDoGolpe(s.tempo)})`],
    ['Crítico', `${Math.round(s.critico)}%`]
  );
  const v = virtudeAtiva();
  linhas.push(['Virtude', v ? `${v.nome}: ${v.desc(v.ef(nivelDaVirtude(v)))}` : 'nenhuma (aba Virtudes)']);
  const lh = Math.max(20, Math.min(26, (a.y + a.h - y2) / (linhas.length + 0.5)));
  for (const [k, val] of linhas) {
    ctx.font = '13px Alegreya, Georgia, serif'; ctx.fillStyle = '#8f846c'; ctx.fillText(k, x2, y2);
    ctx.font = '14px Alegreya, Georgia, serif'; ctx.fillStyle = k === 'Dano' && s && s.sagrado[1] ? COR_SAGRADO : '#efe7d6';
    const valT = T(val); let t = valT;
    while (ctx.measureText(t).width > w2 - 110 && t.length > 6) t = t.slice(0, -2);
    ctx.fillText(t === valT ? t : t + '…', x2 + 110, y2);
    y2 += lh;
  }
}

let arvoreTomas = null;   // a árvore aberta na aba Habilidades

function desenharAbaHabilidades(a) {
  const caminho = caminhoDoJogador();
  if (!caminho) {
    escreverLinhas('Escolha o seu posto com o capitão da guarda, no Portão de Gaza, para abrir as habilidades.', a.x, a.y + 30, a.w, 'italic 15px Alegreya, Georgia, serif', '#8f846c');
    return;
  }
  const naMao = arvoreDaArma(armaAtiva());
  if (!arvoreTomas) arvoreTomas = naMao || arvoreDoCaminho();
  ctx.font = 'bold 15px Alegreya, Georgia, serif';
  ctx.fillStyle = jogador.pontosHabilidade ? '#ffe58a' : '#8f846c';
  ctx.fillText(jogador.pontosHabilidade ? `Pontos de habilidade: ${jogador.pontosHabilidade}` : 'Nenhum ponto de habilidade', a.x, a.y + 16);
  ctx.font = '12.5px Alegreya, Georgia, serif'; ctx.fillStyle = '#8f846c'; ctx.textAlign = 'right';
  ctx.fillText('1 por nível e 1 por missão secundária', a.x + a.w, a.y + 16); ctx.textAlign = 'left';

  // Abas das seis árvores
  const nAbas = ARVORES_ARMA.length;
  const tabY = a.y + 26, tabH = 30, tabW = (a.w - (nAbas - 1) * 5) / nAbas;
  ARVORES_ARMA.forEach((arv, i) => {
    const n = pontosNaArvore(arv.id);
    const tx = a.x + i * (tabW + 5);
    const rot = `${T(arv.curto || arv.nome)}${n ? ` (${n})` : ''}`;
    botaoTomas(tx, tabY, tabW, tabH, '', arvoreTomas === arv.id, () => { arvoreTomas = arv.id; habilidadeMarcada = null; }, arv.cor);
    let t = rot; ctx.font = (arvoreTomas === arv.id ? 'bold ' : '') + (tabW < 90 ? '12px' : '13px') + ' Alegreya, Georgia, serif';
    while (ctx.measureText(t).width > tabW - 10 && t.length > 4) t = t.slice(0, -2);
    ctx.fillStyle = arvoreTomas === arv.id ? '#ffe9a8' : arvoreValeAgora(arv.id) ? arv.cor : '#a39a86';
    ctx.textAlign = 'center'; ctx.fillText(t === rot ? t : t + '…', tx + tabW / 2, tabY + 20); ctx.textAlign = 'left';
  });
  const arv = ARVORES_ARMA.find((t) => t.id === arvoreTomas);
  const vale = arvoreValeAgora(arv.id);
  const lista = HABILIDADES[arv.id];
  const n = pontosNaArvore(arv.id);
  ctx.font = '12.5px Alegreya, Georgia, serif'; ctx.fillStyle = vale ? arv.cor : '#8f846c';
  const quem = arv.escudo ? 'com escudo no braço' : `com ${arv.nome.toLowerCase()} na mão`;
  if (arv.livre) ctx.fillText(`${T(arv.nome)}: ${arv.ideia}. Vale com qualquer arma. ${n} pontos.`, a.x, tabY + tabH + 17);
  else ctx.fillText(`${T(arv.nome)}: ${arv.ideia}. Vale ${quem}${vale ? ' (agora)' : ''}. ${n} pontos${arv.escudo ? '' : `: +${n * PROFICIENCIA.danoPct}% de dano e golpes ${s1(-n * PROFICIENCIA.tempoPct)}% mais rápidos`}.`, a.x, tabY + tabH + 17);

  // Cinco fileiras
  const detalheH = Math.min(124, Math.max(92, a.h * 0.27));
  const topo = tabY + tabH + 26, altGrade = a.y + a.h - detalheH - 8 - topo;
  const filH = Math.max(28, Math.min(60, (altGrade - 4 * 6) / 5));
  const rotW = Math.min(118, a.w * 0.16);
  const colW = (a.w - rotW - 10) / 2;
  for (let fil = 0; fil < 5; fil++) {
    const fy = topo + fil * (filH + 6);
    const aberta = jogador.nivel >= NIVEL_DA_FILEIRA[fil] && n >= PONTOS_NA_ARVORE[fil];
    ctx.font = 'bold 12.5px Alegreya, Georgia, serif'; ctx.fillStyle = aberta ? '#c9a24a' : '#5c554a';
    ctx.fillText(`Nível ${NIVEL_DA_FILEIRA[fil]}`, a.x, fy + (filH >= 44 ? 20 : filH / 2 + 4));
    if (filH >= 44 && PONTOS_NA_ARVORE[fil]) { ctx.font = '11.5px Alegreya, Georgia, serif'; ctx.fillText(`${PONTOS_NA_ARVORE[fil]} pts na árvore`, a.x, fy + 36); }
    lista.filter((h) => h.fil === fil).forEach((h, k) => {
      const cx = a.x + rotW + 10 + k * colW;
      const w = colW - 8;
      const r = pontosEm(h.id), max = maximoDe(h), extra = extraDosItens(h.id);
      const caixa = { x: cx, y: fy, w, h: filH, acao: () => { habilidadeMarcada = h.id; } };
      areasTomas.push(caixa);
      const marcada = habilidadeMarcada === h.id;
      ctx.fillStyle = marcada ? 'rgba(232, 185, 49, 0.16)' : dentroDe(caixa) ? 'rgba(255,255,255,0.07)' : 'rgba(255,255,255,0.035)';
      ctx.fillRect(cx, fy, w, filH);
      ctx.strokeStyle = marcada ? '#e8b931' : r ? arv.cor : '#3d362c';
      ctx.strokeRect(cx + 0.5, fy + 0.5, w - 1, filH - 1);
      const ic = Math.min(44, filH - 8);
      desenharIconeHabilidade(h.id, cx + 5, fy + (filH - ic) / 2, ic, !(r || extra));
      const tx = cx + ic + 12;
      ctx.font = 'bold 14px Alegreya, Georgia, serif';
      ctx.fillStyle = !aberta && !r ? '#5c554a' : r ? '#efe7d6' : '#b9ad94';
      const nomeT = T(h.nome); let nome = nomeT;
      while (ctx.measureText(nome).width > w - 96 - ic && nome.length > 4) nome = nome.slice(0, -2);
      ctx.fillText(nome === nomeT ? nome : nome + '…', tx, fy + (filH >= 44 ? 20 : filH / 2 + 5));
      ctx.font = 'bold 13px monospace'; ctx.fillStyle = r ? '#e8b931' : '#6b6356'; ctx.textAlign = 'right';
      ctx.fillText(`${r}/${max}`, cx + w - 10, fy + (filH >= 44 ? 20 : filH / 2 + 5));
      if (extra) { const wr = ctx.measureText(`${r}/${max}`).width; ctx.fillStyle = '#7fa6ef'; ctx.fillText(`+${extra}`, cx + w - 14 - wr, fy + (filH >= 44 ? 20 : filH / 2 + 5)); }
      ctx.textAlign = 'left';
      const atalho = jogador.atalhos.indexOf(h.id);
      if (jogador.atalhoDireito === h.id && (r || extra)) {
        ctx.font = 'bold 12px monospace'; ctx.fillStyle = '#9fd0ff'; ctx.textAlign = 'right';
        ctx.fillText('[Dir]', cx + w - (filH >= 44 ? (atalho >= 0 ? 44 : 10) : 82), fy + (filH >= 44 ? filH - 8 : filH / 2 + 5)); ctx.textAlign = 'left';
      }
      if (atalho >= 0 && (r || extra)) {
        ctx.font = 'bold 12px monospace'; ctx.fillStyle = '#ffe58a'; ctx.textAlign = 'right';
        ctx.fillText(`[${'FGH'[atalho]}]`, cx + w - (filH >= 44 ? 10 : 46), fy + (filH >= 44 ? filH - 8 : filH / 2 + 5)); ctx.textAlign = 'left';
      }
      if (filH >= 44) {
        ctx.font = '12px Alegreya, Georgia, serif'; ctx.fillStyle = '#8f846c';
        ctx.fillText(h.tipo === 'ativa' ? `Ativa · ${h.custo} de devoção` : 'Passiva', tx, fy + 38);
      }
    });
  }

  // Detalhes da marcada
  const dy = a.y + a.h - detalheH;
  ctx.fillStyle = 'rgba(255,255,255,0.04)'; ctx.fillRect(a.x, dy, a.w, detalheH);
  const id = habilidadeMarcada && INDICE_HABILIDADES[habilidadeMarcada]?.arvore === arv.id ? habilidadeMarcada : null;
  if (!id) {
    escreverLinhas('Toque numa habilidade para ver o que ela faz. As ativas vão nos atalhos F, G e H.', a.x + 12, dy + 26, a.w - 24, 'italic 14px Alegreya, Georgia, serif', '#8f846c');
    return;
  }
  const h = INDICE_HABILIDADES[id].h, r = pontosEm(id), max = maximoDe(h), extra = extraDosItens(id), ef = r + extra;
  const btnW = 150;
  desenharIconeHabilidade(id, a.x + 10, dy + 10, 52, !ef);
  ctx.font = 'bold 15px Alegreya, Georgia, serif'; ctx.fillStyle = '#e8b931';
  ctx.fillText(h.nome, a.x + 72, dy + 22);
  let ty = dy + 42;
  const larg = a.w - btnW - 96;
  if (ef) ty = escreverLinhas(`Agora (${extra ? `${r} + ${extra} dos itens` : r}): ${h.desc(h.ef(ef))}`, a.x + 72, ty, larg, '13.5px Alegreya, Georgia, serif', '#efe7d6', 17, dy + detalheH - 6);
  if (r < max) ty = escreverLinhas(`${ef ? 'Próximo' : 'Com 1 ponto'}: ${h.desc(h.ef(ef + 1))}`, a.x + 72, ty, larg, '13.5px Alegreya, Georgia, serif', r ? '#a39a86' : '#efe7d6', 17, dy + detalheH - 6);
  const motivo = motivoParaNaoAprender(id);
  const bx = a.x + a.w - btnW - 10;
  botaoTomas(bx, dy + 10, btnW, 30, r >= max ? 'No máximo' : '+1 ponto', false, motivo ? null : () => aprenderHabilidade(id));
  if (motivo && r < max) escreverLinhas(motivo, bx, dy + 56, btnW, '12px Alegreya, Georgia, serif', '#c98a6a', 15);
  if (h.tipo === 'ativa' && ef) {
    const bw = (btnW - 12) / 4;
    const direito = jogador.atalhoDireito === id;
    if (!MODO.toque) botaoTomas(bx + 3 * (bw + 4), dy + detalheH - 40, bw, 30, 'Dir.', direito, direito ? () => { jogador.atalhoDireito = null; } : () => { jogador.atalhoDireito = id; });
    ['F', 'G', 'H'].forEach((t, k) => {
      const esta = jogador.atalhos[k] === id;
      botaoTomas(bx + k * (bw + 4), dy + detalheH - 40, bw, 30, t, esta, esta ? null : () => {
        const antes = jogador.atalhos.indexOf(id);
        if (antes >= 0) jogador.atalhos[antes] = jogador.atalhos[k];   // troca de lugar
        jogador.atalhos[k] = id;
      });
    });
  }
}

let virtudeMarcada = null;
function desenharAbaVirtudes(a) {
  ctx.font = 'bold 15px Alegreya, Georgia, serif';
  ctx.fillStyle = jogador.pontosHabilidade ? '#ffe58a' : '#8f846c';
  ctx.fillText(jogador.pontosHabilidade ? `Pontos de habilidade: ${jogador.pontosHabilidade}` : 'Nenhum ponto de habilidade', a.x, a.y + 16);
  escreverLinhas('Uma virtude ativa de cada vez, sem gastar devoção; cresce com os pontos. As que curam valem também para quem luta ao lado. V troca para a próxima.',
                 a.x, a.y + 36, a.w, '12.5px Alegreya, Georgia, serif', '#a39a86', 16);
  const detalheH = Math.min(118, Math.max(90, a.h * 0.26));
  const topo = a.y + 70, colW = (a.w - 3 * 10) / 4;
  const linhaH = Math.max(30, Math.min(70, (a.y + a.h - detalheH - 12 - topo - 26) / 3 - 10));
  CAMINHOS_VIRTUDE.forEach((c, i) => {
    const cx = a.x + i * (colW + 10);
    ctx.font = 'bold 14px Alegreya, Georgia, serif'; ctx.fillStyle = `rgb(${c.cor})`;
    ctx.textAlign = 'center'; ctx.fillText(T(c.nome), cx + colW / 2, topo + 14); ctx.textAlign = 'left';
    VIRTUDES.filter((v) => v.caminho === c.id).forEach((v) => {
      const y = topo + 24 + v.degrau * (linhaH + 10);
      const r = pontosEm(v.id), extra = extraDosItens(v.id), ativa = jogador.virtude === v.id && virtudeLiberada(v);
      const pode = !motivoParaNaoAprender(v.id);
      const caixa = { x: cx, y, w: colW, h: linhaH, acao: () => { virtudeMarcada = v.id; } };
      areasTomas.push(caixa);
      if (v.degrau > 0) { ctx.strokeStyle = r ? `rgba(${c.cor}, 0.6)` : '#3d362c'; ctx.beginPath(); ctx.moveTo(cx + colW / 2, y - 10); ctx.lineTo(cx + colW / 2, y); ctx.stroke(); }
      ctx.fillStyle = ativa ? `rgba(${c.cor}, 0.18)` : virtudeMarcada === v.id ? 'rgba(232, 185, 49, 0.12)' : dentroDe(caixa) ? 'rgba(255,255,255,0.07)' : 'rgba(255,255,255,0.035)';
      ctx.fillRect(cx, y, colW, linhaH);
      ctx.strokeStyle = ativa ? `rgb(${c.cor})` : virtudeMarcada === v.id ? '#e8b931' : r ? `rgba(${c.cor}, 0.6)` : '#3d362c';
      ctx.lineWidth = ativa ? 2 : 1; ctx.strokeRect(cx + 0.5, y + 0.5, colW - 1, linhaH - 1); ctx.lineWidth = 1;
      if (typeof desenharIconeHabilidade === 'function') desenharIconeHabilidade(v.id, cx + 6, y + (linhaH - Math.min(40, linhaH - 8)) / 2, Math.min(40, linhaH - 8), !(r || extra));
      const tx = cx + (typeof desenharIconeHabilidade === 'function' ? Math.min(40, linhaH - 8) + 12 : 10);
      ctx.font = 'bold 14px Alegreya, Georgia, serif'; ctx.fillStyle = r || extra ? '#efe7d6' : pode ? '#b9ad94' : '#5c554a';
      ctx.fillText(T(v.nome), tx, y + (linhaH >= 46 ? 20 : linhaH / 2 + 5));
      ctx.font = 'bold 12px monospace'; ctx.fillStyle = r ? '#e8b931' : '#6b6356'; ctx.textAlign = 'right';
      ctx.fillText(`${r}/5`, cx + colW - 8, y + (linhaH >= 46 ? 20 : linhaH / 2 + 5));
      if (extra) { const wr = ctx.measureText(`${r}/5`).width; ctx.fillStyle = '#7fa6ef'; ctx.fillText(`+${extra}`, cx + colW - 12 - wr, y + (linhaH >= 46 ? 20 : linhaH / 2 + 5)); }
      ctx.textAlign = 'left';
      if (linhaH >= 46) { ctx.font = '11.5px Alegreya, Georgia, serif'; ctx.fillStyle = ativa ? `rgb(${c.cor})` : '#8f846c';
        ctx.fillText(ativa ? 'ATIVA' : `Nível ${NIVEL_DO_DEGRAU[v.degrau]}`, tx, y + 38); }
    });
  });
  // detalhe
  const dy = a.y + a.h - detalheH;
  ctx.fillStyle = 'rgba(255,255,255,0.04)'; ctx.fillRect(a.x, dy, a.w, detalheH);
  const v = VIRTUDES.find((x) => x.id === virtudeMarcada);
  if (!v) { escreverLinhas('Toque numa virtude para ver o que ela faz.', a.x + 12, dy + 26, a.w - 24, 'italic 14px Alegreya, Georgia, serif', '#8f846c'); return; }
  const r = pontosEm(v.id), ef = nivelDaVirtude(v), btnW = 150, bx = a.x + a.w - btnW - 10;
  ctx.font = 'bold 15px Alegreya, Georgia, serif'; ctx.fillStyle = `rgb(${v.cor})`;
  ctx.fillText(`${T(v.nome)} · ${T(v.texto)}`, a.x + 12, dy + 22);
  let ty = dy + 42; const larg = a.w - btnW - 36;
  if (ef) ty = escreverLinhas(`Agora (${ef}): ${v.desc(v.ef(ef))}`, a.x + 12, ty, larg, '13.5px Alegreya, Georgia, serif', '#efe7d6', 17, dy + detalheH - 6);
  if (r < 5) ty = escreverLinhas(`${ef ? 'Próximo' : 'Com 1 ponto'}: ${v.desc(v.ef(ef + 1))}`, a.x + 12, ty, larg, '13.5px Alegreya, Georgia, serif', ef ? '#a39a86' : '#efe7d6', 17, dy + detalheH - 6);
  const motivo = motivoParaNaoAprender(v.id);
  botaoTomas(bx, dy + 10, btnW, 30, r >= 5 ? 'No máximo' : '+1 ponto', false, motivo ? null : () => aprenderHabilidade(v.id));
  if (motivo && r < 5) escreverLinhas(motivo, bx, dy + 50, btnW, '12px Alegreya, Georgia, serif', '#c98a6a', 15);
  if (ef) {
    const ativa = jogador.virtude === v.id;
    botaoTomas(bx, dy + detalheH - 40, btnW, 30, ativa ? 'Desligar' : 'Usar esta', ativa, () => escolherVirtude(v.id));
  }
}

;
// ===== js/atlas.js =====
// =====================================================================
// ATLAS: o mapa da região, como numa página de atlas antigo
// =====================================================================
// Tecla M (ou o botão Mapa no celular) abre. Mostra os lugares do jogo na
// posição real (Ascalão, Ibelin, Ramla, Lida...) e os lugares inventados perto
// deles (as dunas, a torre, o acampamento, a caverna). As missões em andamento
// aparecem como selos de cera no lugar do passo atual: não diz o ponto exato,
// só para onde ir. Lugares já visitados ficam em tinta forte.
//
// As posições vêm de latitude e longitude (as cidades reais); os lugares
// inventados estão onde a história os põe.

let atlasAberto = false;

// --- Projeção: longitude/latitude -> pontos do desenho (1000 x 860) ---
const ATLAS_LON = [34.38, 35.30], ATLAS_LAT = [32.12, 31.45];
function atlasXY(lat, lon) {
  return [(lon - ATLAS_LON[0]) / (ATLAS_LON[1] - ATLAS_LON[0]) * 1000,
          (lat - ATLAS_LAT[0]) / (ATLAS_LAT[1] - ATLAS_LAT[0]) * 860];
}

// Lugares do jogo. tipo: cidade, castelo, acampamento, ruina, caverna, campo
// dx/dy/ancora: onde fica o nome em relação ao símbolo
const LUGARES_ATLAS = {
  ascalao:     { nome: 'Ascalão', lat: 31.668, lon: 34.566, tipo: 'cidade', dx: 16, dy: -10, ancora: 'start', tam: 1.25,
                 legado: () => true },
  dunas:       { nome: 'Dunas da Costa', lat: 31.628, lon: 34.552, tipo: 'campo', dx: 14, dy: 16, ancora: 'start', legado: () => flags.foiAsDunas },
  torre:       { nome: 'Torre da costa', lat: 31.606, lon: 34.512, tipo: 'ruina', dx: -12, dy: 18, ancora: 'end', legado: () => flags.foiATorre },
  acampamento: { nome: 'Acampamento do sultão', lat: 31.640, lon: 34.640, tipo: 'acampamento', dx: 14, dy: 5, ancora: 'start',
                 legado: () => flags.entrouAcampamento },
  ibelin:      { nome: 'Ibelin', lat: 31.877, lon: 34.739, tipo: 'castelo', dx: -14, dy: 5, ancora: 'end', tam: 1.15, legado: () => flags.foiAIbelin },
  planicie:    { nome: 'Planície costeira', lat: 31.900, lon: 34.800, tipo: 'campo', dx: -6, dy: 24, ancora: 'middle', legado: () => flags.foiARamla },
  caverna:     { nome: 'Caverna nas colinas', lat: 31.968, lon: 34.800, tipo: 'caverna', dx: 0, dy: -16, ancora: 'middle', legado: () => flags.foiACaverna },
  ramla:       { nome: 'Ramla', lat: 31.928, lon: 34.866, tipo: 'cidade', dx: -12, dy: -12, ancora: 'end', tam: 1.1, legado: () => flags.foiARamla },
  lida:        { nome: 'Lida', lat: 31.952, lon: 34.893, tipo: 'cidade', dx: 14, dy: -6, ancora: 'start', legado: () => flags.foiALida },
  montgisard:  { nome: 'Montgisard', lat: 31.859, lon: 34.922, tipo: 'campo', dx: 14, dy: 16, ancora: 'start', futuro: 'Ato III' }
};
// Mapas de dentro ficam no lugar de fora
const LUGAR_DO_MAPA = { cisternas: 'ascalao', catedral: 'ascalao', poroes: 'lida' };
const lugarDoMapa = (nome) => LUGAR_DO_MAPA[nome] || nome;

// Onde fica cada passo de cada missão (o lugar, não o ponto exato)
const LOCAIS_DAS_MISSOES = {
  servir: ['ascalao'],
  oratorio: ['ascalao', 'ascalao'],
  estrada: ['dunas', 'dunas', 'ascalao'],
  refugiados: ['dunas', 'ascalao'],
  rei: ['ascalao'],
  templarios: ['dunas', 'ascalao'],
  acampamento: ['acampamento', 'acampamento', 'ascalao'],
  fogueiras: ['ascalao', 'ascalao', 'ascalao', 'ascalao'],
  torre: ['ascalao', 'torre', 'torre', 'ascalao'],
  ibelin: ['ascalao', 'ibelin'],
  cinzas: ['ramla', 'ramla', 'ramla'],
  poroesLida: ['lida', 'lida', 'lida', 'lida', 'ibelin'],
  carrocas: ['planicie', 'ibelin'],
  desertores: ['caverna', 'caverna', 'caverna', 'ibelin']
};

// Lugares de referência (não se visita): só nome no mapa
const REFERENCIAS_ATLAS = [
  { nome: 'Gaza', lat: 31.505, lon: 34.462 },
  { nome: 'Jafa', lat: 32.052, lon: 34.752 },
  { nome: 'Jerusalém', lat: 31.778, lon: 35.232, grande: true },
  { nome: 'Belém', lat: 31.705, lon: 35.205 },
  { nome: 'Blanchegarde', lat: 31.700, lon: 34.848 }
];

// Linha da costa, do sul para o norte (aproximada)
const COSTA_ATLAS = [[30.60, 33.80], [31.20, 34.20], [31.43, 34.36], [31.48, 34.41], [31.53, 34.45], [31.58, 34.495], [31.62, 34.53], [31.66, 34.555],
  [31.70, 34.575], [31.75, 34.605], [31.80, 34.635], [31.85, 34.665], [31.90, 34.695], [31.95, 34.715], [32.00, 34.735],
  [32.05, 34.745], [32.10, 34.76], [32.13, 34.77], [32.60, 34.86], [33.20, 34.95]];

// Estradas da época (aproximadas): a da costa, a de Ramla e a de Jerusalém
const ESTRADAS_ATLAS = [
  [[31.505, 34.462], [31.585, 34.525], [31.668, 34.566], [31.76, 34.64], [31.877, 34.739], [31.97, 34.745], [32.052, 34.752]],
  [[31.877, 34.739], [31.900, 34.800], [31.928, 34.866], [31.952, 34.893]],
  [[31.928, 34.866], [31.88, 34.93], [31.84, 35.00], [31.81, 35.10], [31.778, 35.232]],
  [[31.668, 34.566], [31.70, 34.70], [31.700, 34.848], [31.74, 35.00], [31.778, 35.232]]
];
// O rio Sorek, que desce das montanhas e chega ao mar perto de Ibelin
const RIO_ATLAS = [[31.935, 34.700], [31.92, 34.74], [31.88, 34.79], [31.85, 34.86], [31.82, 34.93], [31.79, 35.00], [31.77, 35.08]];

const lugarConhecido = (id) => !!(flags['visitou_' + id] || LUGARES_ATLAS[id].legado?.());

// Chamado a cada quadro: marca o lugar atual como visitado
function marcarLugarVisitado() {
  const id = lugarDoMapa(nomeDoMapaAtual());
  if (LUGARES_ATLAS[id] && !flags['visitou_' + id]) flags['visitou_' + id] = true;
}

// Missões em andamento e o lugar do passo atual
function missoesNoAtlas() {
  const r = [];
  for (const m of MISSOES) {
    const s = situacao(m);
    if (s.estado !== 'ativa') continue;
    const lugar = (LOCAIS_DAS_MISSOES[m.id] || [])[s.passo];
    if (lugar) r.push({ m, lugar, texto: m.passos[s.passo].texto });
  }
  return r;
}

// --- Desenho (SVG) ---
const pontosSvg = (lista) => lista.map(([la, lo]) => atlasXY(la, lo).map((v) => v.toFixed(1)).join(',')).join(' ');
const esc = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;');

function simboloDoLugar(tipo, x, y, k, tinta) {
  const t = (s) => `<g transform="translate(${x.toFixed(1)},${y.toFixed(1)}) scale(${k})" fill="none" stroke="${tinta}" stroke-width="1.6" stroke-linejoin="round">${s}</g>`;
  switch (tipo) {
    case 'cidade':   // muralha com duas torres
      return t(`<path d="M-11,6 V-4 H-7 V-8 H-3 V-4 H3 V-8 H7 V-4 H11 V6 Z" fill="rgba(140,36,24,0.18)"/><path d="M-2,6 V1 a2,2 0 0 1 4,0 V6"/>`);
    case 'castelo':  // torre de menagem
      return t(`<path d="M-8,7 V-3 H-6 V-6 H-3 V-3 H-1 V-6 H1 V-3 H3 V-6 H6 V-3 H8 V7 Z" fill="rgba(140,36,24,0.18)"/><path d="M-1.5,7 V3 h3 V7"/>`);
    case 'acampamento': // tendas
      return t(`<path d="M-11,6 L-5,-5 L1,6 Z M-1,6 L5,-7 L11,6 Z" fill="rgba(140,36,24,0.18)"/><path d="M5,-7 V-11 l4,1.5 -4,1.5"/>`);
    case 'ruina':
      return t(`<path d="M-6,7 V-6 H-3 V-3 H0 V-8 H3 V-1 L6,2 V7 Z" fill="rgba(90,70,40,0.18)"/>`);
    case 'caverna':
      return t(`<path d="M-11,6 Q-6,-9 0,-9 Q6,-9 11,6 Z" fill="rgba(90,70,40,0.2)"/><path d="M-4,6 Q-4,-1 0,-1 Q4,-1 4,6" fill="${tinta}" fill-opacity="0.6"/>`);
    default:          // campo aberto: um X de batalha/encontro
      return t(`<circle r="3.2" fill="${tinta}" fill-opacity="0.75" stroke="none"/><circle r="7" stroke-dasharray="2 2.4"/>`);
  }
}

function montanhas(lat0, lat1, lon0, lon1, n, semente, tam = 1) {
  let s = semente, out = '';
  const rnd = () => { s = (s * 16807) % 2147483647; return s / 2147483647; };
  for (let i = 0; i < n; i++) {
    const [x, y] = atlasXY(lat0 + (lat1 - lat0) * rnd(), lon0 + (lon1 - lon0) * rnd());
    const w = (9 + rnd() * 7) * tam, h = (7 + rnd() * 6) * tam;
    out += `<path d="M${(x - w).toFixed(1)},${y.toFixed(1)} L${x.toFixed(1)},${(y - h).toFixed(1)} L${(x + w).toFixed(1)},${y.toFixed(1)}" />`
         + `<path d="M${x.toFixed(1)},${(y - h).toFixed(1)} L${(x + w * 0.45).toFixed(1)},${y.toFixed(1)}" stroke-opacity="0.35" stroke-width="3"/>`;
  }
  return out;
}

function desenharAtlas() {
  const svg = document.getElementById('atlasSvg');
  const aqui = lugarDoMapa(nomeDoMapaAtual());
  const ativas = missoesNoAtlas();
  const TINTA = '#3a2a14', VERMELHO = '#8c2418';

  // costa e mar
  const costa = pontosSvg(COSTA_ATLAS);
  const [cx0, cy0] = atlasXY(COSTA_ATLAS[0][0], COSTA_ATLAS[0][1]);
  const [cx1, cy1] = atlasXY(COSTA_ATLAS[COSTA_ATLAS.length - 1][0], COSTA_ATLAS[COSTA_ATLAS.length - 1][1]);
  const mar = `M-1000,${cy1.toFixed(1)} L${costa.split(' ').reverse().join(' L')} L-1000,${cy0.toFixed(1)} Z`;
  // linhas de água paralelas à costa (como nos atlas gravados)
  let ondas = '';
  for (let k = 1; k <= 7; k++) {
    const d = COSTA_ATLAS.map(([la, lo]) => atlasXY(la, lo - k * 0.011)).map(([x, y]) => `${x.toFixed(1)},${y.toFixed(1)}`).join(' ');
    ondas += `<polyline points="${d}" fill="none" stroke="#4d6a72" stroke-width="${(1.1 - k * 0.1).toFixed(2)}" stroke-opacity="${(0.55 - k * 0.06).toFixed(2)}"/>`;
  }

  let lugares = '';
  for (const [id, L] of Object.entries(LUGARES_ATLAS)) {
    const [x, y] = atlasXY(L.lat, L.lon);
    const conhecido = lugarConhecido(id);
    const tinta = L.futuro ? '#8a7650' : conhecido ? TINTA : '#8a7650';
    const k = L.tam || 1;
    lugares += `<g class="lugar" data-id="${id}"${L.futuro ? ' opacity="0.65"' : ''}><title>${esc(L.nome)}${L.futuro ? ' (' + L.futuro + ')' : conhecido ? '' : ' (ainda não visitado)'}</title>`
      + simboloDoLugar(L.tipo, x, y, k, tinta)
      + `<text x="${(x + L.dx).toFixed(1)}" y="${(y + L.dy).toFixed(1)}" text-anchor="${L.ancora}" fill="${tinta}" `
      + `font-family="Alegreya, Georgia, serif" font-size="${(id === 'ascalao' || id === 'ibelin' || id === 'ramla' ? 21 : 17)}" `
      + `font-style="${conhecido && !L.futuro ? 'normal' : 'italic'}" font-weight="${conhecido && !L.futuro ? 600 : 400}" `
      + `paint-order="stroke" stroke="#e6d6b0" stroke-width="4" stroke-linejoin="round">${esc(L.nome)}${L.futuro ? ` · ${L.futuro}` : ''}</text></g>`;
  }
  let refs = '';
  for (const r of REFERENCIAS_ATLAS) {
    const [x, y] = atlasXY(r.lat, r.lon);
    refs += `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="${r.grande ? 5 : 3}" fill="#6b5532"/>`
      + `<text x="${(x + 9).toFixed(1)}" y="${(y + 5).toFixed(1)}" fill="#6b5532" font-family="Alegreya, Georgia, serif" `
      + `font-size="${r.grande ? 19 : 15}" font-style="italic" paint-order="stroke" stroke="#e6d6b0" stroke-width="3">${esc(r.nome)}</text>`;
  }

  // selos das missões (agrupados por lugar, lado a lado)
  let selos = '';
  const porLugar = {};
  ativas.forEach((a, i) => { (porLugar[a.lugar] ||= []).push(i); });
  for (const [lugar, idx] of Object.entries(porLugar)) {
    const L = LUGARES_ATLAS[lugar];
    const [x, y] = atlasXY(L.lat, L.lon);
    idx.forEach((i, j) => {
      const sx = x - 18 - j * 24, sy = y - 26;
      const sec = ativas[i].m.tipo !== 'Principal';
      selos += `<g class="selo" data-i="${i}" transform="translate(${sx.toFixed(1)},${sy.toFixed(1)})">`
        + `<circle r="11.5" fill="${sec ? '#3d5a7a' : VERMELHO}" stroke="#2a0d08" stroke-opacity="0.5"/>`
        + `<circle r="8.5" fill="none" stroke="#f4e2c0" stroke-opacity="0.45" stroke-dasharray="1.5 1.8"/>`
        + `<text y="4.5" text-anchor="middle" fill="#f4e2c0" font-family="Georgia, serif" font-weight="bold" font-size="13">${i + 1}</text>`
        + `<title>${esc(ativas[i].m.nome)}</title></g>`;
    });
  }

  // "você está aqui"
  let voce = '';
  if (LUGARES_ATLAS[aqui]) {
    const [x, y] = atlasXY(LUGARES_ATLAS[aqui].lat, LUGARES_ATLAS[aqui].lon);
    voce = `<g transform="translate(${x.toFixed(1)},${(y + 1).toFixed(1)})" pointer-events="none">`
      + `<circle r="16" fill="none" stroke="#b8892a" stroke-width="2.5"><animate attributeName="r" values="12;22;12" dur="2.2s" repeatCount="indefinite"/>`
      + `<animate attributeName="stroke-opacity" values="0.9;0.1;0.9" dur="2.2s" repeatCount="indefinite"/></circle></g>`;
  }

  // rosa dos ventos e escala
  const rosa = `<g transform="translate(905,770)" fill="${TINTA}" stroke="${TINTA}" stroke-width="1">
      <circle r="38" fill="none" stroke-opacity="0.6"/><circle r="30" fill="none" stroke-opacity="0.35"/>
      <path d="M0,-46 L6,-6 L0,0 Z"/><path d="M0,-46 L-6,-6 L0,0 Z" fill="#e6d6b0"/>
      <path d="M0,46 L6,6 L0,0 Z" fill="#e6d6b0"/><path d="M0,46 L-6,6 L0,0 Z"/>
      <path d="M46,0 L6,6 L0,0 Z" fill="#e6d6b0"/><path d="M46,0 L6,-6 L0,0 Z"/>
      <path d="M-46,0 L-6,6 L0,0 Z"/><path d="M-46,0 L-6,-6 L0,0 Z" fill="#e6d6b0"/>
      <text y="-52" text-anchor="middle" stroke="none" font-family="'Alegreya SC', Georgia, serif" font-size="15">N</text></g>`;
  const pxKm = 1000 / ((ATLAS_LON[1] - ATLAS_LON[0]) * 94.5);
  const escala = `<g transform="translate(40,812)" fill="${TINTA}" font-family="Alegreya, Georgia, serif" font-size="14">
      <rect width="${(5 * pxKm).toFixed(1)}" height="6" fill="${TINTA}"/><rect x="${(5 * pxKm).toFixed(1)}" width="${(5 * pxKm).toFixed(1)}" height="6" fill="none" stroke="${TINTA}"/>
      <text y="22">0</text><text x="${(10 * pxKm).toFixed(1)}" y="22" text-anchor="middle">10 km · duas léguas</text></g>`;

  svg.innerHTML = `
    <defs>
      <filter id="papel" x="0" y="0" width="100%" height="100%">
        <feTurbulence type="fractalNoise" baseFrequency="0.9" numOctaves="2" seed="7" result="r"/>
        <feColorMatrix in="r" type="matrix" values="0 0 0 0 0.35  0 0 0 0 0.25  0 0 0 0 0.12  0 0 0 0.16 0"/>
      </filter>
      <radialGradient id="manchas" cx="50%" cy="45%" r="75%">
        <stop offset="60%" stop-color="#7a5a2a" stop-opacity="0"/><stop offset="100%" stop-color="#5a3c18" stop-opacity="0.45"/>
      </radialGradient>
    </defs>
    <rect x="-1000" y="-1000" width="3000" height="2860" fill="#e3d2aa"/>
    <path d="${mar}" fill="#b7c2ae"/>
    ${ondas}
    <polyline points="${costa}" fill="none" stroke="${TINTA}" stroke-width="2.2"/>
    <text x="150" y="330" fill="#3f5a60" font-family="'Alegreya SC', Georgia, serif" font-size="26" letter-spacing="6" transform="rotate(-62 150 330)" text-anchor="middle">MARE MAGNUM</text>
    <g stroke="#6b5532" stroke-width="1.4" fill="none" stroke-linecap="round">${montanhas(31.55, 32.05, 35.02, 35.28, 70, 11, 1.1)}${montanhas(31.62, 32.0, 34.88, 35.0, 22, 29, 0.75)}</g>
    <text x="${atlasXY(31.93, 35.15)[0].toFixed(0)}" y="${atlasXY(31.93, 35.15)[1].toFixed(0)}" fill="#6b5532" font-family="Alegreya, Georgia, serif" font-style="italic" font-size="17" text-anchor="middle" paint-order="stroke" stroke="#e3d2aa" stroke-width="4">Montes da Judeia</text>
    <polyline points="${pontosSvg(RIO_ATLAS)}" fill="none" stroke="#4d6a72" stroke-width="2" stroke-opacity="0.75"/>
    <g fill="none" stroke="#7a5a2a" stroke-width="1.8" stroke-dasharray="6 5" stroke-opacity="0.8">${ESTRADAS_ATLAS.map((e) => `<polyline points="${pontosSvg(e)}"/>`).join('')}</g>
    ${refs}
    ${lugares}
    ${voce}
    ${selos}
    ${rosa}
    ${escala}
    <g transform="translate(700,40)">
      <rect width="270" height="78" fill="#e9dbb8" stroke="${TINTA}" stroke-width="1.5"/>
      <rect x="5" y="5" width="260" height="68" fill="none" stroke="${TINTA}" stroke-width="0.8"/>
      <text x="135" y="36" text-anchor="middle" fill="${VERMELHO}" font-family="'Pirata One', Georgia, serif" font-size="30" letter-spacing="3">TERRA SANCTA</text>
      <text x="135" y="60" text-anchor="middle" fill="${TINTA}" font-family="Alegreya, Georgia, serif" font-style="italic" font-size="16">de Ascalão a Lida · Anno Domini 1177</text>
    </g>
    <rect x="-300" y="-200" width="1600" height="1260" fill="url(#manchas)" pointer-events="none"/>
    ${MODO.toque ? '' : '<rect x="-300" y="-200" width="1600" height="1260" filter="url(#papel)" pointer-events="none"/>'}`;

  // lista ao lado
  const L = LUGARES_ATLAS[aqui];
  document.getElementById('atlasAqui').textContent = `Você está em: ${mapaAtual.nome}${L && L.nome !== mapaAtual.nome ? ` (${L.nome})` : ''}`;
  const lista = document.getElementById('atlasLista');
  lista.innerHTML = ativas.length ? '' : '<li class="vazio">Nenhuma missão em andamento.</li>';
  ativas.forEach((a, i) => {
    const li = document.createElement('li');
    const b = document.createElement('button');
    b.innerHTML = `<span class="selo${a.m.tipo !== 'Principal' ? ' sec' : ''}">${i + 1}</span><span><strong>${esc(a.m.nome)}</strong>`
      + `<small>${esc(LUGARES_ATLAS[a.lugar].nome)}${a.lugar === aqui ? ' · aqui' : ''}</small></span>`;
    b.title = a.texto;
    b.addEventListener('click', () => destacarSelo(i, b));
    li.appendChild(b); lista.appendChild(li);
  });
}

function destacarSelo(i, botao) {
  for (const b of document.querySelectorAll('#atlasLista button')) b.classList.toggle('ativo', b === botao);
  for (const g of document.querySelectorAll('#atlasSvg .selo')) {
    const c = g.querySelector('circle');
    if (Number(g.dataset.i) === i) c.setAttribute('stroke', '#ffe9a8'), c.setAttribute('stroke-width', '4'), c.setAttribute('stroke-opacity', '1');
    else c.setAttribute('stroke', '#2a0d08'), c.setAttribute('stroke-width', '1'), c.setAttribute('stroke-opacity', '0.5');
  }
}

function abrirAtlas() {
  if (dialogo || transicao) return;
  atlasAberto = true;
  diarioAberto = false; cronicaAberta = false;
  desenharAtlas();
  document.getElementById('atlas').hidden = false;
}
function fecharAtlas() {
  atlasAberto = false;
  document.getElementById('atlas').hidden = true;
}

(function prepararAtlas() {
  document.querySelector('#atlas .fechar').addEventListener('click', fecharAtlas);
  // clicar fora da folha fecha
  document.getElementById('atlas').addEventListener('click', (e) => { if (e.target.id === 'atlas') fecharAtlas(); });
  window.addEventListener('keydown', (e) => {
    if (dialogo || menuOratorio) return;
    const t = e.key.toLowerCase();
    if (t === 'm') atlasAberto ? fecharAtlas() : abrirAtlas();
    else if (t === 'escape' && atlasAberto) fecharAtlas();
  });
})();

