function atualizarAto3() {
  if (flags.qutlughMorto && !avisouFuga) {
    avisouFuga = true;
    if (!flags.saladinoFugiu) {
      flags.saladinoFugiu = true;
      avisar('Saladino foge num camelo de corrida! O exército do sultão se desfaz.');
    }
  }
}

