// ===== js/caminho.js =====
// =====================================================================
// CAMINHO: a escolha de quem Tomás vai ser, antes do jogo começar
// =====================================================================
// Num jogo novo, depois de escolher computador ou celular, aparece a tela
// "Que homem Tomás vai ser?" com os quatro estilos de combate. Cada carta
// mostra o Tomás como ele pode estar no fim da campanha, com o melhor
// equipamento do estilo (retratos renderizados por ferramentas/retratos.py).
//
// A escolha fica em flags.caminho (vai junto no jogo salvo). Na Cena 2, o
// capitão só oferece o posto do caminho escolhido.

const CAMINHOS = [
  { id: 'besta', nome: 'Besteiro', arma: 'Besta',
    desc: 'Mata de longe, atrás das ameias. O virote atravessa o campo, mas a recarga é lenta e ele sofre quando cercado.',
    fim: 'Capuz de couro, cota de malha e uma besta de Gênova.',
    barras: { Alcance: 5, Velocidade: 1, Dano: 4, Defesa: 1 } },
  { id: 'lanca', nome: 'Lanceiro', arma: 'Lança e escudo',
    desc: 'Segura o inimigo na ponta da lança. Estocada estreita e longa, com o escudo no outro braço.',
    fim: 'Capelo de malha, cota, escudo de amêndoa e lança longa.',
    barras: { Alcance: 3, Velocidade: 3, Dano: 3, Defesa: 3 } },
  { id: 'duasmaos', nome: 'Homem de machado', arma: 'Machado dinamarquês',
    desc: 'Golpes largos que acertam vários de uma vez e fazem o inimigo cambalear. Sem escudo: a defesa é bater primeiro.',
    fim: 'Elmo de nasal, cota de malha e o machado de duas mãos.',
    barras: { Alcance: 2, Velocidade: 2, Dano: 5, Defesa: 1 } },
  { id: 'espada', nome: 'Espada e escudo', arma: 'Espada e escudo',
    desc: 'Ao lado dos cavaleiros. Golpes rápidos e o escudo segura boa parte do que vem de frente. Especial: empurrão de escudo.',
    fim: 'Elmo de nasal, malha da cabeça aos pés, espada e escudo.',
    barras: { Alcance: 1, Velocidade: 4, Dano: 2, Defesa: 5 } }
];

let caminhoMarcado = null;

// Há um jogo salvo? (então o caminho já foi escolhido, ou o jogo é anterior a esta tela)
function temJogoSalvo() {
  try { return !!localStorage.getItem(CHAVE_SALVO); } catch (e) { return false; }
}

function mostrarEscolhaDoCaminho(depois) {
  const tela = document.getElementById('caminho');
  const cartas = document.getElementById('cartasCaminho');
  const botao = document.getElementById('btnComecar');
  cartas.innerHTML = '';
  for (const c of CAMINHOS) {
    const b = document.createElement('button');
    b.className = 'carta';
    b.dataset.id = c.id;
    b.innerHTML = `
      <div class="retrato"><img src="assets/tela/caminho_${c.id}.webp" alt="Tomás como ${c.nome.toLowerCase()} no fim da campanha"><span class="fim">No fim da campanha</span></div>
      <h3>${c.nome}</h3>
      <p class="arma">${c.arma}</p>
      <p class="desc">${c.desc}</p>
      <div class="barras">${Object.entries(c.barras).map(([k, v]) =>
        `<span>${k}</span><span class="barra"><i style="width:${v * 20}%"></i></span>`).join('')}</div>`;
    b.title = c.fim;
    b.addEventListener('click', () => {
      caminhoMarcado = c.id;
      for (const x of cartas.children) x.classList.toggle('escolhida', x === b);
      botao.disabled = false;
      botao.textContent = `Começar como ${c.nome.toLowerCase()}`;
    });
    cartas.appendChild(b);
  }
  botao.onclick = () => {
    if (!caminhoMarcado) return;
    flags.caminho = caminhoMarcado;
    tela.hidden = true;
    depois();
  };
  tela.hidden = false;
}

;
// ===== js/abertura.js =====
// =====================================================================
// ABERTURA: uma página da Crônica antes de entrar no jogo
// =====================================================================
// Para o jogador se situar: no jogo novo, a primeira página ("Um reino com
// poucos cavaleiros"); ao continuar, a página mais recente que ele já tem e
// o que está fazendo agora (a missão principal em andamento).
// Arte: Ascalão ao entardecer, tirada do próprio cenário (assets/tela/abertura.webp).
// O texto rola sozinho (rolagem do navegador), também no celular.

let aberturaAberta = false;

function passoAtualDaHistoria() {
  const ativas = MISSOES.filter((m) => situacao(m).estado === 'ativa');
  const m = ativas.find((x) => x.tipo === 'Principal') || ativas[0];
  if (!m) return null;
  return { nome: m.nome, texto: m.passos[situacao(m).passo].texto };
}

function mostrarAbertura(novo) {
  const pagina = novo ? PAGINAS_CRONICA[0] : (paginasLiberadas().slice(-1)[0] || PAGINAS_CRONICA[0]);
  const tela = document.getElementById('abertura');
  document.getElementById('aberturaTitulo').textContent = pagina.titulo;
  document.getElementById('aberturaData').textContent = pagina.data;
  const texto = document.getElementById('aberturaTexto');
  texto.innerHTML = '';
  const par = (t, classe) => { const p = document.createElement('p'); if (classe) p.className = classe; p.textContent = t; texto.appendChild(p); return p; };
  for (const t of pagina.texto) par(t);
  if (pagina.tomas) par(pagina.tomas, 'tomas');
  if (novo) {
    par('Você é Tomás, filho de um ferreiro de Ramla. Sem título e sem terra, veio a Ascalão servir ao rei.', 'tomas');
  } else {
    const agora = passoAtualDaHistoria();
    if (agora) {
      const p = par('', 'agora');
      const b = document.createElement('b'); b.textContent = 'Agora · ' + agora.nome;
      p.appendChild(b); p.appendChild(document.createTextNode(agora.texto));
    }
  }
  par('Fonte: ' + pagina.fonte, 'fonte');
  texto.scrollTop = 0;
  const botao = document.getElementById('aberturaSeguir');
  botao.textContent = novo ? 'Começar' : 'Continuar';
  tela.hidden = false;
  tela.classList.remove('saindo');
  aberturaAberta = true;
  setTimeout(() => botao.focus(), 50);
}

function fecharAbertura() {
  const tela = document.getElementById('abertura');
  if (tela.hidden) return;
  tela.classList.add('saindo');
  aberturaAberta = false;
  setTimeout(() => { tela.hidden = true; tela.classList.remove('saindo'); }, 600);
}

document.getElementById('aberturaSeguir').addEventListener('click', fecharAbertura);
window.addEventListener('keydown', (e) => {
  if (aberturaAberta && (e.key === 'Enter' || e.key === 'Escape')) { e.preventDefault(); e.stopImmediatePropagation(); fecharAbertura(); }
}, true);

;
// ===== js/toque.js =====
// =====================================================================
// TOQUE: tela inicial (computador ou celular) e controles de toque
// =====================================================================
// No celular:
//   - joystick no canto esquerdo para andar (como as teclas W A S D);
//   - tocar na tela funciona como o clique do mouse: andar até o ponto,
//     falar com alguém, atacar um inimigo, pegar um item; segurar o dedo
//     no chão faz o Tomás seguir o dedo;
//   - com o equipamento ou a loja aberta, segurar o dedo num item é o
//     botão direito do mouse (usar, equipar, vender);
//   - dois dedos fazem zoom;
//   - botões à direita: Atacar, Especial, Falar, Trocar arma, Rezar, e
//     em cima Equipamento, Missões, Mapa, Crônica e Voltar;
//   - com uma janela aberta (missões, mapa, equipamento, loja, Crônica,
//     conversa), o joystick e os botões de ação somem para não cobrir nada.
// Por baixo, o toque vira os mesmos eventos de mouse e teclado do
// computador, então o resto do jogo não precisa saber de onde veio.

const MODO = { toque: false };

// --- Tela inicial ---------------------------------------------------------
function escolherModo(toque, admin = false, paraLica = false) {
  MODO.toque = toque;
  document.getElementById('inicio').style.display = 'none';
  document.body.classList.add('jogando');
  // Direto para a Liça (como o Crucible): sem abertura, o menu das séries já aberto (js/lica.js)
  if (paraLica && !admin && typeof abrirLicaDaTelaInicial === 'function') setTimeout(abrirLicaDaTelaInicial, 350);
  // Jogo novo: primeiro a escolha do caminho (js/caminho.js); o admin já vem com o caminho
  const novo = !temJogoSalvo() && !flags.caminho && !flags.cena2;
  if (!admin && novo) mostrarEscolhaDoCaminho(() => {});
  // Antes de tudo, uma página da Crônica para situar o jogador (js/abertura.js)
  if (!admin && !paraLica) mostrarAbertura(novo);
  if (toque) {
    document.body.classList.add('modo-toque');
    // telas pequenas: um pouco menos de zoom para ver mais do mapa
    zoom = Math.max(1.1, Math.min(2, Math.min(window.innerWidth, window.innerHeight) / 340));
    try { document.documentElement.requestFullscreen?.().then(() => screen.orientation?.lock?.('landscape').catch(() => {})).catch(() => {}); } catch (e) {}
  }
  setTimeout(ajustarTamanho, 300);
}

(function prepararInicio() {
  const temToque = 'ontouchstart' in window || navigator.maxTouchPoints > 0;
  // Sugere a versão do aparelho, mas a pessoa escolhe
  document.getElementById(temToque ? 'btnToque' : 'btnPc').classList.add('sugerido');
  // Personagens salvos (js/personagens.js): escolher qual jogar, ou começar um novo
  const salvos = listarPersonagens();
  let escolhido = salvos.some((p) => p.n === VAGA_CARREGADA) ? VAGA_CARREGADA : salvos.length ? salvos[0].n : 'novo';
  let modoLica = false;
  const lista = document.getElementById('listaPersonagens');
  const marcarModo = (lica) => {
    modoLica = lica && escolhido !== 'novo';
    const bc = document.getElementById('btnCampanha'), bl = document.getElementById('btnLica');
    bc.classList.toggle('ativo', !modoLica); bl.classList.toggle('ativo', modoLica);
    bc.setAttribute('aria-checked', String(!modoLica)); bl.setAttribute('aria-checked', String(modoLica));
    bl.setAttribute('aria-disabled', String(escolhido === 'novo'));
  };
  const montarLista = () => {
    lista.innerHTML = '';
    const linha = (rotulo, info, n, classe) => {
      const l = document.createElement('div'); l.className = 'linha';
      const b = document.createElement('button');
      b.className = 'pers' + (classe ? ' ' + classe : '') + (escolhido === n ? ' ativo' : '');
      b.setAttribute('role', 'radio'); b.setAttribute('aria-checked', String(escolhido === n));
      b.innerHTML = `<strong>${rotulo}</strong><span class="info">${info}</span>`;
      b.addEventListener('click', () => { escolhido = n; montarLista(); marcarModo(modoLica); });
      l.appendChild(b);
      if (n !== 'novo') {
        const x = document.createElement('button'); x.className = 'apagar'; x.textContent = 'apagar'; x.title = 'Apagar este personagem';
        x.addEventListener('click', (e) => {
          e.stopPropagation();
          if (!x.classList.contains('confirmar')) { x.classList.add('confirmar'); x.textContent = 'apagar?'; return; }
          apagarVaga(n);
          const i = salvos.findIndex((p) => p.n === n); if (i >= 0) salvos.splice(i, 1);
          if (escolhido === n) escolhido = salvos.length ? salvos[0].n : 'novo';
          if (!salvos.length) document.getElementById('modoJogo').hidden = true;
          montarLista(); marcarModo(modoLica);
        });
        l.appendChild(x);
      }
      lista.appendChild(l);
    };
    for (const p of salvos) linha(nomeDoPersonagem(p.dados), descreverJogoSalvo(p.dados), p.n);
    if (vagaLivre() !== null) linha('+ Novo personagem', 'começar do zero, num jogo salvo à parte', 'novo', 'novo');
  };
  if (salvos.length) {
    document.getElementById('personagens').hidden = false;
    document.getElementById('inicio').classList.add('com-personagens');
    document.getElementById('modoJogo').hidden = false;
    montarLista();
    document.getElementById('btnCampanha').addEventListener('click', () => marcarModo(false));
    document.getElementById('btnLica').addEventListener('click', () => marcarModo(true));
    marcarModo(false);
  }
  // Novo personagem ou outro personagem: grava a vaga, recarrega a página e já entra
  const jogar = (toque) => {
    if (escolhido === 'novo') {
      const n = vagaLivre();
      if (n === null) return;
      escolherVaga(n);
      if (n === VAGA_CARREGADA && !salvos.length) { escolherModo(toque); return; }   // nenhum salvo: segue como sempre
      try { sessionStorage.setItem('montgisard_novo', toque ? 'toque' : 'pc'); } catch (e) {}
      location.reload();
      return;
    }
    if (escolhido !== VAGA_CARREGADA) {
      escolherVaga(escolhido);
      try { sessionStorage.setItem('montgisard_entrar', JSON.stringify({ toque, lica: modoLica })); } catch (e) {}
      location.reload();
      return;
    }
    escolherModo(toque, false, modoLica);
  };
  document.getElementById('btnPc').addEventListener('click', () => jogar(false));
  document.getElementById('btnToque').addEventListener('click', () => jogar(true));
  // Voltando de um "Novo personagem" (escolha do caminho) ou de uma troca de personagem
  let pendente = null, entrar = null;
  try {
    pendente = sessionStorage.getItem('montgisard_novo'); sessionStorage.removeItem('montgisard_novo');
    entrar = JSON.parse(sessionStorage.getItem('montgisard_entrar') || 'null'); sessionStorage.removeItem('montgisard_entrar');
  } catch (e) {}
  if (pendente) setTimeout(() => escolherModo(pendente === 'toque'), 0);
  else if (entrar) setTimeout(() => escolherModo(!!entrar.toque, false, !!entrar.lica), 0);
  // Painéis de controles e créditos
  const painel = (id) => document.getElementById(id);
  document.getElementById('btnControles').addEventListener('click', () => { painel('painelControles').hidden = false; });
  document.getElementById('btnCreditos').addEventListener('click', () => { painel('painelCreditos').hidden = false; });
  for (const b of document.querySelectorAll('#inicio .fechar')) b.addEventListener('click', () => { b.closest('.painel').hidden = true; });
})();

// --- Eventos falsos de mouse e teclado ---------------------------------------
function mouseFalso(tipo, x, y, botao = 0) {
  const alvo = tipo === 'mouseup' ? window : canvas;
  alvo.dispatchEvent(new MouseEvent(tipo, { clientX: x, clientY: y, button: botao, bubbles: true }));
}
function teclaFalsa(key) {
  window.dispatchEvent(new KeyboardEvent('keydown', { key, bubbles: true }));
  window.dispatchEvent(new KeyboardEvent('keyup', { key, bubbles: true }));
}

// --- Joystick ------------------------------------------------------------
const joy = { ativo: false, id: null, cx: 0, cy: 0, x: 0, y: 0 };
const RAIO_JOY = 50;

// Lido pelo jogador a cada quadro: direção na tela (-1 a 1) ou null
function joystickAtivo() {
  if (!joy.ativo || Math.hypot(joy.x, joy.y) < 0.2) return null;
  return { x: joy.x, y: joy.y };
}

function moverJoy(t) {
  let dx = t.clientX - joy.cx, dy = t.clientY - joy.cy;
  const d = Math.hypot(dx, dy);
  if (d > RAIO_JOY) { dx *= RAIO_JOY / d; dy *= RAIO_JOY / d; }
  joy.x = dx / RAIO_JOY; joy.y = dy / RAIO_JOY;
  document.getElementById('joyPino').style.transform = `translate(${dx}px, ${dy}px)`;
}

(function prepararJoystick() {
  const base = document.getElementById('joy');
  base.addEventListener('touchstart', (e) => {
    e.preventDefault();
    const t = e.changedTouches[0];
    const r = base.getBoundingClientRect();
    joy.ativo = true; joy.id = t.identifier; joy.cx = r.left + r.width / 2; joy.cy = r.top + r.height / 2;
    moverJoy(t);
  }, { passive: false });
  base.addEventListener('touchmove', (e) => {
    e.preventDefault();
    for (const t of e.changedTouches) if (t.identifier === joy.id) moverJoy(t);
  }, { passive: false });
  const soltar = (e) => {
    for (const t of e.changedTouches) if (t.identifier === joy.id) {
      joy.ativo = false; joy.x = joy.y = 0;
      document.getElementById('joyPino').style.transform = '';
    }
  };
  base.addEventListener('touchend', soltar);
  base.addEventListener('touchcancel', soltar);
})();

// --- Botões de ação --------------------------------------------------------
// O inimigo vivo mais perto (para Atacar e Especial mirarem sozinhos)
function inimigoMaisPerto(max = 9) {
  let melhor = null, dMin = max;
  for (const ini of inimigosVivos()) {
    if (!explorado(ini.x, ini.y)) continue;   // na névoa
    const d = Math.hypot(ini.x - jogador.x, ini.y - jogador.y);
    if (d < dMin) { dMin = d; melhor = ini; }
  }
  return melhor;
}

function botaoAtacar() {
  if (dialogo || transicao || diarioAberto || cronicaAberta) return;
  const alvo = inimigoMaisPerto();
  if (alvo) { limparAlvos(); alvoInimigo = alvo; }   // chega perto e golpeia até ele cair
  else atacar(jogador.angulo);
}
function botaoEspecial(k = 0) {
  if (dialogo || transicao) return;
  const alvo = inimigoMaisPerto();
  atacarEspecial(alvo ? Math.atan2(alvo.y - jogador.y, alvo.x - jogador.x) : jogador.angulo, k);
}

const ACOES_TOQUE = {
  atacar: botaoAtacar,
  especial: () => botaoEspecial(0),
  especialG: () => botaoEspecial(1),
  especialH: () => botaoEspecial(2),
  falar: () => teclaFalsa('e'),
  virtude: () => teclaFalsa('v'),
  remedio: () => { const t = melhorRemedio(); if (t) usarRemedio(t); else avisarUmaVez('Sem remédios no cinto.'); },
  menu: () => { const m = document.getElementById('menuZoom'); m.hidden = !m.hidden; document.getElementById('painelSom').hidden = m.hidden; },
  trocar: () => teclaFalsa('q'),
  rolar: () => rolar(),
  rezar: () => teclaFalsa('r'),
  equip: () => teclaFalsa('i'),
  missoes: () => teclaFalsa('j'),
  atlas: () => teclaFalsa('m'),
  tomas: () => teclaFalsa('t'),
  cronica: () => teclaFalsa('c'),
  voltar: () => teclaFalsa('Escape'),
  zoomMais: () => mudarZoom(1.15),
  zoomMenos: () => mudarZoom(1 / 1.15)
};

(function prepararBotoes() {
  for (const b of document.querySelectorAll('#controles [data-acao]')) {
    const acao = ACOES_TOQUE[b.dataset.acao];
    let repetir = null;
    b.addEventListener('touchstart', (e) => {
      e.preventDefault(); e.stopPropagation();
      b.classList.add('apertado');
      acao();
      // Atacar segurado continua golpeando
      if (b.dataset.acao === 'atacar') repetir = setInterval(acao, 250);
    }, { passive: false });
    const soltar = () => { b.classList.remove('apertado'); clearInterval(repetir); };
    b.addEventListener('touchend', soltar);
    b.addEventListener('touchcancel', soltar);
    // no computador (para testar) também funciona com clique
    b.addEventListener('click', (e) => { if (!MODO.toque) acao(); });
  }
})();

// --- Toque no mapa e nas janelas -----------------------------------------
const toqueTela = { id: null, x0: 0, y0: 0, x: 0, y: 0, longo: null, direito: false };
let pinca = null;   // { d0, zoom0 } com dois dedos

// O cinto de remédios (desenhado no canvas): tocar num quadrado usa o remédio
function remedioNoPonto(x, y) {
  if (MODO.toque) return null;   // no celular o remédio tem botão próprio (js/hud.js, melhorRemedio)
  const tam = 46, gap = 8, total = 4 * tam + 3 * gap;
  const x0 = (canvas.width - total) / 2, yy = canvas.height - tam - 16;
  if (y < yy || y > yy + tam) return null;
  const i = Math.floor((x - x0) / (tam + gap));
  if (i < 0 || i > 3 || x - x0 - i * (tam + gap) > tam) return null;
  return String(i + 1);
}

canvas.addEventListener('touchstart', (e) => {
  if (!MODO.toque) return;
  e.preventDefault();
  if (e.touches.length === 2) {
    // dois dedos: zoom (cancela o toque de um dedo)
    if (toqueTela.id !== null) { clearTimeout(toqueTela.longo); mouseFalso('mouseup', toqueTela.x, toqueTela.y, 0); toqueTela.id = null; }
    const [a, b] = e.touches;
    pinca = { d0: Math.hypot(a.clientX - b.clientX, a.clientY - b.clientY), zoom0: zoom };
    return;
  }
  if (toqueTela.id !== null) return;
  const t = e.changedTouches[0];
  const tecla = remedioNoPonto(t.clientX, t.clientY);
  if (tecla && !janelaAberta()) { teclaFalsa(tecla); return; }
  Object.assign(toqueTela, { id: t.identifier, x0: t.clientX, y0: t.clientY, x: t.clientX, y: t.clientY, direito: false,
                              rolavel: null, rolando: false });
  mouseFalso('mousemove', t.clientX, t.clientY);
  // Sobre um texto que rola (js/rolagem.js): espera para ver se é arrasto ou toque
  const rol = areaRolavelEm(t.clientX, t.clientY);
  if (rol) { toqueTela.rolavel = rol; return; }
  mouseFalso('mousedown', t.clientX, t.clientY, 0);
  // Segurar parado com o equipamento ou a loja aberta = botão direito
  toqueTela.longo = setTimeout(() => {
    if ((inventarioAberto || lojaAberta) && Math.hypot(toqueTela.x - toqueTela.x0, toqueTela.y - toqueTela.y0) < 12) {
      mouseFalso('mouseup', toqueTela.x, toqueTela.y, 0);
      mouseFalso('mousedown', toqueTela.x, toqueTela.y, 2);
      toqueTela.direito = true;
      navigator.vibrate?.(20);
    }
  }, 450);
}, { passive: false });

canvas.addEventListener('touchmove', (e) => {
  if (!MODO.toque) return;
  e.preventDefault();
  if (pinca && e.touches.length >= 2) {
    const [a, b] = e.touches;
    const d = Math.hypot(a.clientX - b.clientX, a.clientY - b.clientY);
    zoom = Math.min(ZOOM_MAX, Math.max(ZOOM_MIN, pinca.zoom0 * d / pinca.d0));
    return;
  }
  for (const t of e.changedTouches) if (t.identifier === toqueTela.id) {
    if (toqueTela.rolavel) {
      // arrastar o texto: o dedo puxa o conteúdo
      if (!toqueTela.rolando && Math.abs(t.clientY - toqueTela.y0) > 8) toqueTela.rolando = true;
      if (toqueTela.rolando) {
        const r = toqueTela.rolavel;
        r.y = Math.min(r.max, Math.max(0, r.y - (t.clientY - toqueTela.y)));
      }
      toqueTela.x = t.clientX; toqueTela.y = t.clientY;
      continue;
    }
    toqueTela.x = t.clientX; toqueTela.y = t.clientY;
    mouseFalso('mousemove', t.clientX, t.clientY);
  }
}, { passive: false });

function fimDoToque(e) {
  if (!MODO.toque) return;
  e.preventDefault();
  if (e.touches.length < 2) pinca = null;
  for (const t of e.changedTouches) if (t.identifier === toqueTela.id) {
    clearTimeout(toqueTela.longo);
    if (toqueTela.rolavel) {
      // não arrastou: era um toque normal no texto
      if (!toqueTela.rolando && e.type === 'touchend') {
        mouseFalso('mousemove', toqueTela.x0, toqueTela.y0);
        mouseFalso('mousedown', toqueTela.x0, toqueTela.y0, 0);
        mouseFalso('mouseup', toqueTela.x0, toqueTela.y0, 0);
      }
      toqueTela.rolavel = null; toqueTela.rolando = false; toqueTela.id = null;
      continue;
    }
    mouseFalso('mouseup', t.clientX, t.clientY, toqueTela.direito ? 2 : 0);
    toqueTela.id = null;
  }
}
canvas.addEventListener('touchend', fimDoToque, { passive: false });
canvas.addEventListener('touchcancel', fimDoToque, { passive: false });

// Alguma janela por cima do jogo? (aí o cinto de remédios não responde ao toque)
function janelaAberta() {
  return !!(diarioAberto || cronicaAberta || inventarioAberto || lojaAberta || dialogo || menuOratorio || painelTomasAberto ||
            (typeof atlasAberto !== 'undefined' && atlasAberto) || (typeof menuItem !== 'undefined' && menuItem));
}

// --- Janelas abertas: tira os controles da frente ----------------------------
// (e acende os botões Missões/Crônica quando há novidade)
setInterval(() => {
  if (!MODO.toque) return;
  const aberto = janelaAberta();
  document.body.classList.toggle('atlas-aberto', typeof atlasAberto !== 'undefined' && atlasAberto);
  if (aberto) { document.getElementById('menuZoom').hidden = true; document.getElementById('painelSom').hidden = true; }
  // Falar aparece só perto de alguém (ou de um oratório)
  document.body.classList.toggle('perto-de-alguem', !aberto && !!(npcProximo() || (typeof oratorioProximo === 'function' && oratorioProximo()) ||
    (typeof interativosDoMapa === 'function' && interativosDoMapa().some((i) => Math.hypot(i.x - jogador.x, i.y - jogador.y) < (i.tipo === 'tumulo' ? 2.2 : 1.6)))));
  // remédio: quantos do que vai ser usado
  const rem = melhorRemedio();
  document.getElementById('toqueRemedioQtd').textContent = rem ? String(cinto[rem]) : '0';
  document.getElementById('toqueRemedio').classList.toggle('sem', !rem);
  // habilidade F: custo e se dá para usar
  ['', 'G', 'H'].forEach((sufixo, k) => {
    const h = habilidadeDoAtalho(k);
    const vale = h && arvoreValeAgora(INDICE_HABILIDADES[h.id].arvore);
    document.getElementById('toqueEspecial' + sufixo + 'Custo').textContent = h ? String(h.custo || '') : '';
    const btn = document.getElementById('toqueEspecial' + sufixo);
    const icone = h && typeof iconeDaHabilidadeURL === 'function' ? iconeDaHabilidadeURL(h.id) : '';
    if (btn.dataset.icone !== (h ? h.id : '')) {
      btn.dataset.icone = h ? h.id : '';
      btn.style.backgroundImage = icone ? `url(${icone})` : '';
      btn.style.backgroundSize = icone ? '78% 78%' : '';
      btn.style.backgroundPosition = 'center'; btn.style.backgroundRepeat = 'no-repeat';
      const svg = btn.querySelector('svg'); if (svg) svg.style.visibility = icone ? 'hidden' : '';
    }
    document.getElementById('toqueEspecial' + sufixo).classList.toggle('sem', !h || !vale || jogador.devocao < (h.custo || 0));
  });
  document.getElementById('toqueVirtude').classList.toggle('sem', !virtudeAtiva());
  document.body.classList.toggle('painel-aberto', aberto);
  document.getElementById('toqueMissoes').classList.toggle('novo', !!novidadeNasMissoes);
  document.getElementById('toqueTomas').classList.toggle('novo', !!(jogador.pontosAtributo || jogador.pontosHabilidade));
  if (typeof novidadeNaCronica !== 'undefined') document.getElementById('toqueCronica').classList.toggle('novo', !!novidadeNaCronica);
}, 150);

