// ===== js/admin.js =====
// =====================================================================
// MODO ADMIN: versão de teste, com senha, para explorar o jogo
// =====================================================================
// Na tela inicial, "Admin" pede a senha e o caminho. Começa com:
//   - todos os oratórios encontrados (viagem rápida para qualquer mapa)
//   - Tomás no nível máximo, com todos os pontos de atributo distribuídos
//     e todas as habilidades do caminho no máximo
//   - o melhor equipamento (Armas de Montgisard + lendários) e ouro de sobra
//   - o cinto cheio de remédios
// Salva num lugar separado do jogo normal: o jogo salvo de verdade não é tocado.
//
// A senha não fica escrita aqui: só o "hash" dela (SHA-256). Isto evita que
// alguém a leia no código, mas não é segurança de verdade: quem souber
// programar consegue ligar o modo admin pelo console do navegador.

const HASH_SENHA_ADMIN = 'b1fc90a4366b25b02e89039781a6d254085dc72d23a5a34a728da7a5a30c23ef';
const CHAVE_SALVO_ADMIN = 'cruz-de-montgisard-admin';

async function senhaAdminConfere(senha) {
  try {
    const dados = new TextEncoder().encode(senha);
    const h = await crypto.subtle.digest('SHA-256', dados);
    const hex = [...new Uint8Array(h)].map((b) => b.toString(16).padStart(2, '0')).join('');
    return hex === HASH_SENHA_ADMIN;
  } catch (e) {
    return false;
  }
}

// Prepara Tomás e o mundo para explorar. caminho: 'espada' | 'lanca' | 'duasmaos' | 'besta'
function ativarModoAdmin(caminho) {
  MODO.admin = true;
  CHAVE_SALVO = CHAVE_SALVO_ADMIN;          // salva à parte

  // história: o suficiente para nada ficar trancado
  Object.assign(flags, { caminho, cena2: true, ordemDeCarga: true, a3Rei: true });
  jogador.estilo = caminho;

  // nível máximo, atributos distribuídos
  jogador.nivel = NIVEL_MAXIMO;
  jogador.xp = xpTotalAte(NIVEL_MAXIMO);
  const pontos = (NIVEL_MAXIMO - 1) * PONTOS_POR_NIVEL;
  const peso = caminho === 'besta' ? { forca: 0.15, destreza: 0.45, vigor: 0.25, fe: 0.15 }
                                   : { forca: 0.4, destreza: 0.15, vigor: 0.3, fe: 0.15 };
  jogador.atributos = {};
  for (const [k, p] of Object.entries(peso)) jogador.atributos[k] = ATRIBUTO_INICIAL + Math.round(pontos * p);
  jogador.pontosAtributo = 0;

  // todas as habilidades de todas as árvores no máximo; nos atalhos, as do fim da árvore do caminho
  jogador.habilidades = {};
  for (const lista of Object.values(HABILIDADES)) for (const h of lista) jogador.habilidades[h.id] = maximoDe(h);
  jogador.pontosHabilidade = 0;
  jogador.versaoHabilidades = VERSAO_HABILIDADES;
  jogador.atalhos = HABILIDADES[ARVORE_DO_CAMINHO[caminho]].filter((h) => h.tipo === 'ativa').slice(-3).map((h) => h.id);
  jogador.virtude = 'auraFervor';

  // equipamento: as Armas de Montgisard e o melhor do resto
  const lend = (base) => { const it = criarItem(base, 'lendario'); return it.nome === baseDe(it).nome ? criarItem(base, 'raro') : it; };
  const armaBase = ARMA_DO_ESTILO[caminho];
  const umaMao = BASES_ARMAS[armaBase].maos === 1;
  jogador.armas = [lend(armaBase), criarItem(caminho === 'besta' ? 'espada' : 'bestaMao', 'raro')];
  jogador.escudos = [umaMao ? criarItem('escudoCruz', 'conjunto') : null, caminho === 'besta' ? criarItem('amendoa', 'raro') : null];
  jogador.armaAtiva = 0;
  jogador.equipamento = {
    elmo: criarItem('elmoGrande', 'conjunto'),
    armadura: criarItem('sobreveste', 'conjunto'),
    luvas: lend('manoplas'),
    botas: lend('botasCano'),
    cinto: criarItem('cintoCavaleiro', 'raro'),
    colar: lend('relicario'),
    anel1: lend('sinete'),
    anel2: criarItem('anelPrata', 'raro')
  };
  jogador.alforje = [];
  jogador.ouro = 9999999;
  recalcularAtributos();
  for (const r of Object.keys(cinto)) cinto[r] = maximoPorRemedio();
  jogador.vida = jogador.vidaMax;
  jogador.devocao = jogador.devocaoMax;

  // todos os oratórios encontrados
  for (const o of ORATORIOS) descobertos[o.id] = true;

  // começa na cruz do portão de Ascalão
  const inicio = ORATORIOS.find((o) => o.id === 'portao') || ORATORIOS[0];
  iniciarTransicao({ destino: inicio.mapa, chegada: inicio.chegada });
  avisar('Modo admin: todos os oratórios abertos (E num oratório para viajar).');
}

// Marca no canto da tela, para não confundir com o jogo de verdade
function desenharMarcaAdmin() {
  if (!MODO.admin) return;
  ctx.save();
  ctx.setTransform(1, 0, 0, 1, 0, 0);
  ctx.font = 'bold 12px Alegreya SC, Georgia, serif';
  ctx.fillStyle = 'rgba(232, 80, 60, 0.85)';
  ctx.textAlign = 'right';
  ctx.fillText('MODO ADMIN', canvas.width - 14, MODO.toque ? 70 : 22);
  ctx.restore();
}

// --- Tela inicial: o painel do admin -------------------------------------------
(function prepararAdmin() {
  const botao = document.getElementById('btnAdmin');
  if (!botao) return;
  const painel = document.getElementById('painelAdmin');
  const campo = document.getElementById('senhaAdmin');
  const erro = document.getElementById('erroAdmin');
  let caminho = 'espada';
  for (const b of painel.querySelectorAll('[data-caminho]')) {
    b.addEventListener('click', () => {
      caminho = b.dataset.caminho;
      for (const x of painel.querySelectorAll('[data-caminho]')) x.classList.toggle('ativo', x === b);
    });
  }
  botao.addEventListener('click', () => { painel.hidden = false; erro.hidden = true; campo.value = ''; setTimeout(() => campo.focus(), 50); });
  const entrar = async (toque) => {
    if (!(await senhaAdminConfere(campo.value))) { erro.hidden = false; campo.select(); return; }
    painel.hidden = true;
    escolherModo(toque, true);
    ativarModoAdmin(caminho);
  };
  document.getElementById('adminPc').addEventListener('click', () => entrar(false));
  document.getElementById('adminToque').addEventListener('click', () => entrar(true));
  campo.addEventListener('keydown', (e) => { if (e.key === 'Enter') entrar('ontouchstart' in window); });
})();

