const PACOTE_EFEITOS = {"aco":[0,9710],"baque":[9710,12890],"bau":[12890,22600],"beber":[22600,32049],"bencao":[32049,52208],"bloqueio":[52208,60351],"brado":[60351,90176],"carne":[90176,95968],"clique":[95968,97319],"couro":[97319,107029],"dor":[107029,111515],"dor_f":[111515,114956],"escada":[114956,139817],"fera_dor":[139817,152401],"fera_morte":[152401,165768],"frasco":[165768,171560],"gema":[171560,173956],"golpe1":[173956,177136],"golpe2":[177136,180577],"golpe3":[180577,183496],"grito_morte":[183496,196080],"grunhido":[196080,198999],"item_voa":[198999,204791],"livro":[204791,215546],"madeira":[215546,221860],"malha":[221860,226868],"metal":[226868,231093],"moedas":[231093,236885],"morte_tomas":[236885,253126],"nivel":[253126,279555],"objeto":[279555,283780],"pagina":[283780,288005],"pano":[288005,293013],"passo_couro1":[293013,296193],"passo_couro2":[296193,298850],"passo_couro3":[298850,302030],"passo_couro4":[302030,305210],"passo_eco1":[305210,313092],"passo_eco2":[313092,320974],"passo_eco3":[320974,329378],"passo_eco4":[329378,337521],"passo_metal1":[337521,340701],"passo_metal2":[340701,344142],"passo_metal3":[344142,347322],"passo_metal4":[347322,350502],"pesado":[350502,354727],"porta":[354727,361041],"postura":[361041,366311],"quebra":[366311,372364],"quebra2":[372364,383642],"sem_devocao":[383642,401450],"sino":[401450,447209],"tremor":[447209,462928],"virote":[462928,467936]};

