    if (typeof explorado === 'function' && !explorado(i.x, i.y)) continue;
    const p = mundoParaTela(i.x, i.y);
    const sx = (p.x + camera.x) * zoom, sy = (p.y + camera.y) * zoom - altPx(i.alt / 2) * zoom;
    const d = Math.hypot(mouse.x - sx, (mouse.y - sy) * 1.3);
