  // anda até o lado de cá (o tile livre mais perto)
  destino = i.tipo === 'tumulo' ? { x: i.x - 1.6, y: i.y } : { x: i.x, y: i.y + (i.tipo === 'alavanca' ? 0.9 : 0) };
