          nivel: (t.nivel || 1) + PENITENCIA.nivel, preparo: t.preparo * PENITENCIA.ritmo, recarga: t.recarga * PENITENCIA.ritmo,
          vel: t.vel * PENITENCIA.vel, chanceItem: Math.min(1, (t.chanceItem || 0) * PENITENCIA.item), penitencia: true,
          // experiência: o quádruplo da normal (o nível maior, sozinho, daria dezenas de vezes mais)
