// ===== js/combate_base.js =====
// =====================================================================
// BASE DO COMBATE: rolamento, aviso dos golpes, guarda e impacto
// =====================================================================
// Fase 1 do doc "Montgisard — novo combate, árvores por arma e missões":
//
//   ROLAMENTO  Shift no computador (ou o botão de rolar no celular): Tomás
//              rola uns 2,6 tiles na direção em que anda (ou para o cursor).
//              No começo do rolamento nenhum golpe pega. Recarga de 1,3 s.
//   AVISO      Todo inimigo que prepara um golpe desenha no chão a área que
//              vai acertar (um leque à frente; a linha da flecha, nos
//              arqueiros). O golpe vai na direção travada no começo do
//              preparo: quem sai do leque não é atingido.
//   GUARDA     Inimigos de escudo ou de armadura pesada têm uma barra de
//              guarda (amarela, embaixo da vida). Cada arma tira guarda de um
//              jeito (a maça muito, a besta pouco). Guarda zerada: o inimigo
//              cambaleia, perde o escudo e leva +50% de dano por 3 s.
//   IMPACTO    Uma pausa curtíssima a cada acerto de Tomás e a tela treme no
//              crítico, na guarda quebrada e no golpe forte que Tomás leva.

const ROLAMENTO = { dur: 0.42, dist: 2.6, recarga: 1.3, imune: 0.34 };
const GUARDA_DA_ARMA = { martelo: 2.1, arco: 0.6, maca: 2.0, acha: 1.8, machado: 1.6, espada: 1.0, faca: 0.6, lanca: 0.8, besta: 0.7, bestaMao: 0.6 };
const GUARDA_QUEBRADA_S = 3;
let pausaImpacto = 0;

jogador.rolamento = null;
jogador.recargaRolar = 0;
jogador.esquivando = 0;

// --- Rolamento -------------------------------------------------------------
function direcaoDoRolamento() {
  let telaDX = 0, telaDY = 0;
  if (teclas['w']) telaDY -= 1;
  if (teclas['s']) telaDY += 1;
  if (teclas['a']) telaDX -= 1;
  if (teclas['d']) telaDX += 1;
  const joy = typeof joystickAtivo === 'function' ? joystickAtivo() : null;
  if (joy) { telaDX = joy.x; telaDY = joy.y * 2; }
  if (telaDX || telaDY) return Math.atan2(telaDY - telaDX, telaDX + telaDY);
  if (destino) return Math.atan2(destino.y - jogador.y, destino.x - jogador.x);
  if (!MODO.toque && typeof pontoDoMouseNoMundo === 'function') {
    const p = pontoDoMouseNoMundo();
    if (Math.hypot(p.x - jogador.x, p.y - jogador.y) > 0.3) return Math.atan2(p.y - jogador.y, p.x - jogador.x);
  }
  return jogador.angulo;
}

function rolar() {
  if (jogador.rolamento || jogador.recargaRolar > 0 || jogador.vida <= 0) return;
  if (dialogo || transicao || menuOratorio || jogador.investida || jogador.giro) return;
  if (jogador.rezando) interromperOracao();
  const ang = direcaoDoRolamento();
  ataque = null; destino = null; alvoInimigo = null; npcAlvo = null;
  jogador.angulo = ang;
  jogador.rolamento = { t: 0, ang };
  jogador.esquivando = ROLAMENTO.imune;
  jogador.recargaRolar = ROLAMENTO.recarga * (1 + (bonus.rolarRecargaPct || 0) / 100);
  jogador.respostaPronta = true;        // Resposta (árvore da espada): o próximo golpe é crítico
  if (typeof tocar === 'function') tocar('pano', { vol: 0.5, rate: 1.2 });
  poeiraDoRolamento(4);
}

function poeiraDoRolamento(n) {
  if (typeof emitir !== 'function') return;
  emitir(n, () => ({ tipo: 'poeira', x: jogador.x + acaso(-0.2, 0.2), y: jogador.y + acaso(-0.2, 0.2), z: 0.05,
                     vx: acaso(-0.4, 0.4), vy: acaso(-0.4, 0.4), vz: 0.25, vida: 0, dur: acaso(0.5, 0.8),
                     cor: '226, 208, 176', tam: acaso(4, 7) }));
}

function atualizarRolamento(dt) {
  jogador.recargaRolar = Math.max(0, jogador.recargaRolar - dt);
  jogador.esquivando = Math.max(0, jogador.esquivando - dt);
  const r = jogador.rolamento;
  if (!r) return false;
  r.t += dt;
  const vel = ROLAMENTO.dist / ROLAMENTO.dur * (r.t < ROLAMENTO.dur * 0.7 ? 1.15 : 0.6);
  const bloqueado = (x, y) => colide(x, y, jogador.raio) || colideComOratorio(x, y, jogador.raio) || ehPortal(tileEm(x, y)) ||
                              colideComNpc(x, y, jogador.raio);
  const nx = jogador.x + Math.cos(r.ang) * vel * dt, ny = jogador.y + Math.sin(r.ang) * vel * dt;
  if (!bloqueado(nx, jogador.y)) jogador.x = nx;
  if (!bloqueado(jogador.x, ny)) jogador.y = ny;
  if (Math.random() < 0.35) poeiraDoRolamento(1);
  if (r.t >= ROLAMENTO.dur) { jogador.rolamento = null; poeiraDoRolamento(3); }
  return true;
}

window.addEventListener('keydown', (e) => {
  if (e.key === 'Shift' && !e.repeat) rolar();
});

// --- Aviso do golpe e golpe na direção travada --------------------------------
// (js/inimigos.js grava ini.angGolpe quando o preparo começa e só fere quem
// está dentro do leque: veja dentroDoGolpe)
const LEQUE_INIMIGO = Math.PI * 0.25;   // metade do leque (45° de cada lado)
function dentroDoGolpe(ini, alvo) {
  if (ini.angGolpe === undefined) return true;
  let dif = Math.abs(Math.atan2(alvo.y - ini.y, alvo.x - ini.x) - ini.angGolpe);
  if (dif > Math.PI) dif = 2 * Math.PI - dif;
  return dif <= LEQUE_INIMIGO || Math.hypot(alvo.x - ini.x, alvo.y - ini.y) < 0.6;
}

function desenharAvisosDeGolpe() {
  for (const ini of inimigos) {
    if (ini.morto || !(ini.preparo > 0) || ini.angGolpe === undefined) continue;
    if (typeof explorado === 'function' && !explorado(ini.x, ini.y)) continue;
    const t = ini.tipo;
    const prog = Math.max(0, Math.min(1, 1 - ini.preparo / t.preparo));
    const forte = t.flagAoMorrer || t.elite || ini.comandante;
    const centro = mundoParaTela(ini.x, ini.y);
    const cx = centro.x + camera.x, cy = centro.y + camera.y;
    const pt = (x, y) => { const p = mundoParaTela(x, y); return [p.x + camera.x, p.y + camera.y]; };
    ctx.save();
    if (t.comportamento === 'atirador') {
      // a linha da flecha
      const comp = Math.min(t.alcance / METROS_POR_TILE, 9);
      const [fx, fy] = pt(ini.x + Math.cos(ini.angGolpe) * comp, ini.y + Math.sin(ini.angGolpe) * comp);
      ctx.strokeStyle = `rgba(230, 70, 50, ${0.15 + 0.45 * prog})`;
      ctx.lineWidth = 1 + 1.5 * prog;
      ctx.setLineDash([6, 5]);
      ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(fx, fy); ctx.stroke();
    } else {
      // o leque do golpe, que enche conforme o golpe se aproxima
      const r = t.alcance / METROS_POR_TILE + t.raio + 0.2;
      const desenharLeque = (raio) => {
        ctx.beginPath(); ctx.moveTo(cx, cy);
        for (let i = 0; i <= 14; i++) {
          const a = ini.angGolpe - LEQUE_INIMIGO + (2 * LEQUE_INIMIGO * i) / 14;
          ctx.lineTo(...pt(ini.x + Math.cos(a) * raio, ini.y + Math.sin(a) * raio));
        }
        ctx.closePath();
      };
      desenharLeque(r);
      ctx.fillStyle = `rgba(200, 40, 30, ${forte ? 0.16 : 0.1})`; ctx.fill();
      ctx.strokeStyle = `rgba(255, 110, 80, ${0.25 + 0.4 * prog})`; ctx.lineWidth = 1; ctx.stroke();
      desenharLeque(r * prog);
      ctx.fillStyle = `rgba(230, 60, 40, ${(forte ? 0.32 : 0.22) * prog})`; ctx.fill();
    }
    ctx.restore();
  }
}

// --- Guarda ------------------------------------------------------------------
function prepararGuarda(ini) {
  if (ini.guardaMax !== undefined) return;
  const t = ini.tipo;
  const pesado = (t.escudo || 0) > 0 || (t.vida >= 90 && t.nivel >= 4 && !t.comportamento);
  ini.guardaMax = pesado ? Math.round(t.vida * (t.escudo ? 0.6 : 0.45)) : 0;
  ini.guarda = ini.guardaMax;
  ini.guardaQuebrada = 0;
  ini.semGolpe = 0;
}

function quebrarGuarda(ini) {
  ini.guarda = 0;
  ini.guardaQuebrada = GUARDA_QUEBRADA_S;
  ini.atordoado = Math.max(ini.atordoado || 0, 1.2);
  ini.preparo = 0;
  numeros.push({ x: ini.x, y: ini.y, altura: ini.tipo.altura + 0.4, texto: 'Guarda quebrada!', cor: '#ffd76a', tempo: 1.3, grande: true });
  if (typeof tremerTela === 'function') tremerTela(0.2, 5);
  if (typeof tocar === 'function') tocar('metal', { vol: 0.7, rate: 0.8 });
}

function atualizarGuardas(dt) {
  for (const ini of inimigos) {
    if (!ini.morto && ini.semDano !== undefined) ini.semDano += dt;
    if (ini.morto || !ini.guardaMax) continue;
    ini.semGolpe = (ini.semGolpe || 0) + dt;
    if (ini.guardaQuebrada > 0) {
      ini.guardaQuebrada -= dt;
      if (ini.guardaQuebrada <= 0) { ini.guardaQuebrada = 0; ini.guarda = ini.guardaMax * 0.5; }
    } else if (ini.semGolpe > 2.5) {
      ini.guarda = Math.min(ini.guardaMax, ini.guarda + ini.guardaMax * 0.12 * dt);
    }
  }
}

// --- Golpes de Tomás: guarda e impacto --------------------------------------------
const _ferirInimigoOrigBase = ferirInimigo;
