const _atualizarProjeteisOrigEl = atualizarProjeteis;
atualizarProjeteis = function (dt) {
  const potes = projeteis.filter((p) => p.nafta);
  _atualizarProjeteisOrigEl(dt);
  for (const p of potes) if (!projeteis.includes(p)) {
    chamasInimigas.push({ x: p.x, y: p.y, raio: 1.2, dps: Math.max(4, Math.round((p.origem ? p.origem.tipo.dano[1] : 10) * 0.5)), t: 0, dur: 3.5 });
    if (typeof tremerTela === 'function') tremerTela(0.08, 2);
    if (typeof tocar === 'function') tocar('quebra', { vol: 0.5 });
  }
};

// --- Tomás atingido: a parte de fogo ou de veneno do golpe ---
const _ferirJogadorOrigEl = ferirJogador;
ferirJogador = function (dano, origem) {
  const el = origem && origem.tipo && origem.tipo.elemento;
  if (!el || jogador.esquivando > 0) return _ferirJogadorOrigEl(dano, origem);
  // 60% do golpe é o corte ou a flecha; 40% é fogo ou veneno, que a armadura não segura
  const fisico = Math.max(1, Math.round(dano * 0.6));
  const r = _ferirJogadorOrigEl(fisico, origem);
  if (jogador.vida <= 0) return r;
  const elem = dano * 0.4 * (1 - resistenciaDe(el) / 100);
  if (el === 'veneno') envenenar(jogador, elem / DURACAO_VENENO * 1.5);
  else if (elem >= 1) {
    jogador.vida -= Math.round(elem);
    numeros.push({ x: jogador.x + 0.3, y: jogador.y, altura: jogador.altura + 0.2, texto: String(Math.round(elem)), cor: COR_FOGO, tempo: 0.9 });
    if (jogador.vida <= 0) morrerJogador();
  }
  return r;
};

// Veneno e chamas em Tomás, a cada quadro
const _atualizarJogadorOrigEl = atualizarJogador;
atualizarJogador = function (dt) {
  if (jogador.envenenado && jogador.vida > 0) atualizarVeneno(jogador, dt, () => morrerJogador());
  for (const f of chamasInimigas) {
    f.t += dt;
    if (jogador.vida > 0 && !(jogador.esquivando > 0) && Math.hypot(jogador.x - f.x, jogador.y - f.y) < f.raio + jogador.raio) {
      jogador.vida -= f.dps * (1 - resistenciaDe('fogo') / 100) * dt;
      f.acum = (f.acum || 0) + f.dps * dt;
      if (f.acum > 4) { numeros.push({ x: jogador.x, y: jogador.y, altura: jogador.altura, texto: String(Math.round(f.acum)), cor: COR_FOGO, tempo: 0.6 }); f.acum = 0; }
      if (jogador.vida <= 0) morrerJogador();
    }
    if (Math.random() < 0.6 && typeof emitir === 'function')
      emitir(1, () => ({ tipo: 'luz', x: f.x + acaso(-f.raio, f.raio) * 0.7, y: f.y + acaso(-f.raio, f.raio) * 0.7, z: 0.1,
                         vx: 0, vy: 0, vz: acaso(0.8, 1.8), vida: 0, dur: acaso(0.4, 0.8), cor: '255, 120, 40', tam: acaso(1, 2.4) }));
  }
  chamasInimigas = chamasInimigas.filter((f) => f.t < f.dur);
  return _atualizarJogadorOrigEl(dt);
};
// ao trocar de mapa, o fogo e o veneno ficam para trás
