const _desenharEfeitosDeHabilidadeOrigEl = desenharEfeitosDeHabilidade;
desenharEfeitosDeHabilidade = function () {
  _desenharEfeitosDeHabilidadeOrigEl();
  for (const f of chamasInimigas) {
    const p = mundoParaTela(f.x, f.y);
    const fade = Math.min(1, (f.dur - f.t) / 0.6, f.t / 0.15);
    ctx.beginPath();
    ctx.ellipse(p.x + camera.x, p.y + camera.y, meiaLargPx(f.raio * 4), meiaLargPx(f.raio * 4) / 2, 0, 0, Math.PI * 2);
    ctx.fillStyle = `rgba(255, 110, 30, ${0.28 * fade + 0.07 * Math.sin(performance.now() / 80)})`; ctx.fill();
  }
};

