  if (bonus.fogoPct && s.fogo) s.fogo = s.fogo.map((v) => Math.round(v * (1 + bonus.fogoPct / 100)));
  if (bonus.venenoPct && s.veneno) s.veneno = Math.round(s.veneno * (1 + bonus.venenoPct / 100));
