const _antesDoGolpeOrigArt = antesDoGolpe;
antesDoGolpe = function (ini, s) {
  const s2 = _antesDoGolpeOrigArt(ini, s);
  if (s.aliado) return s2;
  if (s2.sagradoExtra) {
    const x = Math.round(s2.sagradoExtra * (1 + (bonus.sagradoPct || 0) / 100));
    s2.sagrado = [(s2.sagrado ? s2.sagrado[0] : 0) + Math.ceil(x / 2), (s2.sagrado ? s2.sagrado[1] : 0) + x];
  }
  if (s2.detonaVeneno && ini.envenenado) {
    const resto = ini.envenenado.dpsTotal * Math.max(0, ini.envenenado.t);
    s2.dano = s2.dano.map((d) => Math.round(d * 1.5 + resto));
    ini.envenenado = null;
    numeros.push({ x: ini.x, y: ini.y, altura: ini.tipo.altura + 0.5, texto: 'Golpe mortal!', cor: COR_VENENO, tempo: 1.1, grande: true });
  }
  return s2;
};
const _ferirInimigoOrigArt = ferirInimigo;
