    ctx.beginPath(); ctx.arc(p.x + camera.x, p.y + camera.y - alto, a.e.grande ? 5 : 3.5, 0, Math.PI * 2); ctx.fill();
    if (a.e.impacto) { ctx.fillStyle = 'rgba(255, 160, 60, 0.9)'; ctx.beginPath(); ctx.arc(p.x + camera.x + 2, p.y + camera.y - alto - 3, 2, 0, Math.PI * 2); ctx.fill(); }
