  if (!info || info.arvore !== 'virtudes') return _motivoParaNaoAprenderOrigVir(id);
  const v = info.h.virtude;
  if (pontosEm(id) >= 5) return 'Já está no máximo.';
  if (jogador.nivel < NIVEL_DO_DEGRAU[v.degrau]) return `Pede nível ${NIVEL_DO_DEGRAU[v.degrau]}.`;
  const baixo = v.degrau > 0 && VIRTUDES.find((x) => x.caminho === v.caminho && x.degrau === v.degrau - 1);
  if (baixo && !pontosEm(baixo.id)) return `Pede um ponto em ${baixo.nome}.`;
  if (!jogador.pontosHabilidade) return 'Sem pontos de habilidade.';
