// Ao entrar nos mapas
function marcarMapaDoAto4() {
  const m = nomeDoMapaAtual();
  if (m === 'vau') { flags.foiAoVau = true; if (typeof renovarEstoque === 'function') renovarEstoque(); }
  if (m === 'pedreira') flags.foiAPedreira = true;
  if (m === 'banias') flags.foiABanias = true;
  if (m === 'marj') flags.foiAMarj = true;
  if (m === 'minas') flags.desceuMinas = true;
  if (m === 'campoReal' && flags.sapadorMorto) flags.escapouChastellet = true;
}

// --- Defesas: segurar um ponto até o último inimigo da onda cair ---
// mapa.defesas = [{ id, nome, x, y, texto, onda: [[tipo, dx, dy], ...] }]. Chegar perto solta a onda;
// quando todos caem, flags['def_' + id] fica marcada. Sair do mapa no meio desfaz a onda.
const RAIO_DEFESA = 4;
let defesaAtiva = null;   // { id, inimigos: [...] }
function atualizarDefesas() {
  const lista = (mapaAtual.defesas || []).filter((d) => !d.ativa || d.ativa());
  if (defesaAtiva) {
    if (!lista.some((d) => d.id === defesaAtiva.id)) { defesaAtiva = null; return; }
    if (defesaAtiva.inimigos.every((i) => i.morto)) {
      const d = lista.find((x) => x.id === defesaAtiva.id);
      flags['def_' + d.id] = true;
      defesaAtiva = null;
      avisar(d.texto);
      if (typeof tocar === 'function') tocar('sino', { vol: 0.5 });
    }
    return;
  }
  for (const d of lista) {
    if (flags['def_' + d.id] || Math.hypot(d.x - jogador.x, d.y - jogador.y) > RAIO_DEFESA) continue;
    const novos = d.onda.map(([tipo, dx, dy]) => {
      const t = TIPOS_INIMIGO[tipo];
      let x = d.x + dx, y = d.y + dy;
      const ruim = (px, py) => colide(px, py, 0.35) || ehPortal(tileEm(px, py)) || !acharCaminho(px, py, d.x, d.y);
      for (let k = 0; k < 20 && ruim(x, y); k++) { x = d.x + dx * (0.9 - k * 0.04) + (Math.random() - 0.5); y = d.y + dy * (0.9 - k * 0.04) + (Math.random() - 0.5); }
      for (let k = 0; k < 40 && ruim(x, y); k++) { const a = Math.random() * Math.PI * 2, r = 3 + Math.random() * 3; x = d.x + Math.cos(a) * r; y = d.y + Math.sin(a) * r; }
      if (ruim(x, y)) return null;           // nenhum lugar bom: esse não vem
      const ini = { tipo: t, x, y, casaX: x, casaY: y, vida: t.vida, estado: 'perseguindo', preparo: 0, recarga: Math.random(),
                    morto: false, tempoMorto: 0, flash: 0, aggroBatalha: true };
      inimigos.push(ini);
      return ini;
    }).filter(Boolean);
    defesaAtiva = { id: d.id, inimigos: novos };
    avisar(`${d.nome}: os bandidos atacam!`);
    break;
  }
}
const carrosSalvos = () => ['def_carro1', 'def_carro2', 'def_carro3'].filter((f) => flags[f]).length;

// As defesas ainda por fazer aparecem no chão como os pontos de observação
const _desenharPontosOrigA4 = desenharPontosDeObservacao;
desenharPontosDeObservacao = function (tempo) {
  _desenharPontosOrigA4(tempo);
  const pend = (mapaAtual.defesas || []).filter((d) => (!d.ativa || d.ativa()) && !flags['def_' + d.id] && (!defesaAtiva || defesaAtiva.id !== d.id));
  if (!pend.length) return;
  const salvo = mapaAtual.pontos;
  mapaAtual.pontos = pend.map((d) => ({ id: '__def_' + d.id, x: d.x, y: d.y, nome: d.nome }));
  try { _desenharPontosOrigA4(tempo); } finally { mapaAtual.pontos = salvo; }
};

let ultimoMapaA4 = null;
const _atualizarAto3OrigA4 = atualizarAto3;
atualizarAto3 = function () {
  _atualizarAto3OrigA4();
  const m = nomeDoMapaAtual();
  if (m !== ultimoMapaA4) { ultimoMapaA4 = m; defesaAtiva = null; marcarMapaDoAto4(); }
  if (!transicao) atualizarDefesas();
};

