// --- Hattin: o mato seco pega fogo à volta de Tomás enquanto a batalha dura ---
let tFogoHattin = 0;
function atualizarAto5(dt) {
  if (transicao) return;
  const m = nomeDoMapaAtual();
  if (m === 'hattin' && !flags.def_tenda && typeof chamasInimigas !== 'undefined') {
    tFogoHattin -= dt;
    if (tFogoHattin <= 0) {
      tFogoHattin = 4 + Math.random() * 3;
      for (let k = 0; k < 10; k++) {
        const a = Math.random() * Math.PI * 2, r = 2 + Math.random() * 4, x = jogador.x + Math.cos(a) * r, y = jogador.y + Math.sin(a) * r;
        if (!colide(x, y, 0.3)) { chamasInimigas.push({ x, y, raio: 1.6, dps: 12, t: 0, dur: 7 }); break; }
      }
    }
  }
  if (m === 'turan' && flags.def_coluna1 && flags.def_coluna2 && flags.def_coluna3) flags.colunaChegou = true;
  if (m === 'cresson') flags.foiACresson = true;
  if (m === 'turan') flags.foiATuran = true;
  if (m === 'hattin') flags.foiAHattin = true;
}
const _atualizarAto3OrigA5 = atualizarAto3;
atualizarAto3 = function () { _atualizarAto3OrigA5(); atualizarAto5(1 / 60); };

// --- Missões ---
