// --- Falas ---
// Depois do Vau, o rei aponta os anos que vêm (soma uma escolha à fala da Penitência)
(function () {
  const ini = DIALOGOS.rei3_depois.inicio;
  const desc = Object.getOwnPropertyDescriptor(ini, 'escolhas');
  const base = desc.get ? desc.get : () => desc.value;
  const ir5 = { texto: 'Seguir em frente: maio de 1187. (Ato V)', ir: 'anos' };
  Object.defineProperty(ini, 'escolhas', { get: () => (flags.fimAtoIV && !flags.a5Inicio ? [ir5, ...base()] : base()), configurable: true });
  DIALOGOS.rei3_depois.anos = {
    quem: 'Balduíno IV', texto: 'Não vou ver muitos invernos, Tomás. A lepra me come as mãos e os olhos. Quando eu me for, segura o reino com os que restarem. Promete.',
    fonte: 'Fato: Balduíno IV morreu em março de 1185, aos 24 anos', proximo: 'adeus'
  };
  DIALOGOS.rei3_depois.adeus = {
    quem: 'Balduíno IV', texto: 'Vai com Deus, Messire Tomás.',
    fonte: 'Ficção', efeito: { flag: 'a5Inicio', viajar: { destino: 'campoReal', chegada: { x: 20, y: 14 } },
      aviso: 'Maio de 1187. O rei leproso morreu há dois anos. Guido de Lusignan é rei, e o exército se junta em Séforis.' }
  };
})();

