;
// ===== js/lica.js =====
// =====================================================================
// A LIÇA: séries de ondas (como o Crucible do Grim Dawn), à parte da campanha
// =====================================================================
// De qualquer oratório (depois do fim do Ato I), Tomás pode ir à Liça que
// Balião mandou erguer no campo de Montgisard. Lá enfrenta séries de 20 ondas
// de mercenários, desertores e campeões pagos, cada onda mais dura; a cada
// 5 ondas vem um campeão de nome, e ele ergue um estandarte (um bônus que vale
// até o fim da série). Os inimigos acompanham o nível de Tomás. A experiência
// vem a cada inimigo; no fim, a bolsa: um baú com peças e ouro, melhor quanto
// mais longe ele chegar. Cair na Liça não leva ouro nem manda para a cidade:
// a série acaba e ele volta ao oratório de onde saiu, com o prêmio das ondas
// vencidas. Há três séries; a seguinte se abre vencendo a anterior.
// Entre as ondas, o armeiro da Liça conserta tudo (as séries são longas).
// Não muda nada na história (missões, flags) e vale também na Penitência.

const SERIES_LICA = [
  { id: 1, nome: 'Série do Escudeiro', vida: 1, dano: 1, nivel: 0,
    tipos: ['saqueador', 'veterano', 'beduino', 'arqueiro', 'hiena', 'infante', 'chacal'],
    chefes: ['veterano', 'hienaVelha', 'lobo', 'sunqur'] },
  { id: 2, nome: 'Série do Sargento', vida: 1.35, dano: 1.2, nivel: 3,
    tipos: ['desertor', 'besteiroDesertor', 'infante', 'batedorTurcomano', 'arqueiro', 'hiena', 'veterano'],
    chefes: ['rato', 'sunqur', 'corvo', 'arslan'] },
  { id: 3, nome: 'Série do Cavaleiro', vida: 1.8, dano: 1.45, nivel: 6,
    tipos: ['mameluco', 'lanceiroMameluco', 'arqueiroMameluco', 'guardaSultao', 'batedorTurcomano', 'hienaGruta'],
    chefes: ['corvo', 'arslan', 'sunqur', 'guardaSultao'] }
];
const ONDAS_DA_SERIE = 20;
const CENTRO_LICA = { x: 24, y: 20 };
const ESTANDARTES = [
  { id: 'templo', nome: 'Estandarte do Templo', efeitos: { danoPct: 20 }, desc: '+20% de dano' },
  { id: 'hospital', nome: 'Estandarte do Hospital', efeitos: { regenVida: 3 }, desc: '+3 de vida por segundo' },
  { id: 'ibelin', nome: 'Estandarte de Ibelin', efeitos: { defesaPct: 25 }, desc: '+25% de defesa' },
  { id: 'rei', nome: 'Estandarte do Rei', efeitos: { vidaPct: 15 }, desc: '+15% de vida' },
  { id: 'saoJorge', nome: 'Pendão de São Jorge', efeitos: { sagrado: 10 }, desc: '+5 a 10 de dano sagrado' },
  { id: 'antioquia', nome: 'Estandarte de Antioquia', efeitos: { tempoPct: -12 }, desc: 'golpes 12% mais rápidos' },
  { id: 'genova', nome: 'Bandeira de Gênova', efeitos: { resTodas: 25 }, desc: '+25% de resistência ao fogo e ao veneno' },
  { id: 'peregrino', nome: 'Bandeira do Peregrino', efeitos: { regenDevocao: 2, devocaoMax: 20 }, desc: '+20 de devoção e +2 por segundo' }
];

let lica = null;   // { serie, onda, fase: 'contagem'|'luta'|'pausa'|'fim', t, origem, estandartes, abates }
const emLica = () => !!lica;
function registroDaLica() { return jogador.lica || (jogador.lica = { melhor: {}, vencidas: {} }); }
const serieAberta = (id) => id === 1 || !!registroDaLica().vencidas[id - 1];
const licaLiberada = () => !!(flags.fimAtoI || (jogador.dificuldade || 0) >= 1 || (jogador.campanhas || 0) > 0);

// --- Entrar: pelo menu do oratório ---
const _abrirMenuOratorioOrigLica = abrirMenuOratorio;
abrirMenuOratorio = function (o) {
  _abrirMenuOratorioOrigLica(o);
  if (!licaLiberada() || emLica() || !menuOratorio) return;
  const sair = menuOratorio.opcoes.pop();
  menuOratorio.opcoes.push({ texto: 'A Liça (séries de ondas)...', acao: () => abrirMenuLica(o), fica: true }, sair);
};
function abrirMenuLica(o) {
  const reg = registroDaLica();
  const opcoes = SERIES_LICA.map((s) => {
    const aberta = serieAberta(s.id);
    const recorde = reg.melhor[s.id] ? ` · recorde: onda ${reg.melhor[s.id]}` : '';
    return { texto: aberta ? `${s.nome}${reg.vencidas[s.id] ? ' ✓' : ''}${recorde}` : `${s.nome} (vença a anterior)`,
             acao: aberta ? () => entrarNaLica(s.id, o) : () => abrirMenuLica(o), fica: !aberta };
  });
  opcoes.push({ texto: 'O que é a Liça?', acao: () => iniciarDialogo('lica_historia'), fica: false });
  opcoes.push(o ? { texto: '← Voltar', acao: () => abrirMenuOratorio(o), fica: true } : { texto: 'Sair', acao: () => {}, fica: false });
  menuOratorio = { oratorio: { nome: 'A Liça de Montgisard' }, opcoes, sob: -1 };
  if (!reg.viuHistoria) { reg.viuHistoria = true; menuOratorio = null; iniciarDialogo('lica_historia'); depoisDaHistoriaLica = () => abrirMenuLica(o); }
}
// Ao fim da história do arauto, o menu das séries volta (para quem entrou pela primeira vez)
let depoisDaHistoriaLica = null;
const _avancarDialogoOrigLica = avancarDialogo;
avancarDialogo = function () {
  _avancarDialogoOrigLica();
  if (!dialogo && depoisDaHistoriaLica) { const f = depoisDaHistoriaLica; depoisDaHistoriaLica = null; f(); }
};
// Entrada pela tela inicial ("A Liça", como o Crucible): o menu das séries, a partir do oratório salvo
function abrirLicaDaTelaInicial() {
  const d = lerJogoSalvo();
  const o = d && typeof ORATORIOS !== 'undefined' ? ORATORIOS.find((x) => x.id === d.oratorio) : null;
  abrirMenuLica(o || null);
}
function entrarNaLica(serie, o) {
  lica = { serie, onda: 0, fase: 'contagem', t: 5, estandartes: [], abates: 0,
           origem: { mapa: nomeDoMapaAtual(), x: o && o.chegada ? o.chegada.x : jogador.x, y: o && o.chegada ? o.chegada.y : jogador.y } };
  jogador.vida = jogador.vidaMax; jogador.devocao = jogador.devocaoMax;
  iniciarTransicao({ destino: 'campo', chegada: { ...CENTRO_LICA }, lica: true });
  avisar(`A Liça · ${SERIES_LICA[serie - 1].nome}`);
}

// No campo, durante a Liça: nada da batalha nem dos inimigos de sempre
const _iniciarBatalhaOrigLica = iniciarBatalha;
iniciarBatalha = function () {
  if (emLica()) { aliados = []; cruzBatalha = null; marcasDeCarga = []; inimigos = []; return; }
  return _iniciarBatalhaOrigLica();
};
const _criarInimigosDoMapaOrigLica = criarInimigosDoMapa;
criarInimigosDoMapa = function (nomeMapa) {
  _criarInimigosDoMapaOrigLica(nomeMapa);
  if (emLica() && nomeMapa === 'campo') { inimigos = []; aliados = []; cruzBatalha = null; }
};
// Sair do campo por uma passagem ou viajando: a série fica pela metade (sem a bolsa)
const _iniciarTransicaoOrigLica = iniciarTransicao;
iniciarTransicao = function (portal) {
  if (emLica() && !portal.lica && lica.fase !== 'fim') { avisar('Você deixou a Liça: a série acabou sem a bolsa.'); lica = null; }
  return _iniciarTransicaoOrigLica(portal);
};

// --- As ondas ---
function tipoDaLica(id, chefe) {
  const t = TIPOS_INIMIGO[id];
  const s = SERIES_LICA[lica.serie - 1];
  const alvo = Math.max(t.nivel || 1, (jogador.nivel || 1) + s.nivel);
  const k = Math.max(0, alvo - (t.nivel || 1));
  const o = lica.onda - 1;
  const mv = (1 + 0.16 * k) * s.vida * (1 + 0.05 * o) * (chefe ? 1.6 : 1);
  const md = (1 + 0.09 * k) * s.dano * (1 + 0.03 * o) * (chefe ? 1.2 : 1);
  // o "nível" que conta para a experiência e o saque é o da campanha (cada nível de inimigo vale 3 de Tomás)
  const nivelEq = Math.max(t.nivel || 1, ((jogador.nivel || 1) - 4 + s.nivel) / 3);
  const novo = { ...t, vida: Math.round(t.vida * mv), dano: t.dano.map((d) => Math.round(d * md)), nivel: nivelEq,
                 penitencia: true,                              // a Liça tem a própria escala (não soma a da Penitência)
                 flagAoMorrer: undefined, fala: undefined, unicoChefe: undefined, chefeLica: !!chefe,
                 chanceItem: chefe ? 1 : (t.chanceItem || 0) * 0.5, xpMult: (t.xpMult || 1) * (chefe ? 4 : 1), raridadeMinima: chefe ? 'refinado' : t.raridadeMinima };
  return novo;
}
function lugarLivreNaLica() {
  for (let k = 0; k < 40; k++) {
    const a = Math.random() * Math.PI * 2, r = 7 + Math.random() * 3;
    const x = jogador.x + Math.cos(a) * r, y = jogador.y + Math.sin(a) * r;
    if (!colide(x, y, 0.35) && !ehPortal(tileEm(x, y)) && tileEm(x, y) !== '#') return [x, y];
  }
  return [CENTRO_LICA.x + 6, CENTRO_LICA.y];
}
function soltarOndaDaLica() {
  lica.onda++;
  const s = SERIES_LICA[lica.serie - 1];
  const n = Math.min(22, 5 + Math.floor(lica.onda * 0.7) + lica.serie);
  const chefe = lica.onda % 5 === 0;
  inimigos = inimigos.filter((i) => !i.morto || i.tempoMorto < 8);
  const novo = (id, ehChefe) => {
    const [x, y] = lugarLivreNaLica();
    const t = tipoDaLica(id, ehChefe);
    const ini = { tipo: t, x, y, casaX: x, casaY: y, vida: t.vida, estado: 'perseguindo', preparo: 0, recarga: Math.random(),
                  morto: false, tempoMorto: 0, flash: 0, aggroBatalha: true, lica: true, penitencia: true };
    inimigos.push(ini);
    return ini;
  };
  for (let k = 0; k < n; k++) {
    const ini = novo(escolherUm(s.tipos), false);
    if (Math.random() < Math.min(0.25, 0.015 * lica.onda) && typeof tornarElite === 'function') { tornarElite(ini, 'campeao', `${ini.tipo.nome} campeão`); ini.tipo.penitencia = true; }
  }
  if (chefe) {
    const id = s.chefes[Math.min(s.chefes.length - 1, lica.onda / 5 - 1)];
    const c = novo(id, true);
    if (typeof tornarElite === 'function' && !TIPOS_INIMIGO[id].flagAoMorrer) { tornarElite(c, 'lider', `${c.tipo.nome}, campeão da Liça`); c.tipo.penitencia = true; c.tipo.chefeLica = true; }
    avisar(`Onda ${lica.onda}: ${c.tipo.nome}!`);
  } else avisar(`Onda ${lica.onda} de ${ONDAS_DA_SERIE}`);
  lica.fase = 'luta'; lica.tOnda = 0; lica.tPuxar = 0;
  if (typeof tocar === 'function') tocar('sino', { vol: 0.6, rate: 0.8 });
}

function atualizarLica(dt) {
  if (!lica || transicao || nomeDoMapaAtual() !== 'campo') return;
  if (lica.fase === 'contagem' || lica.fase === 'pausa') {
    if (menuOratorio || dialogo) return;
    lica.t -= dt;
    if (lica.t <= 0) soltarOndaDaLica();
  } else if (lica.fase === 'luta') {
    // na Liça o armeiro vigia de perto: nada chega a se partir no meio da onda
    for (const it of todosOsItensDoJogador()) if (it.durMax && it.dur < 1) { it.dur = 1; recalcularAtributos(); }
    const vivos = inimigosVivos();
    if (vivos.length) {
      // ninguém fica perdido longe da arena: quem se afasta demais volta para perto de Tomás
      lica.tLonge = (lica.tLonge || 0) + dt;
      if (lica.tLonge > 3) {
        lica.tLonge = 0;
        for (const i of vivos) if (Math.hypot(i.x - jogador.x, i.y - jogador.y) > 13) { [i.x, i.y] = lugarLivreNaLica(); i.casaX = i.x; i.casaY = i.y; i.estado = 'perseguindo'; }
      }
      // onda que se arrasta (alguém enroscado atrás de uma moita): os poucos que restam vêm para perto, à vista de Tomás
      lica.tOnda = (lica.tOnda || 0) + dt;
      if (lica.tOnda > 40 && (lica.tPuxar = (lica.tPuxar || 0) + dt) > 10) {
        lica.tPuxar = 0;
        const longe = vivos.filter((i) => Math.hypot(i.x - jogador.x, i.y - jogador.y) > 6 || !linhaLivre(jogador.x, jogador.y, i.x, i.y, 0.3));
        for (const i of longe.slice(0, 3)) {
          for (let k = 0; k < 40; k++) {
            const ang = Math.random() * Math.PI * 2, r = 2.5 + Math.random() * 2, x = jogador.x + Math.cos(ang) * r, y = jogador.y + Math.sin(ang) * r;
            if (!colide(x, y, 0.35) && !ehPortal(tileEm(x, y)) && linhaLivre(jogador.x, jogador.y, x, y, 0.3)) { i.x = x; i.y = y; i.casaX = x; i.casaY = y; i.estado = 'perseguindo'; break; }
          }
        }
      }
      return;
    }
    if (lica.onda >= ONDAS_DA_SERIE) { fimDaLica(true); return; }
    lica.fase = 'pausa'; lica.t = 6;
    // entre as ondas, o armeiro da Liça acerta as armas e a armadura
    for (const it of todosOsItensDoJogador()) if (it.durMax) it.dur = it.durMax;
    recalcularAtributos();
    jogador.vida = Math.min(jogador.vidaMax, jogador.vida + jogador.vidaMax * 0.25);
    jogador.devocao = Math.min(jogador.devocaoMax, jogador.devocao + jogador.devocaoMax * 0.25);
    const reg = registroDaLica();
    reg.melhor[lica.serie] = Math.max(reg.melhor[lica.serie] || 0, lica.onda);
    avisar(`Onda ${lica.onda} vencida.`);
    if (lica.onda % 5 === 0) escolherEstandarte();
  }
}
const _matarInimigoOrigLica = matarInimigo;
matarInimigo = function (ini) {
  const vivo = !ini.morto;
  _matarInimigoOrigLica(ini);
  if (vivo && ini.lica && lica) lica.abates++;
};

// A cada 5 ondas: um estandarte entre três (vale até o fim da série)
function escolherEstandarte() {
  const livres = ESTANDARTES.filter((e) => !lica.estandartes.includes(e.id));
  const tres = [];
  while (tres.length < 3 && livres.length) tres.push(livres.splice(Math.floor(Math.random() * livres.length), 1)[0]);
  menuOratorio = {
    oratorio: { nome: 'Erga um estandarte' }, sob: -1, pergunta: true,
    opcoes: tres.map((e) => ({ texto: `${e.nome}: ${e.desc}`, acao: () => { lica.estandartes.push(e.id); recalcularAtributos(); avisar(e.nome); } }))
  };
}
const _bonusDasMasmorrasOrigLica = bonusDasMasmorras;
bonusDasMasmorras = function () {
  const b = { ..._bonusDasMasmorrasOrigLica() };
  if (lica) for (const id of lica.estandartes) {
    const e = ESTANDARTES.find((x) => x.id === id);
    for (const [k, v] of Object.entries(e.efeitos)) b[k] = (b[k] || 0) + v;
  }
  return b;
};

// --- O fim: a bolsa da Liça ---
function fimDaLica(venceu) {
  const s = lica.serie;
  const vencidas = venceu ? ONDAS_DA_SERIE : Math.max(0, lica.onda - 1);
  const reg = registroDaLica();
  reg.melhor[s] = Math.max(reg.melhor[s] || 0, vencidas);
  if (venceu) reg.vencidas[s] = true;
  lica.fase = 'fim';
  // a bolsa: peças (mais e melhores quanto mais longe), ouro e, vencendo, uma chance de lendária
  const pecas = Math.floor(vencidas / 4) + (venceu ? 2 : 0);
  const minima = vencidas >= 20 ? 'raro' : vencidas >= 10 ? 'refinado' : null;
  const ouro = Math.round(vencidas * 40 * s * (1 + (jogador.nivel || 1) / 10));
  const premio = [];
  for (let k = 0; k < pecas; k++) {
    const it = gerarItemAleatorio(minima);
    premio.push(it);
  }
  if (venceu && Math.random() < 0.25 * s) {
    const lend = LENDARIOS.filter((l) => !l.unico);
    if (lend.length) { const l = escolherUm(lend); const it = criarItem(l.base, 'comum'); Object.assign(it, { raridade: 'lendario', nome: l.nome, efeitos: { ...l.efeitos }, texto: l.texto }); premio.push(it); }
  }
  jogador.ouro += ouro;
  const volta = lica.origem;
  lica.premio = { pecas: premio, ouro, vencidas, venceu };
  // as peças vão para o alforje (o que não couber, para o baú)
  for (const it of premio) {
    if (jogador.alforje.length < TAMANHO_ALFORJE) jogador.alforje.push(it);
    else { if (!Array.isArray(jogador.bau)) jogador.bau = []; jogador.bau.push(it); }
  }
  const titulo = venceu ? `${SERIES_LICA[s - 1].nome} vencida!` : `A Liça acabou na onda ${lica.onda}`;
  menuOratorio = {
    oratorio: { nome: titulo }, sob: -1, pergunta: true,
    opcoes: [{ texto: `A bolsa: ${ouro} de ouro e ${premio.length} peça(s)${premio.some((p) => p.raridade === 'lendario') ? ', uma delas lendária!' : ''} · Voltar`,
               acao: () => { const destinoLica = volta; lica = null; iniciarTransicao({ destino: destinoLica.mapa, chegada: { x: destinoLica.x, y: destinoLica.y }, renascer: true }); recalcularAtributos(); } }]
  };
  if (typeof tocar === 'function') tocar(venceu ? 'nivel' : 'sino', { vol: 0.8 });
}
// Cair na Liça: acaba a série (sem perder ouro e sem ir para a cidade)
const _morrerJogadorOrigLica = morrerJogador;
morrerJogador = function () {
  if (!lica || lica.fase === 'fim') return _morrerJogadorOrigLica();
  jogador.vida = Math.max(1, Math.round(jogador.vidaMax * 0.3));
  ataque = null; alvoInimigo = null; destino = null;
  for (const i of inimigos) { i.preparo = 0; i.atordoado = 99; }
  fimDaLica(false);
};

// --- Ligações ---
const _atualizarInimigosOrigLica = atualizarInimigos;
atualizarInimigos = function (dt) { _atualizarInimigosOrigLica(dt); atualizarLica(dt); };

// Quadro no alto da tela
function desenharHudDaLica() {
  if (!lica || nomeDoMapaAtual() !== 'campo' || transicao) return;
  const s = SERIES_LICA[lica.serie - 1];
  const vivos = inimigosVivos().length;
  const w = Math.min(470, canvas.width - 24), x = (canvas.width - w) / 2, y = 10, h = 62;
  ctx.save();
  ctx.fillStyle = 'rgba(18, 13, 9, 0.82)'; ctx.fillRect(x, y, w, h);
  ctx.strokeStyle = 'rgba(201, 162, 90, 0.8)'; ctx.strokeRect(x + 0.5, y + 0.5, w - 1, h - 1);
  ctx.textAlign = 'center';
  ctx.font = 'bold 15px Alegreya, Georgia, serif'; ctx.fillStyle = '#e8b931';
  ctx.fillText(`A Liça · ${s.nome}`, canvas.width / 2, y + 20);
  ctx.font = '13px Alegreya, Georgia, serif'; ctx.fillStyle = '#efe7d6';
  const linha = lica.fase === 'contagem' ? `A primeira onda entra em ${Math.ceil(lica.t)}…`
    : lica.fase === 'pausa' ? `Onda ${lica.onda} vencida · a próxima em ${Math.ceil(lica.t)}…`
    : lica.fase === 'fim' ? 'A bolsa está no alforje.'
    : `Onda ${lica.onda} de ${ONDAS_DA_SERIE} · inimigos de pé: ${vivos}`;
  ctx.fillText(linha, canvas.width / 2, y + 38);
  ctx.font = '12px Alegreya, Georgia, serif'; ctx.fillStyle = '#b9ad94';
  const est = lica.estandartes.map((id) => ESTANDARTES.find((e) => e.id === id).nome.replace(/^(Estandarte|Pendão|Bandeira) d[eoa]s? /, '')).join(', ');
  ctx.fillText(`Abates: ${lica.abates}${est ? ` · Estandartes: ${est}` : ''}`, canvas.width / 2, y + 54);
  ctx.restore();
}
const _desenharHudDaBatalhaOrigLica = desenharHudDaBatalha;
desenharHudDaBatalha = function () { if (lica) return desenharHudDaLica(); return _desenharHudDaBatalhaOrigLica(); };

// --- A história da Liça ---
DIALOGOS.lica_historia = {
  inicio: {
    quem: 'Arauto da Liça',
    texto: 'A liça é o campo cercado onde os cavaleiros se medem. Nas terras dos francos, no norte da França, nasceram neste século os torneios: grupos de cavaleiros lutando em campo aberto, a cavalo e a pé, e quem era vencido pagava o resgate com as armas e o cavalo.',
    fonte: 'Fato: os torneios do século XII (a vida de Guilherme Marechal conta muitos deles, nas décadas de 1160 a 1180)',
    proximo: 'igreja'
  },
  igreja: {
    quem: 'Arauto da Liça',
    texto: 'A Igreja os condenava. Os concílios de Clermont, em 1130, e de Latrão, em 1139, proibiram essas "feiras detestáveis", e quem morria num torneio ficava sem sepultura cristã. Mesmo assim, os cavaleiros não deixavam de ir.',
    fonte: 'Fato: Concílio de Clermont (1130) e cânone 14 do II Concílio de Latrão (1139)',
    proximo: 'balian'
  },
  balian: {
    quem: 'Arauto da Liça',
    texto: 'Depois de Montgisard, Messire Balião mandou cercar um pedaço do campo para que os que sobreviveram não perdessem a mão. Contra eles vêm mercenários, desertores e campeões turcomanos, pagos a peso de prata, em séries de vinte ondas, cada uma mais dura que a outra.',
    fonte: 'Ficção',
    proximo: 'regras'
  },
  regras: {
    quem: 'Arauto da Liça',
    texto: 'A cada cinco ondas, um campeão de nome, e tu ergues um estandarte. Quem aguenta até o fim leva a bolsa inteira; quem cai leva o que ganhou até ali, e ninguém aqui morre sem confissão. Vence uma série e a seguinte se abre.',
    fonte: 'Ficção'
  }
};

;
// ===== js/main.js =====
// =====================================================================
// MAIN: o loop do jogo, que junta tudo
// =====================================================================
// A cada quadro (~60 por segundo): atualiza a lógica e desenha a tela.

function atualizar(dt) {
  // Pausa do impacto (js/combate_base.js): o mundo para por um instante a cada acerto
  if (typeof pausaImpacto !== 'undefined' && pausaImpacto > 0) {
    pausaImpacto -= dt;
    atualizarEfeitos(dt * 0.2);
    return;
  }
  atualizarRecuperacao(dt); // vida, devoção, números e avisos
  atualizarProgresso(dt);   // brilho de nível e bônus que mudam com o tempo
  atualizarMissoes();       // percebe missões novas, avançadas ou concluídas
  atualizarCronica();       // páginas novas da Crônica
  atualizarAto3();          // a fuga do sultão
  atualizarNevoa();
  atualizarSom();           // música e ambiente do lugar, passos (js/som.js)         // descobre o mapa em volta de Tomás (js/nevoa.js)

  // Durante a troca de mapa, nada se move
  if (transicao) {
    atualizarTransicao(dt);
    return;
  }
  // Loja pedida na conversa: abre assim que a conversa termina
  if (!dialogo && lojaPendente) { abrirLoja(lojaPendente); lojaPendente = null; }
  if (!dialogo && viagemPendente) { iniciarTransicao(viagemPendente); viagemPendente = null; }
  // Durante uma conversa, só o texto anda
  if (dialogo) {
    atualizarDialogo(dt);
    return;
  }
  // Com o menu do oratório ou o diário de missões aberto, o mundo espera
  marcarLugarVisitado();   // para o atlas (js/atlas.js)
  if (menuOratorio || diarioAberto || lojaAberta || cronicaAberta || atlasAberto || painelTomasAberto || aberturaAberta) return;

  atualizarRemedios(dt);
  atualizarOracao(dt);
  atualizarBencao(dt);
  atualizarHabilidades(dt); // giro, investida, posturas
  atualizarVirtudes(dt);
  atualizarSantuario(dt);   // paz das igrejas e das cruzes
  atualizarEfeitos(dt);     // faíscas, poeira, rastros
  atualizarJogador(dt);
  atualizarAtaque(dt);
  atualizarProjeteis(dt);
  atualizarInimigos(dt);
  atualizarCompanheiro(dt);
  atualizarNpcs();
  atualizarItens();
  atualizarAchados();       // quebrar jarros, revistar corpos
  if (typeof atualizarBau === "function") atualizarBau();   // o baú fecha quando Tomás se afasta
  atualizarMasmorras(dt);   // armadilhas, grade, falas dos chefes (js/masmorras.js)
  atualizarPontosDeObservacao();
  atualizarOratorios();
  atualizarOratorioAlvo();
}

function desenhar(tempo) {
  const tilesDesenhados = desenharMundoComVisual(tempo);
  desenharTextosDoMundo();
  desenharInterface(tilesDesenhados);
  if (typeof desenharHudDaBatalha === 'function') desenharHudDaBatalha();   // quadro da batalha de Montgisard
  desenharDialogo();
  desenharMenuOratorio();
  desenharBotaoMissoes(tempo);
  desenharBotaoCronica(tempo);
  desenharDiario();
  desenharPainelTomas();
  desenharCronica();
  desenharDicaDoHud();      // dicas do painel de baixo, por cima de tudo
  desenharTransicao();
  desenharMarcaAdmin();
}

// "dt" é quanto tempo passou desde o último quadro, em segundos.
// Multiplicar velocidades por dt faz o jogo rodar igual em PCs rápidos e lentos.
let tempoAnterior = performance.now();

function loop(tempoAtual) {
  const dt = Math.min((tempoAtual - tempoAnterior) / 1000, 0.1);
  tempoAnterior = tempoAtual;
  atualizar(dt);
  desenhar(tempoAtual);
  requestAnimationFrame(loop);
}

recalcularAtributos(); // vida e devoção máximas com o equipamento inicial
carregarJogo();   // continua do último oratório, se houver jogo salvo
aoEntrarNoMapa(); // prepara o primeiro mapa
requestAnimationFrame(loop);

;
// ===== js/pausa.js =====
// =====================================================================
// PAUSA: Esc (ou o botão ❚❚) para o jogo e abre o menu de pausa
// =====================================================================
// Continuar, salvar e voltar ao menu principal (a tela dos personagens),
// ou voltar sem salvar. O jogo salvo continua do último oratório por onde
// Tomás passou (como no Diablo 2: volta-se ao ponto de viagem).

let jogoPausado = false;
let ultimoOratorioId = null;
try { const d = lerJogoSalvo(); if (d && d.oratorio) ultimoOratorioId = d.oratorio; } catch (e) {}

// O mundo para enquanto a pausa está aberta; e guarda o último oratório visitado
const _atualizarOrigPausa = atualizar;
atualizar = function (dt) {
  if (jogoPausado) return;
  _atualizarOrigPausa(dt);
  const o = typeof oratorioProximo === 'function' && oratorioProximo();
  if (o) ultimoOratorioId = o.id;
};

function abrirPausa() {
  if (jogoPausado || document.getElementById('inicio').style.display !== 'none') return;
  jogoPausado = true;
  const o = ORATORIOS.find((x) => x.id === ultimoOratorioId);
  document.getElementById('pausaOratorio').textContent = o
    ? `Ao salvar, você continua depois neste oratório: ${T(o.nome)}.` : 'Ainda não passou por um oratório: só dá para sair sem salvar.';
  document.getElementById('pausaSalvar').disabled = !o;
  document.getElementById('pausa').hidden = false;
  document.getElementById('pausaContinuar').focus();
}
function fecharPausa() {
  jogoPausado = false;
  document.getElementById('pausa').hidden = true;
  tempoAnterior = performance.now();
}
function salvarNoUltimoOratorio() {
  const o = ORATORIOS.find((x) => x.id === ultimoOratorioId);
  if (!o) return false;
  const orig = oratorioProximo;
  oratorioProximo = () => o;
  try { salvarJogo(); } finally { oratorioProximo = orig; }
  return true;
}
function irAoMenuPrincipal(salvar) {
  if (salvar) salvarNoUltimoOratorio();
  location.reload();
}

// Esc com nada aberto: pausa (ouvido antes dos outros, que fecham janelas com Esc)
window.addEventListener('keydown', (e) => {
  if (e.key !== 'Escape') return;
  if (jogoPausado) { e.preventDefault(); e.stopImmediatePropagation(); fecharPausa(); return; }
  const aberto = (typeof janelaAberta === 'function' && janelaAberta()) || (typeof bauAberto !== 'undefined' && bauAberto) ||
    (typeof aberturaAberta !== 'undefined' && aberturaAberta) || !document.getElementById('caminho').hidden;
  if (!aberto) { e.preventDefault(); e.stopImmediatePropagation(); abrirPausa(); }
}, true);
// Com a pausa aberta, nenhuma outra tecla chega ao jogo
window.addEventListener('keydown', (e) => { if (jogoPausado && e.key !== 'Escape' && e.key !== 'Tab' && e.key !== 'Enter' && e.key !== ' ') e.stopImmediatePropagation(); }, true);

document.getElementById('btnPausa').addEventListener('click', abrirPausa);
document.getElementById('pausaContinuar').addEventListener('click', fecharPausa);
document.getElementById('pausaSalvar').addEventListener('click', () => irAoMenuPrincipal(true));
document.getElementById('pausaSair').addEventListener('click', () => irAoMenuPrincipal(false));
if (typeof ACOES_TOQUE !== 'undefined') ACOES_TOQUE.pausa = abrirPausa;
// Sair da aba sem querer também pausa
document.addEventListener('visibilitychange', () => { if (document.hidden && !jogoPausado && document.getElementById('inicio').style.display === 'none') abrirPausa(); });

// --- A abertura do estúdio (o selo, no index.html): some sozinha; clique ou tecla pula.
// Só uma vez por sessão (voltar ao menu pela pausa não mostra de novo).
(function () {
  const selo = document.getElementById('selo');
  if (!selo) return;
  let visto = false;
  try { visto = !!sessionStorage.getItem('montgisard_selo'); sessionStorage.setItem('montgisard_selo', '1'); } catch (e) {}
  if (visto) { selo.remove(); return; }
  const pular = () => { selo.classList.add('pular'); setTimeout(() => selo.remove(), 400); window.removeEventListener('keydown', pular, true); };
  selo.addEventListener('click', pular);
  window.addEventListener('keydown', pular, true);
  setTimeout(() => { if (selo.isConnected) selo.remove(); window.removeEventListener('keydown', pular, true); }, 5800);
})();

;
